from (values
(374907,41657,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Zug soll genau pünktlich am Bahnsteig ...'::text,'angekommen sein'::text,'ankommen'::text,'ankommend'::text,'Der Zug soll genau pünktlich am Bahnsteig angekommen sein.'::text),
(374911,41657,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Кажуть, що потяг ... на платформу точно вчасно.'::text,'прибув'::text,'прибуває'::text,'прибуваючи'::text,'Кажуть, що потяг прибув на платформу точно вчасно.'::text),
(374910,41657,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Se dice que el tren ... al andén justo a tiempo.'::text,'ha llegado'::text,'llega'::text,'llegando'::text,'Se dice que el tren ha llegado al andén justo a tiempo.'::text),
(374909,41657,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Selon les infos, le train ... à quai pile à l''heure.'::text,'est arrivé'::text,'arrive'::text,'arrivant'::text,'Selon les infos, le train est arrivé à quai pile à l''heure.'::text),
(374912,41657,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Trenin perona tam vaktinde ... bildiriliyor.'::text,'vardığı'::text,'varması'::text,'varırken'::text,'Trenin perona tam vaktinde vardığı bildiriliyor.'::text),
(374913,41657,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A hírek szerint a vonat pontosan időben ... a peronra.'::text,'megérkezett'::text,'megérkezik'::text,'érkezve'::text,'A hírek szerint a vonat pontosan időben megérkezett a peronra.'::text),
(374916,41658,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ihre Freunde schlugen ein ... am Ende des Bahnsteigs vor.'::text,'Treffen'::text,'treffen'::text,'trafen'::text,'Ihre Freunde schlugen ein Treffen am Ende des Bahnsteigs vor.'::text),
(374920,41658,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Її друзі запропонували ... в кінці платформи.'::text,'зустрітися'::text,'зустрітися'::text,'зустрілися'::text,'Її друзі запропонували зустрітися в кінці платформи.'::text),
(374919,41658,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sus amigos propusieron ... al final del andén.'::text,'verse'::text,'verse'::text,'se vieron'::text,'Sus amigos propusieron verse al final del andén.'::text),
(374918,41658,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ses amis ont proposé ... au bout du quai.'::text,'de se retrouver'::text,'de se retrouver'::text,'se sont retrouvés'::text,'Ses amis ont proposé de se retrouver au bout du quai.'::text),
(374921,41658,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Arkadaşları peronun sonunda ... önerdi.'::text,'buluşmayı'::text,'buluşmayı'::text,'buluştular'::text,'Arkadaşları peronun sonunda buluşmayı önerdi.'::text),
(374922,41658,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A barátai azt javasolták, hogy ... a peron végén.'::text,'találkozzanak'::text,'találkozni'::text,'találkoztak'::text,'A barátai azt javasolták, hogy találkozzanak a peron végén.'::text),
(374925,41659,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ihre Freunde ... schon eine Weile am Bahnsteig gewartet haben, denn sie rannten sofort zu ihr.'::text,'müssen'::text,'sollten'::text,'müssen'::text,'Ihre Freunde müssen schon eine Weile am Bahnsteig gewartet haben, denn sie rannten sofort zu ihr.'::text),
(374929,41659,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Її друзі ... на платформі вже якийсь час, бо одразу підбігли до неї.'::text,'напевно чекали'::text,'мали б чекати'::text,'напевно чекають'::text,'Її друзі напевно чекали на платформі вже якийсь час, бо одразу підбігли до неї.'::text),
(374928,41659,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sus amigos ... esperando en el andén un buen rato, porque corrieron hacia ella enseguida.'::text,'debieron de estar'::text,'deberían haber estado'::text,'deben de estar'::text,'Sus amigos debieron de estar esperando en el andén un buen rato, porque corrieron hacia ella enseguida.'::text),
(374927,41659,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ses amis ... attendre sur le quai depuis un moment, car ils ont couru vers elle tout de suite.'::text,'devaient'::text,'auraient dû'::text,'doivent'::text,'Ses amis devaient attendre sur le quai depuis un moment, car ils ont couru vers elle tout de suite.'::text),
(374930,41659,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Arkadaşları bir süredir peronda ..., çünkü hemen ona koştular.'::text,'bekliyor olmalıydı'::text,'beklemeleri gerekirdi'::text,'bekliyor olmalı'::text,'Arkadaşları bir süredir peronda bekliyor olmalıydı, çünkü hemen ona koştular.'::text),
(374931,41659,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A barátai már egy ideje ... a peronon, mert azonnal odaszaladtak hozzá.'::text,'biztosan vártak'::text,'várniuk kellett volna'::text,'biztosan várnak'::text,'A barátai már egy ideje biztosan vártak a peronon, mert azonnal odaszaladtak hozzá.'::text),
(374934,41660,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Erst als sich die Türen öffneten, ... sie mit ihrem Koffer auf den Bahnsteig.'::text,'trat'::text,'trat'::text,'trat'::text,'Erst als sich die Türen öffneten, trat sie mit ihrem Koffer auf den Bahnsteig.'::text),
(374938,41660,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Лише коли двері відчинилися, ... на платформу зі своєю валізою.'::text,'вона вийшла'::text,'вона вийшла'::text,'вона вийшла'::text,'Лише коли двері відчинилися, вона вийшла на платформу зі своєю валізою.'::text),
(374937,41660,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Solo cuando se abrieron las puertas ... al andén con su maleta.'::text,'bajó'::text,'bajó'::text,'bajó'::text,'Solo cuando se abrieron las puertas bajó al andén con su maleta.'::text),
(374936,41660,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ce n''est qu''à l''ouverture des portes qu''elle ... sur le quai avec sa valise.'::text,'est descendue'::text,'est descendue'::text,'est descendue'::text,'Ce n''est qu''à l''ouverture des portes qu''elle est descendue sur le quai avec sa valise.'::text),
(374939,41660,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ancak kapılar açıldığında bavuluyla perona ...'::text,'indi'::text,'indi'::text,'indi'::text,'Ancak kapılar açıldığında bavuluyla perona indi.'::text),
(374940,41660,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csak amikor kinyíltak az ajtók, ... le a peronra a bőröndjével.'::text,'lépett'::text,'lépett'::text,'lépett'::text,'Csak amikor kinyíltak az ajtók, lépett le a peronra a bőröndjével.'::text),
(374943,41661,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ließ ihre Freunde sie am Ende des Bahnsteigs ...'::text,'abholen'::text,'abzuholen'::text,'abgeholt'::text,'Sie ließ ihre Freunde sie am Ende des Bahnsteigs abholen.'::text),
(374947,41661,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона домовилася, щоб друзі ... її в кінці платформи.'::text,'зустріли'::text,'зустріли'::text,'зустріли'::text,'Вона домовилася, щоб друзі зустріли її в кінці платформи.'::text),
(374946,41661,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hizo que sus amigos la ... al final del andén.'::text,'esperaran'::text,'esperar'::text,'esperaron'::text,'Hizo que sus amigos la esperaran al final del andén.'::text),
(374945,41661,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle a fait en sorte que ses amis la ... au bout du quai.'::text,'retrouvent'::text,'retrouver'::text,'ont retrouvée'::text,'Elle a fait en sorte que ses amis la retrouvent au bout du quai.'::text),
(374948,41661,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Arkadaşlarının onu peronun sonunda ... sağladı.'::text,'karşılamasını'::text,'karşılamasını'::text,'karşıladı'::text,'Arkadaşlarının onu peronun sonunda karşılamasını sağladı.'::text),
(374949,41661,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elintézte, hogy a barátai a peron végén ... őt.'::text,'várják'::text,'várni'::text,'várták'::text,'Elintézte, hogy a barátai a peron végén várják őt.'::text),
(374952,41662,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Person wünscht sich offenkundig, der Bahnsteig ... kürzer, angesichts des Gewichts ihres Koffers.'::text,'wäre'::text,'ist'::text,'wird'::text,'Die Person wünscht sich offenkundig, der Bahnsteig wäre kürzer, angesichts des Gewichts ihres Koffers.'::text),
(374956,41662,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Суб''єктка, очевидно, бажає, щоб платформа ... коротшою, з огляду на вагу її валізи.'::text,'була'::text,'є'::text,'буде'::text,'Суб''єктка, очевидно, бажає, щоб платформа була коротшою, з огляду на вагу її валізи.'::text),
(374955,41662,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El sujeto evidentemente desea que el andén ... más corto, dado el peso de su maleta.'::text,'fuera'::text,'es'::text,'será'::text,'El sujeto evidentemente desea que el andén fuera más corto, dado el peso de su maleta.'::text),
(374954,41662,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le sujet souhaite manifestement que le quai ... plus court, vu le poids de sa valise.'::text,'soit'::text,'est'::text,'sera'::text,'Le sujet souhaite manifestement que le quai soit plus court, vu le poids de sa valise.'::text),
(374957,41662,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Denek, bavulunun ağırlığı göz önüne alındığında, peronun daha kısa ... açıkça diliyor.'::text,'olmasını'::text,'olduğunu'::text,'olacağını'::text,'Denek, bavulunun ağırlığı göz önüne alındığında, peronun daha kısa olmasını açıkça diliyor.'::text),
(374958,41662,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az alany a bőröndje súlyát tekintve nyilvánvalóan azt kívánja, bárcsak rövidebb ... a peron.'::text,'lenne'::text,NULL::text,'lesz'::text,'Az alany a bőröndje súlyát tekintve nyilvánvalóan azt kívánja, bárcsak rövidebb lenne a peron.'::text),
(374961,41663,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Bahnsteig, ... ihre Freunde warteten, wurde zur absolut epischen Wiedersehensszene!'::text,'wo'::text,'der'::text,'dessen'::text,'Der Bahnsteig, wo ihre Freunde warteten, wurde zur absolut epischen Wiedersehensszene!'::text),
(374965,41663,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Платформа, ... чекали її друзі, стала абсолютно епічною сценою зустрічі!'::text,'де'::text,'яка'::text,'чия'::text,'Платформа, де чекали її друзі, стала абсолютно епічною сценою зустрічі!'::text),
(374964,41663,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡El andén, ... la esperaban sus amigos, se convirtió en una escena de reencuentro absolutamente épica!'::text,'donde'::text,'que'::text,'cuyo'::text,'¡El andén, donde la esperaban sus amigos, se convirtió en una escena de reencuentro absolutamente épica!'::text),
(374963,41663,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le quai, ... ses amis attendaient, est devenu une scène de retrouvailles absolument épique !'::text,'où'::text,'qui'::text,'dont'::text,'Le quai, où ses amis attendaient, est devenu une scène de retrouvailles absolument épique !'::text),
(374966,41663,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Arkadaşlarının ... beklediği peron, resmen efsanevi bir kavuşma sahnesine dönüştü!'::text,''::text,NULL::text,NULL::text,'Arkadaşlarının beklediği peron, resmen efsanevi bir kavuşma sahnesine dönüştü!'::text),
(374967,41663,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A peron, ... a barátai vártak, egy abszolút epikus viszontlátási jelenetté vált!'::text,'ahol'::text,'amely'::text,'akinek'::text,'A peron, ahol a barátai vártak, egy abszolút epikus viszontlátási jelenetté vált!'::text),
(374970,41664,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie kam endlich mit ... nach Hause und rannte den Bahnsteig entlang. Das Ende einer Albtraumreise!'::text,'dem Zug'::text,'dem Zug'::text,'einem Zug'::text,'Sie kam endlich mit dem Zug nach Hause und rannte den Bahnsteig entlang. Das Ende einer Albtraumreise!'::text),
(374974,41664,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона нарешті приїхала додому ... і побігла платформою. Кінець поїздки-жахіття!'::text,'потягом'::text,'потягом'::text,'потягом'::text,'Вона нарешті приїхала додому потягом і побігла платформою. Кінець поїздки-жахіття!'::text),
(374973,41664,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Por fin llegó a casa ... y corrió por el andén. ¡El fin de un viaje de pesadilla!'::text,'en tren'::text,'en el tren'::text,'en un tren'::text,'Por fin llegó a casa en tren y corrió por el andén. ¡El fin de un viaje de pesadilla!'::text),
(374972,41664,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle est enfin rentrée ... et a couru le long du quai. La fin d''un voyage cauchemardesque !'::text,'en train'::text,'par le train'::text,'par un train'::text,'Elle est enfin rentrée en train et a couru le long du quai. La fin d''un voyage cauchemardesque !'::text),
(374975,41664,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sonunda eve ... döndü ve peron boyunca koştu. Kâbus gibi bir yolculuğun sonu!'::text,'trenle'::text,'trenle'::text,'bir trenle'::text,'Sonunda eve trenle döndü ve peron boyunca koştu. Kâbus gibi bir yolculuğun sonu!'::text),
(374976,41664,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Végre hazaért ..., és végigrohant a peronon. Egy rémálomszerű utazás vége!'::text,'vonattal'::text,'a vonattal'::text,'egy vonattal'::text,'Végre hazaért vonattal, és végigrohant a peronon. Egy rémálomszerű utazás vége!'::text),
(374988,41666,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Okay, also sie schwört, sie wusste, dass ihre Freunde sie am Bahnsteig ...'::text,'abholen würden'::text,'abholen werden'::text,'abholen'::text,'Okay, also sie schwört, sie wusste, dass ihre Freunde sie am Bahnsteig abholen würden.'::text),
(374992,41666,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коротше, вона клянеться, що знала, що друзі ... її на платформі.'::text,'зустрінуть'::text,'зустрінуть'::text,'зустрічають'::text,'Коротше, вона клянеться, що знала, що друзі зустрінуть її на платформі.'::text),
(374991,41666,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vale, pues jura que sabía que sus amigos la ... en el andén.'::text,'recogerían'::text,'recogerán'::text,'recogen'::text,'Vale, pues jura que sabía que sus amigos la recogerían en el andén.'::text),
(374990,41666,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bon, elle jure qu''elle savait que ses amis ... la chercher sur le quai.'::text,'viendraient'::text,'viendront'::text,'viennent'::text,'Bon, elle jure qu''elle savait que ses amis viendraient la chercher sur le quai.'::text),
(374993,41666,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tamam yani, arkadaşlarının onu peronda ... bildiğine yemin ediyor.'::text,'karşılayacağını'::text,'karşılayacağını'::text,'karşıladığını'::text,'Tamam yani, arkadaşlarının onu peronda karşılayacağını bildiğine yemin ediyor.'::text),
(374994,41666,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oké, szóval esküszik, hogy tudta, a barátai ... őt a peronon.'::text,'várni fogják'::text,'várni fogják'::text,'várják'::text,'Oké, szóval esküszik, hogy tudta, a barátai várni fogják őt a peronon.'::text),
(374997,41667,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, angeblich ... sie gerade mit ihrem Koffer den Bahnsteig entlang!'::text,'läuft'::text,'läuft'::text,'ist gelaufen'::text,'Bestie, angeblich läuft sie gerade mit ihrem Koffer den Bahnsteig entlang!'::text),
(375001,41667,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подружко, кажуть, вона зараз ... платформою з валізою!'::text,'йде'::text,'ходить'::text,'пройшла'::text,'Подружко, кажуть, вона зараз йде платформою з валізою!'::text),
(375000,41667,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Amiga, al parecer ella ... por el andén ahora mismo con su maleta!'::text,'está caminando'::text,'camina'::text,'ha caminado'::text,'¡Amiga, al parecer ella está caminando por el andén ahora mismo con su maleta!'::text),
(374999,41667,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, apparemment elle ... sur le quai en ce moment avec sa valise !'::text,'marche'::text,'marche'::text,'a marché'::text,'Bestie, apparemment elle marche sur le quai en ce moment avec sa valise !'::text),
(375002,41667,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, galiba şu an bavuluyla peron boyunca ...!'::text,'yürüyor'::text,'yürür'::text,'yürüdü'::text,'Kanka, galiba şu an bavuluyla peron boyunca yürüyor!'::text),
(375003,41667,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag épp most ... végig a peronon a bőröndjével!'::text,'sétál'::text,'sétál'::text,'sétált'::text,'Csajszi, állítólag épp most sétál végig a peronon a bőröndjével!'::text),
(362388,40266,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... gerade die Anleitung, als sie aufsah und fragte, ob alles gut sei.'::text,'las'::text,'las'::text,'hat gelesen'::text,'Er las gerade die Anleitung, als sie aufsah und fragte, ob alles gut sei.'::text),
(362392,40266,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... інструкцію, коли вона підвела голову й спитала, чи все добре.'::text,'читав'::text,'прочитав'::text,'прочитав'::text,'Він читав інструкцію, коли вона підвела голову й спитала, чи все добре.'::text),
(362391,40266,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él ... las instrucciones cuando ella levantó la vista y preguntó si todo iba bien.'::text,'estaba leyendo'::text,'leyó'::text,'ha leído'::text,'Él estaba leyendo las instrucciones cuando ella levantó la vista y preguntó si todo iba bien.'::text),
(362390,40266,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... le mode d''emploi quand elle a levé les yeux et demandé si tout allait bien.'::text,'lisait'::text,'a lu'::text,'a lu'::text,'Il lisait le mode d''emploi quand elle a levé les yeux et demandé si tout allait bien.'::text),
(362393,40266,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kadın başını kaldırıp her şey yolunda mı diye sorduğunda o talimatları ...'::text,'okuyordu'::text,'okudu'::text,'okumuş'::text,'Kadın başını kaldırıp her şey yolunda mı diye sorduğunda o talimatları okuyordu.'::text),
(362394,40266,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő éppen ... az útmutatót, amikor a nő felnézett, és megkérdezte, minden rendben van-e.'::text,'olvasta'::text,'elolvasta'::text,'elolvasta'::text,'Ő éppen olvasta az útmutatót, amikor a nő felnézett, és megkérdezte, minden rendben van-e.'::text),
(362397,40267,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... die Anleitung schon den ganzen Nachmittag. Absolut anstrengend!'::text,'lesen'::text,'lasen'::text,'lesen'::text,'Sie lesen die Anleitung schon den ganzen Nachmittag. Absolut anstrengend!'::text),
(362401,40267,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вони ... інструкцію все пообіддя. Абсолютно виснажливо!'::text,'читають'::text,'читали'::text,'читають'::text,'Вони читають інструкцію все пообіддя. Абсолютно виснажливо!'::text),
(362400,40267,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ellos ... las instrucciones toda la tarde. ¡Absolutamente agotador!'::text,'han estado leyendo'::text,'leyeron'::text,'están leyendo'::text,'Ellos han estado leyendo las instrucciones toda la tarde. ¡Absolutamente agotador!'::text),
(362399,40267,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ils ... le mode d''emploi depuis tout l''après-midi. Absolument épuisant !'::text,'lisent'::text,'ont lu'::text,'sont en train de lire'::text,'Ils lisent le mode d''emploi depuis tout l''après-midi. Absolument épuisant !'::text),
(362402,40267,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bütün öğleden sonradır talimatları ... ve bu kesinlikle yorucu!'::text,'okuyorlar'::text,'okudular'::text,'okuyorlar'::text,'Bütün öğleden sonradır talimatları okuyorlar ve bu kesinlikle yorucu!'::text),
(362403,40267,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egész délután ... az útmutatót. Abszolút kimerítő!'::text,'olvassák'::text,'olvasták'::text,'olvassák'::text,'Egész délután olvassák az útmutatót. Abszolút kimerítő!'::text),
(362406,40268,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bevor sie anfingen, ... er die Anleitung zweimal durchgelesen. Absolut keine Katastrophen!'::text,'hatte'::text,'hat'::text,'liest'::text,'Bevor sie anfingen, hatte er die Anleitung zweimal durchgelesen. Absolut keine Katastrophen!'::text),
(362410,40268,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Перш ніж вони почали, він ... інструкцію двічі. Абсолютно жодних катастроф!'::text,'прочитав'::text,'прочитав'::text,'читає'::text,'Перш ніж вони почали, він прочитав інструкцію двічі. Абсолютно жодних катастроф!'::text),
(362409,40268,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Antes de empezar, él ... las instrucciones dos veces. ¡Absolutamente ningún desastre!'::text,'había leído'::text,'ha leído'::text,'lee'::text,'Antes de empezar, él había leído las instrucciones dos veces. ¡Absolutamente ningún desastre!'::text),
(362408,40268,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Avant qu''ils commencent, il ... le mode d''emploi deux fois. Absolument aucune catastrophe !'::text,'avait lu'::text,'a lu'::text,'lit'::text,'Avant qu''ils commencent, il avait lu le mode d''emploi deux fois. Absolument aucune catastrophe !'::text),
(362411,40268,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Başlamadan önce talimatları iki kez ... ve kesinlikle hiç felaket yaşanmadı!'::text,'okumuştu'::text,'okudu'::text,'okur'::text,'Başlamadan önce talimatları iki kez okumuştu ve kesinlikle hiç felaket yaşanmadı!'::text),
(362412,40268,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mielőtt nekikezdtek, ő kétszer ... az útmutatót. Abszolút semmi katasztrófa!'::text,'elolvasta'::text,'elolvasta'::text,'olvassa'::text,'Mielőtt nekikezdtek, ő kétszer elolvasta az útmutatót. Abszolút semmi katasztrófa!'::text),
(362415,40269,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn sie der Anleitung folgen, ... der Schrank gerade stehen.'::text,'wird'::text,'würde'::text,'stand'::text,'Wenn sie der Anleitung folgen, wird der Schrank gerade stehen.'::text),
(362419,40269,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо вони дотримуватимуться інструкції, шафа ... рівно.'::text,'стоятиме'::text,'стояла б'::text,'стояла'::text,'Якщо вони дотримуватимуться інструкції, шафа стоятиме рівно.'::text),
(362418,40269,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si siguen las instrucciones, el armario ... recto.'::text,'quedará'::text,'quedaría'::text,'quedó'::text,'Si siguen las instrucciones, el armario quedará recto.'::text),
(362417,40269,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'S''ils suivent le mode d''emploi, l''armoire ... droite.'::text,'tiendra'::text,'tiendrait'::text,'tenait'::text,'S''ils suivent le mode d''emploi, l''armoire tiendra droite.'::text),
(362420,40269,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Talimatlara uyarlarsa dolap düz ...'::text,'duracak'::text,'dururdu'::text,'durdu'::text,'Talimatlara uyarlarsa dolap düz duracak.'::text),
(362421,40269,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha követik az útmutatót, a szekrény egyenesen ...'::text,'fog állni'::text,'állna'::text,'állt'::text,'Ha követik az útmutatót, a szekrény egyenesen fog állni.'::text),
(362424,40270,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn es keine Anleitung gäbe, ... sie den Schrank nicht so schnell aufbauen.'::text,'würden'::text,'werden'::text,'bauten'::text,'Wenn es keine Anleitung gäbe, würden sie den Schrank nicht so schnell aufbauen.'::text),
(362428,40270,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби не було інструкції, вони ... шафу так швидко.'::text,'не зібрали б'::text,'не зберуть'::text,'не зібрали'::text,'Якби не було інструкції, вони не зібрали б шафу так швидко.'::text),
(362427,40270,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si no hubiera instrucciones, ... el armario tan rápido.'::text,'no montarían'::text,'no montarán'::text,'no montaron'::text,'Si no hubiera instrucciones, no montarían el armario tan rápido.'::text),
(362426,40270,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'S''il n''y avait pas de mode d''emploi, ils ... l''armoire aussi vite.'::text,'ne monteraient pas'::text,'ne monteront pas'::text,'n''ont pas monté'::text,'S''il n''y avait pas de mode d''emploi, ils ne monteraient pas l''armoire aussi vite.'::text),
(362429,40270,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Talimat olmasaydı dolabı bu kadar hızlı ...'::text,'kurmazlardı'::text,'kurmayacaklar'::text,'kurmadılar'::text,'Talimat olmasaydı dolabı bu kadar hızlı kurmazlardı.'::text),
(362430,40270,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha nem lenne útmutató, ... ilyen gyorsan a szekrényt.'::text,'nem raknák össze'::text,'nem fogják összerakni'::text,'nem rakták össze'::text,'Ha nem lenne útmutató, nem raknák össze ilyen gyorsan a szekrényt.'::text),
(362433,40271,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mädel, ich hab gehört, dass die Anleitung direkt nach dem Aufbau des Schranks in den Müll ...!'::text,'geworfen wurde'::text,'warf'::text,'geworfen wird'::text,'Mädel, ich hab gehört, dass die Anleitung direkt nach dem Aufbau des Schranks in den Müll geworfen wurde!'::text),
(362437,40271,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, я чула, що інструкцію ... у смітник одразу після того, як шафу зібрали!'::text,'викинули'::text,'викинула'::text,'викидають'::text,'Подруго, я чула, що інструкцію викинули у смітник одразу після того, як шафу зібрали!'::text),
(362436,40271,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Tía, he oído que las instrucciones ... a la basura justo después de montar el armario!'::text,'fueron tiradas'::text,'tiraron'::text,'son tiradas'::text,'¡Tía, he oído que las instrucciones fueron tiradas a la basura justo después de montar el armario!'::text),
(362435,40271,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, j''ai entendu dire que le mode d''emploi ... à la poubelle juste après le montage de l''armoire !'::text,'a été jeté'::text,'a jeté'::text,'est jeté'::text,'Meuf, j''ai entendu dire que le mode d''emploi a été jeté à la poubelle juste après le montage de l''armoire !'::text),
(362438,40271,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, duydum ki dolap biter bitmez talimatlar çöpe ...!'::text,'atılmış'::text,'atmış'::text,'atılıyor'::text,'Kızım, duydum ki dolap biter bitmez talimatlar çöpe atılmış!'::text),
(362439,40271,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, azt hallottam, hogy az útmutatót ... a kukába, amint kész lett a szekrény!'::text,'kidobták'::text,'kidobta'::text,'kidobják'::text,'Csajszi, azt hallottam, hogy az útmutatót kidobták a kukába, amint kész lett a szekrény!'::text),
(362442,40272,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Mann ... die Anleitung laut vor, während die Frau den Schraubenzieher benutzte.'::text,'las'::text,'wurde gelesen'::text,'lesend'::text,'Der Mann las die Anleitung laut vor, während die Frau den Schraubenzieher benutzte.'::text),
(362446,40272,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чоловік ... інструкцію вголос, поки жінка працювала викруткою.'::text,'читав'::text,'читався'::text,'читаючи'::text,'Чоловік читав інструкцію вголос, поки жінка працювала викруткою.'::text),
(362445,40272,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El hombre ... las instrucciones en voz alta mientras la mujer usaba el destornillador.'::text,'leyó'::text,'fue leído'::text,'leyendo'::text,'El hombre leyó las instrucciones en voz alta mientras la mujer usaba el destornillador.'::text),
(362444,40272,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''homme ... le mode d''emploi à voix haute pendant que la femme utilisait le tournevis.'::text,'lisait'::text,'était lu'::text,'lisant'::text,'L''homme lisait le mode d''emploi à voix haute pendant que la femme utilisait le tournevis.'::text),
(362447,40272,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kadın tornavidayı kullanırken adam talimatları yüksek sesle ...'::text,'okudu'::text,'okundu'::text,'okuyarak'::text,'Kadın tornavidayı kullanırken adam talimatları yüksek sesle okudu.'::text),
(362448,40272,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A férfi hangosan ... az útmutatót, miközben a nő a csavarhúzót használta.'::text,'felolvasta'::text,'fel lett olvasva'::text,'felolvasva'::text,'A férfi hangosan felolvasta az útmutatót, miközben a nő a csavarhúzót használta.'::text),
(362460,40274,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Anleitung, ... Bilder winzig sind, war eindeutig ein Vergnügen zu lesen.'::text,'deren'::text,'die'::text,'die'::text,'Die Anleitung, deren Bilder winzig sind, war eindeutig ein Vergnügen zu lesen.'::text),
(362464,40274,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Інструкція, ... малюнки крихітні, явно читалася із задоволенням.'::text,'чиї'::text,'яка'::text,'хто'::text,'Інструкція, чиї малюнки крихітні, явно читалася із задоволенням.'::text),
(362463,40274,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Las instrucciones, ... dibujos son diminutos, eran claramente un placer de leer.'::text,'cuyos'::text,'que'::text,'quienes'::text,'Las instrucciones, cuyos dibujos son diminutos, eran claramente un placer de leer.'::text),
(362462,40274,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le mode d''emploi, ... les images sont minuscules, était clairement un plaisir à lire.'::text,'dont'::text,'qui'::text,'qui'::text,'Le mode d''emploi, dont les images sont minuscules, était clairement un plaisir à lire.'::text),
(362465,40274,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... Resimleri minicik olan talimatları okumak belli ki tam bir keyifti.'::text,''::text,NULL::text,NULL::text,'Resimleri minicik olan talimatları okumak belli ki tam bir keyifti.'::text),
(362466,40274,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az útmutató, ... képei aprók, nyilvánvalóan élvezet volt olvasni.'::text,'amelynek'::text,'amely'::text,'aki'::text,'Az útmutató, amelynek képei aprók, nyilvánvalóan élvezet volt olvasni.'::text),
(362469,40275,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... den Hocker nach Anleitung zusammengebaut, bevor sie mit dem Schrank anfingen.'::text,'hatten'::text,'haben'::text,'bauen'::text,'Sie hatten den Hocker nach Anleitung zusammengebaut, bevor sie mit dem Schrank anfingen.'::text),
(362473,40275,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вони ... табурет, перш ніж узялися за шафу, за інструкцією.'::text,'зібрали'::text,'зібрали'::text,'збирають'::text,'Вони зібрали табурет, перш ніж узялися за шафу, за інструкцією.'::text),
(362472,40275,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ellos ... el taburete antes de empezar con el armario, siguiendo las instrucciones.'::text,'habían montado'::text,'han montado'::text,'montan'::text,'Ellos habían montado el taburete antes de empezar con el armario, siguiendo las instrucciones.'::text),
(362471,40275,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ils ... le tabouret avant de s''attaquer à l''armoire, en suivant le mode d''emploi.'::text,'avaient monté'::text,'ont monté'::text,'montent'::text,'Ils avaient monté le tabouret avant de s''attaquer à l''armoire, en suivant le mode d''emploi.'::text),
(362474,40275,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dolaba başlamadan önce talimatlara uyarak tabureyi ...'::text,'kurmuşlardı'::text,'kurdular'::text,'kuruyorlar'::text,'Dolaba başlamadan önce talimatlara uyarak tabureyi kurmuşlardı.'::text),
(362475,40275,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az útmutatót követve ... a sámlit, mielőtt nekiálltak a szekrénynek.'::text,'összerakták'::text,'összerakták'::text,'összerakják'::text,'Az útmutatót követve összerakták a sámlit, mielőtt nekiálltak a szekrénynek.'::text),
(340077,37787,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Möwen ... ihm jetzt schon seit fünf Minuten die Pommes. Ein friedliches Mittagessen, offensichtlich.'::text,'klauen'::text,'klauen'::text,'klauen'::text,'Die Möwen klauen ihm jetzt schon seit fünf Minuten die Pommes. Ein friedliches Mittagessen, offensichtlich.'::text),
(340081,37787,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чайки ... його картоплю фрі вже п''ять хвилин. Мирний обід, очевидно.'::text,'крадуть'::text,'крадуть'::text,'крадуть'::text,'Чайки крадуть його картоплю фрі вже п''ять хвилин. Мирний обід, очевидно.'::text),
(340080,37787,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Las gaviotas ... las patatas fritas desde hace cinco minutos. Un almuerzo tranquilo, obviamente.'::text,'le están robando'::text,'le están robando'::text,'le roban'::text,'Las gaviotas le están robando las patatas fritas desde hace cinco minutos. Un almuerzo tranquilo, obviamente.'::text),
(340079,37787,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les mouettes ... ses frites depuis cinq minutes. Un déjeuner paisible, évidemment.'::text,'lui volent'::text,'lui volent'::text,'lui volent'::text,'Les mouettes lui volent ses frites depuis cinq minutes. Un déjeuner paisible, évidemment.'::text),
(340082,37787,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Martılar beş dakikadır patates kızartmalarını ..., ne huzurlu bir öğle yemeği ama.'::text,'çalıyor'::text,'çalıyor'::text,'çalar'::text,'Martılar beş dakikadır patates kızartmalarını çalıyor, ne huzurlu bir öğle yemeği ama.'::text),
(340083,37787,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A sirályok már öt perce ... a sült krumpliját. Nyugis ebéd, nyilván.'::text,'lopkodják'::text,'lopják'::text,'lopják'::text,'A sirályok már öt perce lopkodják a sült krumpliját. Nyugis ebéd, nyilván.'::text),
(340086,37788,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... gerade eine Pommes, als eine Möwe eine aus der Tüte nahm. Perfektes Timing.'::text,'aß'::text,'aß'::text,'hat gegessen'::text,'Er aß gerade eine Pommes, als eine Möwe eine aus der Tüte nahm. Perfektes Timing.'::text),
(340090,37788,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... картоплину, коли чайка вихопила одну з ріжка. Бездоганний таймінг.'::text,'їв'::text,'з''їв'::text,'з''їв'::text,'Він їв картоплину, коли чайка вихопила одну з ріжка. Бездоганний таймінг.'::text),
(340089,37788,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él ... una patata cuando una gaviota le quitó una del cucurucho. Sincronización perfecta.'::text,'se estaba comiendo'::text,'se comió'::text,'se ha comido'::text,'Él se estaba comiendo una patata cuando una gaviota le quitó una del cucurucho. Sincronización perfecta.'::text),
(340088,37788,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... une frite quand une mouette en a pris une dans le cornet. Timing parfait.'::text,'mangeait'::text,'a mangé'::text,'a mangé'::text,'Il mangeait une frite quand une mouette en a pris une dans le cornet. Timing parfait.'::text),
(340091,37788,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir martı külahtan bir tane kaptığında o bir patates ..., kusursuz zamanlama.'::text,'yiyordu'::text,'yedi'::text,'yemiş'::text,'Bir martı külahtan bir tane kaptığında o bir patates yiyordu, kusursuz zamanlama.'::text),
(340092,37788,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Épp ... egy hasábburgonyát, amikor egy sirály kivett egyet a tölcsérből. Hibátlan időzítés.'::text,'evett'::text,'megevett'::text,'megevett'::text,'Épp evett egy hasábburgonyát, amikor egy sirály kivett egyet a tölcsérből. Hibátlan időzítés.'::text),
(340095,37789,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Digga, die Möwen ... ihm schon so die Hälfte seiner Pommes, ohne Witz.'::text,'klauten'::text,'klauten'::text,'klauen'::text,'Digga, die Möwen klauten ihm schon so die Hälfte seiner Pommes, ohne Witz.'::text),
(340099,37789,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, чайки вже ... десь половину його картоплі, чесно.'::text,'вкрали'::text,'крали'::text,'крадуть'::text,'Бро, чайки вже вкрали десь половину його картоплі, чесно.'::text),
(340098,37789,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, las gaviotas ya le ... como la mitad de las patatas, en serio.'::text,'han robado'::text,'han estado robando'::text,'están robando'::text,'Tío, las gaviotas ya le han robado como la mitad de las patatas, en serio.'::text),
(340097,37789,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, les mouettes lui ... déjà genre la moitié de ses frites, sans mentir.'::text,'ont piqué'::text,'piquent'::text,'sont en train de piquer'::text,'Frère, les mouettes lui ont piqué déjà genre la moitié de ses frites, sans mentir.'::text),
(340100,37789,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, martılar patateslerinin yarısını çoktan ..., ciddiyim.'::text,'çaldı'::text,'çalıyordu'::text,'çalıyor'::text,'Kanka, martılar patateslerinin yarısını çoktan çaldı, ciddiyim.'::text),
(340101,37789,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, a sirályok már vagy a felét ... a sült krumplijának, komolyan.'::text,'ellopták'::text,'lopták'::text,'lopják'::text,'Tesó, a sirályok már vagy a felét ellopták a sült krumplijának, komolyan.'::text),
(340104,37790,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, wenn er die Pommes nochmal aufmacht, ... sich die Möwen direkt auf ihn, echt.'::text,'stürzen'::text,'würden stürzen'::text,'stürzten'::text,'Alter, wenn er die Pommes nochmal aufmacht, stürzen sich die Möwen direkt auf ihn, echt.'::text),
(340108,37790,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чувак, якщо він знову відкриє ту картоплю, чайки ... прямо на нього, реально.'::text,'полетять'::text,'полетіли б'::text,'полетіли'::text,'Чувак, якщо він знову відкриє ту картоплю, чайки полетять прямо на нього, реально.'::text),
(340107,37790,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, si vuelve a abrir esas patatas, las gaviotas ... directo hacia él, en serio.'::text,'volarán'::text,'volarían'::text,'volaron'::text,'Tío, si vuelve a abrir esas patatas, las gaviotas volarán directo hacia él, en serio.'::text),
(340106,37790,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mec, s''il rouvre ces frites, les mouettes ... droit sur lui, sérieux.'::text,'fonceront'::text,'fonceraient'::text,'ont foncé'::text,'Mec, s''il rouvre ces frites, les mouettes fonceront droit sur lui, sérieux.'::text),
(340109,37790,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dostum, o patatesleri bir daha açarsa martılar direkt üstüne ..., cidden.'::text,'uçacak'::text,'uçardı'::text,'uçtu'::text,'Dostum, o patatesleri bir daha açarsa martılar direkt üstüne uçacak, cidden.'::text),
(340110,37790,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Haver, ha még egyszer kinyitja azt a krumplit, a sirályok egyenesen rá ..., komolyan.'::text,'fognak repülni'::text,'repülnének'::text,'repültek'::text,'Haver, ha még egyszer kinyitja azt a krumplit, a sirályok egyenesen rá fognak repülni, komolyan.'::text),
(340113,37791,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn die Möwen für ihre Pommes bezahlen würden, ... sein Mittagsbudget 50 % größer.'::text,'wäre'::text,'wird'::text,'ist'::text,'Wenn die Möwen für ihre Pommes bezahlen würden, wäre sein Mittagsbudget 50 % größer.'::text),
(340117,37791,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби чайки платили за свою картоплю, його бюджет на обід ... на 50 % більшим.'::text,'був би'::text,'буде'::text,'є'::text,'Якби чайки платили за свою картоплю, його бюджет на обід був би на 50 % більшим.'::text),
(340116,37791,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si las gaviotas pagaran sus patatas, su presupuesto para el almuerzo ... un 50 % mayor.'::text,'sería'::text,'será'::text,'es'::text,'Si las gaviotas pagaran sus patatas, su presupuesto para el almuerzo sería un 50 % mayor.'::text),
(340115,37791,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si les mouettes payaient leurs frites, son budget déjeuner ... 50 % plus élevé.'::text,'serait'::text,'sera'::text,'est'::text,'Si les mouettes payaient leurs frites, son budget déjeuner serait 50 % plus élevé.'::text),
(340118,37791,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Martılar patatesleri için ödeme yapsaydı, öğle yemeği bütçesi %50 daha büyük ...'::text,'olurdu'::text,'olacak'::text,NULL::text,'Martılar patatesleri için ödeme yapsaydı, öğle yemeği bütçesi %50 daha büyük olurdu.'::text),
(340119,37791,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a sirályok fizetnének a sült krumpliért, az ebédkerete 50%-kal nagyobb ...'::text,'lenne'::text,'lesz'::text,NULL::text,'Ha a sirályok fizetnének a sült krumpliért, az ebédkerete 50%-kal nagyobb lenne.'::text),
(340122,37792,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eine seiner Pommes ... vor einem Moment von einer Möwe aus der Papiertüte gezogen.'::text,'wurde'::text,'zog'::text,'wird'::text,'Eine seiner Pommes wurde vor einem Moment von einer Möwe aus der Papiertüte gezogen.'::text),
(340126,37792,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Одна з його картоплин ... чайкою з паперового ріжка щойно.'::text,'була витягнута'::text,'витягла'::text,'витягується'::text,'Одна з його картоплин була витягнута чайкою з паперового ріжка щойно.'::text),
(340125,37792,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Una de sus patatas ... del cucurucho de papel por una gaviota hace un momento.'::text,'fue sacada'::text,'sacó'::text,'es sacada'::text,'Una de sus patatas fue sacada del cucurucho de papel por una gaviota hace un momento.'::text),
(340124,37792,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Une de ses frites ... du cornet en papier par une mouette il y a un instant.'::text,'a été tirée'::text,'a tiré'::text,'est tirée'::text,'Une de ses frites a été tirée du cornet en papier par une mouette il y a un instant.'::text),
(340127,37792,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Patateslerinden biri az önce bir martı tarafından kâğıt külahtan ...'::text,'çekildi'::text,'çekti'::text,'çekiliyor'::text,'Patateslerinden biri az önce bir martı tarafından kâğıt külahtan çekildi.'::text),
(340128,37792,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az egyik sült krumpliját egy perccel ezelőtt ... egy sirály a papírtölcsérből.'::text,'kihúzta'::text,'kihúzta'::text,'kihúzza'::text,'Az egyik sült krumpliját egy perccel ezelőtt kihúzta egy sirály a papírtölcsérből.'::text),
(340131,37793,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eine große Möwe ... eine Pommes direkt aus der Papiertüte.'::text,'schnappte'::text,'wurde geschnappt'::text,'schnappend'::text,'Eine große Möwe schnappte eine Pommes direkt aus der Papiertüte.'::text),
(340135,37793,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Велика чайка ... картоплину прямо з паперового ріжка.'::text,'вихопила'::text,'була взята'::text,'беручи'::text,'Велика чайка вихопила картоплину прямо з паперового ріжка.'::text),
(340134,37793,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Una gaviota grande ... una patata directamente del cucurucho de papel.'::text,'cogió'::text,'fue cogida'::text,'cogiendo'::text,'Una gaviota grande cogió una patata directamente del cucurucho de papel.'::text),
(340133,37793,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Une grosse mouette ... une frite directement dans le cornet en papier.'::text,'a pris'::text,'a été prise'::text,'prenant'::text,'Une grosse mouette a pris une frite directement dans le cornet en papier.'::text),
(340136,37793,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Büyük bir martı kâğıt külahtan doğrudan bir patates ...'::text,'aldı'::text,'alındı'::text,'alarak'::text,'Büyük bir martı kâğıt külahtan doğrudan bir patates aldı.'::text),
(340137,37793,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egy nagy sirály egyenesen a papírtölcsérből ... egy hasábburgonyát.'::text,'vett ki'::text,'ki lett véve'::text,'kivéve'::text,'Egy nagy sirály egyenesen a papírtölcsérből vett ki egy hasábburgonyát.'::text),
(340140,37794,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Möwen greifen jede Pommes an, also ... sie sehr hungrig sein.'::text,'müssen'::text,'können nicht'::text,'sollten nicht'::text,'Die Möwen greifen jede Pommes an, also müssen sie sehr hungrig sein.'::text),
(340144,37794,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чайки атакують кожну картоплину, тож вони ... бути дуже голодними.'::text,'мусять'::text,'не можуть'::text,'не повинні'::text,'Чайки атакують кожну картоплину, тож вони мусять бути дуже голодними.'::text),
(340143,37794,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Las gaviotas atacan cada patata, así que ... estar muy hambrientas.'::text,'deben de'::text,'no pueden'::text,'no deberían'::text,'Las gaviotas atacan cada patata, así que deben de estar muy hambrientas.'::text),
(340142,37794,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les mouettes attaquent chaque frite, alors elles ... avoir très faim.'::text,'doivent'::text,'ne peuvent pas'::text,'ne devraient pas'::text,'Les mouettes attaquent chaque frite, alors elles doivent avoir très faim.'::text),
(340145,37794,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Martılar her patatese saldırıyor, yani çok aç ...'::text,'olmalılar'::text,'olamazlar'::text,'olmamalılar'::text,'Martılar her patatese saldırıyor, yani çok aç olmalılar.'::text),
(340146,37794,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A sirályok minden krumplira lecsapnak, szóval nagyon éhesnek ... lenniük.'::text,'kell'::text,'nem lehet'::text,'nem szabad'::text,'A sirályok minden krumplira lecsapnak, szóval nagyon éhesnek kell lenniük.'::text),
(340158,37796,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du hast gesagt, du ... die Pommes selbst gekauft, also ehrlich, Respekt, dass du sie verteidigt hast.'::text,'hättest'::text,'hast'::text,'kaufst'::text,'Du hast gesagt, du hättest die Pommes selbst gekauft, also ehrlich, Respekt, dass du sie verteidigt hast.'::text),
(340162,37796,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти казав, що сам ... ту картоплю, тож чесно, респект, що захищав її.'::text,'купив'::text,'купив'::text,'купуєш'::text,'Ти казав, що сам купив ту картоплю, тож чесно, респект, що захищав її.'::text),
(340161,37796,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dijiste que ... esas patatas tú mismo, así que, sinceramente, respeto por defenderlas.'::text,'habías comprado'::text,'has comprado'::text,'compras'::text,'Dijiste que habías comprado esas patatas tú mismo, así que, sinceramente, respeto por defenderlas.'::text),
(340160,37796,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu as dit que tu ... ces frites toi-même, alors franchement, respect de les avoir défendues.'::text,'avais acheté'::text,'as acheté'::text,'achètes'::text,'Tu as dit que tu avais acheté ces frites toi-même, alors franchement, respect de les avoir défendues.'::text),
(340163,37796,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O patatesleri kendin ... söyledin, o yüzden açıkçası onları savunduğun için helal olsun.'::text,'almış olduğunu'::text,'aldığını'::text,'aldığını'::text,'O patatesleri kendin almış olduğunu söyledin, o yüzden açıkçası onları savunduğun için helal olsun.'::text),
(340164,37796,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azt mondtad, hogy magad ... azt a sült krumplit, szóval őszintén, respekt, hogy megvédted.'::text,'vetted meg'::text,'vetted meg'::text,'veszed meg'::text,'Azt mondtad, hogy magad vetted meg azt a sült krumplit, szóval őszintén, respekt, hogy megvédted.'::text),
(354477,39387,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Digga, morgen um diese Zeit ... er wieder vor diesen Möwen, ohne Witz.'::text,'flüchtet'::text,'wird flüchten'::text,'flüchtet'::text,'Digga, morgen um diese Zeit flüchtet er wieder vor diesen Möwen, ohne Witz.'::text),
(354481,39387,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, завтра в цей час він знову ... від тих чайок, без жартів.'::text,'тікатиме'::text,'втече'::text,'тікає'::text,'Бро, завтра в цей час він знову тікатиме від тих чайок, без жартів.'::text),
(354480,39387,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, mañana a esta hora él ... otra vez de esas gaviotas, en serio.'::text,'estará huyendo'::text,'huirá'::text,'huye'::text,'Tío, mañana a esta hora él estará huyendo otra vez de esas gaviotas, en serio.'::text),
(354479,39387,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, demain à la même heure, il ... encore ces mouettes, sans mentir.'::text,'sera en train de fuir'::text,'fuira'::text,'fuit'::text,'Frère, demain à la même heure, il sera en train de fuir encore ces mouettes, sans mentir.'::text),
(354482,39387,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, yarın bu saatte yine o martılardan ..., ciddiyim.'::text,'kaçıyor olacak'::text,'kaçacak'::text,'kaçar'::text,'Kanka, yarın bu saatte yine o martılardan kaçıyor olacak, ciddiyim.'::text),
(354483,39387,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, holnap ilyenkor megint ... azok elől a sirályok elől, komolyan.'::text,'menekülni fog'::text,'el fog menekülni'::text,'menekül'::text,'Tesó, holnap ilyenkor megint menekülni fog azok elől a sirályok elől, komolyan.'::text),
(354486,39388,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nee Digga, vergiss die Pommes, ich ... mit ihm ab, echt.'::text,'hau'::text,'werde'::text,'hau'::text,'Nee Digga, vergiss die Pommes, ich hau mit ihm ab, echt.'::text),
(354490,39388,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не, бро, забудь про картоплю, я ... з ним, реально.'::text,'втечу'::text,'тікатиму'::text,'тікаю'::text,'Не, бро, забудь про картоплю, я втечу з ним, реально.'::text),
(354489,39388,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nah, tío, olvida las patatas, yo ... con él, en serio.'::text,'me largo'::text,'me estaré largando'::text,'me largo'::text,'Nah, tío, olvida las patatas, yo me largo con él, en serio.'::text),
(354488,39388,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nan frère, oublie les frites, je ... avec lui, sérieux.'::text,'vais fuir'::text,'serai en train de fuir'::text,'fuis'::text,'Nan frère, oublie les frites, je vais fuir avec lui, sérieux.'::text),
(354491,39388,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yok kanka, patatesleri boş ver, ben de onunla ..., ciddiyim.'::text,'kaçacağım'::text,'kaçıyor olacağım'::text,'kaçarım'::text,'Yok kanka, patatesleri boş ver, ben de onunla kaçacağım, ciddiyim.'::text),
(354492,39388,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem, tesó, felejtsd el a krumplit, én ... vele együtt, komolyan.'::text,'elmenekülök'::text,'menekülni fogok'::text,'menekülök'::text,'Nem, tesó, felejtsd el a krumplit, én elmenekülök vele együtt, komolyan.'::text),
(354495,39389,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn sich 3 Möwen auf die Pommes eines Kunden ..., flieht der Kunde von der Strandpromenade.'::text,'stürzen'::text,'stürzten'::text,'stürzen werden'::text,'Wenn sich 3 Möwen auf die Pommes eines Kunden stürzen, flieht der Kunde von der Strandpromenade.'::text),
(354499,39389,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо 3 чайки ... на картоплю клієнта, клієнт тікає з набережної.'::text,'пікірують'::text,'спікірували'::text,'спікірують'::text,'Якщо 3 чайки пікірують на картоплю клієнта, клієнт тікає з набережної.'::text),
(354498,39389,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si 3 gaviotas se ... sobre las patatas de un cliente, el cliente huye del paseo marítimo.'::text,'lanzan'::text,'lanzaron'::text,'lanzarán'::text,'Si 3 gaviotas se lanzan sobre las patatas de un cliente, el cliente huye del paseo marítimo.'::text),
(354497,39389,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si 3 mouettes ... sur les frites d''un client, le client fuit le front de mer.'::text,'plongent'::text,'ont plongé'::text,'plongeront'::text,'Si 3 mouettes plongent sur les frites d''un client, le client fuit le front de mer.'::text),
(354500,39389,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'3 martı bir müşterinin patateslerine ..., müşteri sahil yolundan kaçar.'::text,'dalarsa'::text,'daldıysa'::text,'dalacaksa'::text,'3 martı bir müşterinin patateslerine dalarsa, müşteri sahil yolundan kaçar.'::text),
(354501,39389,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha 3 sirály ... egy ügyfél sült krumplijára, az ügyfél elmenekül a partról.'::text,'lecsap'::text,'lecsapott'::text,'le fog csapni'::text,'Ha 3 sirály lecsap egy ügyfél sült krumplijára, az ügyfél elmenekül a partról.'::text),
(354513,39391,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... früher keine Angst vor Möwen, bevor er vor ihnen fliehen musste.'::text,'hatte'::text,'hätte'::text,'hatte'::text,'Er hatte früher keine Angst vor Möwen, bevor er vor ihnen fliehen musste.'::text),
(354517,39391,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Раніше він ... чайок, поки не мусив від них тікати.'::text,'не боявся'::text,'не боявся б'::text,'не боявся'::text,'Раніше він не боявся чайок, поки не мусив від них тікати.'::text),
(354516,39391,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Antes él ... miedo a las gaviotas, hasta que tuvo que huir de ellas.'::text,'no solía tener'::text,'no tendría'::text,'no solía tener'::text,'Antes él no solía tener miedo a las gaviotas, hasta que tuvo que huir de ellas.'::text),
(354515,39391,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Avant, il ... peur des mouettes, jusqu''au jour où il a dû les fuir.'::text,'n''avait pas'::text,'n''aurait pas eu'::text,'n''avait pas'::text,'Avant, il n''avait pas peur des mouettes, jusqu''au jour où il a dû les fuir.'::text),
(354518,39391,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Onlardan kaçmak zorunda kalmadan önce martılardan ...'::text,'korkmazdı'::text,'korkmazdı'::text,'korkmazdı'::text,'Onlardan kaçmak zorunda kalmadan önce martılardan korkmazdı.'::text),
(354519,39391,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Régen ... a sirályoktól, mielőtt menekülnie kellett előlük.'::text,'nem félt'::text,'nem félne'::text,'nem félt'::text,'Régen nem félt a sirályoktól, mielőtt menekülnie kellett előlük.'::text),
(354522,39392,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er beschloss, mit seinen Pommes die Promenade entlang ...'::text,'zu fliehen'::text,'fliehend'::text,'fliehen'::text,'Er beschloss, mit seinen Pommes die Promenade entlang zu fliehen.'::text),
(354526,39392,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він вирішив ... набережною зі своєю картоплею.'::text,'втекти'::text,'втеча'::text,'втекти'::text,'Він вирішив втекти набережною зі своєю картоплею.'::text),
(354525,39392,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Decidió ... por el paseo con sus patatas.'::text,'huir'::text,'huyendo'::text,'huir'::text,'Decidió huir por el paseo con sus patatas.'::text),
(354524,39392,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il a décidé ... sur la promenade avec ses frites.'::text,'de fuir'::text,'fuyant'::text,'fuir'::text,'Il a décidé de fuir sur la promenade avec ses frites.'::text),
(354527,39392,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Patatesleriyle sahil yolu boyunca ... karar verdi.'::text,'kaçmaya'::text,'kaçarak'::text,'kaç'::text,'Patatesleriyle sahil yolu boyunca kaçmaya karar verdi.'::text),
(354528,39392,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Úgy döntött, hogy ... a sétányon a sült krumplijával.'::text,'elmenekül'::text,'menekülés'::text,'menekül'::text,'Úgy döntött, hogy elmenekül a sétányon a sült krumplijával.'::text),
(354531,39393,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er musste vor den Möwen fliehen, ...'::text,'oder?'::text,'oder?'::text,'oder?'::text,'Er musste vor den Möwen fliehen, oder?'::text),
(354535,39393,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йому довелося тікати від чайок, ...'::text,'так?'::text,'так?'::text,'так?'::text,'Йому довелося тікати від чайок, так?'::text),
(354534,39393,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tuvo que huir de las gaviotas, ...'::text,'¿verdad?'::text,'¿verdad?'::text,'¿verdad?'::text,'Tuvo que huir de las gaviotas, ¿verdad?'::text),
(354533,39393,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il a dû fuir les mouettes, ...'::text,'n''est-ce pas ?'::text,'n''est-ce pas ?'::text,'n''est-ce pas ?'::text,'Il a dû fuir les mouettes, n''est-ce pas ?'::text),
(354536,39393,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Martılardan kaçmak zorunda kaldı, ...'::text,'değil mi?'::text,'değil mi?'::text,'değil mi?'::text,'Martılardan kaçmak zorunda kaldı, değil mi?'::text),
(354537,39393,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Menekülnie kellett a sirályok elől, ...'::text,'ugye?'::text,'ugye?'::text,'ugye?'::text,'Menekülnie kellett a sirályok elől, ugye?'::text),
(354540,39394,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, du bist geflohen wie eine Legende, und ...'::text,'deine Pommes auch.'::text,'deine Pommes waren es auch.'::text,'deine Pommes auch nicht.'::text,'Ehrlich, du bist geflohen wie eine Legende, und deine Pommes auch.'::text),
(354544,39394,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, ти втік як легенда, і ...'::text,'твоя картопля теж.'::text,'твоя картопля теж була.'::text,'твоя картопля теж ні.'::text,'Чесно, ти втік як легенда, і твоя картопля теж.'::text),
(354543,39394,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sinceramente, huiste como una leyenda, y ...'::text,'tus patatas también.'::text,'tus patatas también estaban.'::text,'tus patatas tampoco.'::text,'Sinceramente, huiste como una leyenda, y tus patatas también.'::text),
(354542,39394,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, tu as fui comme une légende, et ...'::text,'tes frites aussi.'::text,'tes frites l''étaient aussi.'::text,'tes frites non plus.'::text,'Franchement, tu as fui comme une légende, et tes frites aussi.'::text),
(354545,39394,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası efsane gibi kaçtın, ...'::text,'patateslerin de öyle.'::text,'patateslerin de öyleydi.'::text,'patateslerin de kaçmadı.'::text,'Açıkçası efsane gibi kaçtın, patateslerin de öyle.'::text),
(354546,39394,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, úgy menekültél, mint egy legenda, és ...'::text,'a sült krumplid is.'::text,'a sült krumplid is az volt.'::text,'a sült krumplid sem.'::text,'Őszintén, úgy menekültél, mint egy legenda, és a sült krumplid is.'::text),
(354549,39395,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respekt, bis du den Pier erreichst, wirst du jeder einzelnen Möwe ...'::text,'entkommen sein'::text,'entkommen'::text,'entkommst'::text,'Respekt, bis du den Pier erreichst, wirst du jeder einzelnen Möwe entkommen sein.'::text),
(354553,39395,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Респект, поки добіжиш до пірсу, ти ... від кожної чайки.'::text,'втечеш'::text,'втечеш'::text,'тікаєш'::text,'Респект, поки добіжиш до пірсу, ти втечеш від кожної чайки.'::text),
(354552,39395,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respeto, para cuando llegues al muelle, ... de cada una de las gaviotas.'::text,'habrás huido'::text,'huirás'::text,'huyes'::text,'Respeto, para cuando llegues al muelle, habrás huido de cada una de las gaviotas.'::text),
(354551,39395,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respect, d''ici à ce que tu atteignes la jetée, tu ... chaque mouette.'::text,'auras fui'::text,'fuiras'::text,'fuis'::text,'Respect, d''ici à ce que tu atteignes la jetée, tu auras fui chaque mouette.'::text),
(354554,39395,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Helal, iskeleye vardığında her bir martıdan ...'::text,'kaçmış olacaksın'::text,'kaçacaksın'::text,'kaçarsın'::text,'Helal, iskeleye vardığında her bir martıdan kaçmış olacaksın.'::text),
(354555,39395,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respekt, mire a mólóhoz érsz, minden egyes sirály elől ...'::text,'már elmenekültél'::text,'el fogsz menekülni'::text,'menekülsz'::text,'Respekt, mire a mólóhoz érsz, minden egyes sirály elől már elmenekültél.'::text),
(354558,39396,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... gerade mit seinen Pommes vor den Möwen. Ein ruhiges Mittagessen, eindeutig.'::text,'flieht'::text,'flieht'::text,'ist geflohen'::text,'Er flieht gerade mit seinen Pommes vor den Möwen. Ein ruhiges Mittagessen, eindeutig.'::text),
(354562,39396,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він зараз ... від чайок зі своєю картоплею. Спокійний обід, ясна річ.'::text,'тікає'::text,'тікає'::text,'утік'::text,'Він зараз тікає від чайок зі своєю картоплею. Спокійний обід, ясна річ.'::text),
(354561,39396,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él ... de las gaviotas con sus patatas ahora mismo. Un almuerzo tranquilo, claramente.'::text,'está huyendo'::text,'huye'::text,'ha huido'::text,'Él está huyendo de las gaviotas con sus patatas ahora mismo. Un almuerzo tranquilo, claramente.'::text),
(354560,39396,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... les mouettes avec ses frites en ce moment. Un déjeuner calme, clairement.'::text,'fuit'::text,'fuit'::text,'a fui'::text,'Il fuit les mouettes avec ses frites en ce moment. Un déjeuner calme, clairement.'::text),
(354563,39396,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şu anda patatesleriyle martılardan ..., sakin bir öğle yemeği tabii.'::text,'kaçıyor'::text,'kaçar'::text,'kaçtı'::text,'Şu anda patatesleriyle martılardan kaçıyor, sakin bir öğle yemeği tabii.'::text),
(354564,39396,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Épp most ... a sirályok elől a sült krumplijával. Nyugodt ebéd, egyértelműen.'::text,'menekül'::text,'menekül'::text,'elmenekült'::text,'Épp most menekül a sirályok elől a sült krumplijával. Nyugodt ebéd, egyértelműen.'::text),
(359490,39944,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... die Truhe gerade über den Dachbodenboden, als das Staubtuch riss.'::text,'schleifte'::text,'schleifte'::text,'hat geschleift'::text,'Sie schleifte die Truhe gerade über den Dachbodenboden, als das Staubtuch riss.'::text),
(359494,39944,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... скриню підлогою горища, коли пилозахисне покривало порвалося.'::text,'тягла'::text,'дотягла'::text,'дотягла'::text,'Вона тягла скриню підлогою горища, коли пилозахисне покривало порвалося.'::text),
(359493,39944,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella ... el baúl por el suelo del desván cuando la sábana antipolvo se rompió.'::text,'estaba arrastrando'::text,'arrastró'::text,'ha arrastrado'::text,'Ella estaba arrastrando el baúl por el suelo del desván cuando la sábana antipolvo se rompió.'::text),
(359492,39944,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... la malle sur le plancher du grenier quand la housse anti-poussière s''est déchirée.'::text,'traînait'::text,'a traîné'::text,'a traîné'::text,'Elle traînait la malle sur le plancher du grenier quand la housse anti-poussière s''est déchirée.'::text),
(359495,39944,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Toz örtüsü yırtıldığında sandığı tavan arasının zemininde ...'::text,'sürüklüyordu'::text,'sürükledi'::text,'sürüklemiş'::text,'Toz örtüsü yırtıldığında sandığı tavan arasının zemininde sürüklüyordu.'::text),
(359496,39944,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Épp ... a ládát a padlás padlóján, amikor elszakadt a porvédő lepel.'::text,'vonszolta'::text,'elvonszolta'::text,'elvonszolta'::text,'Épp vonszolta a ládát a padlás padlóján, amikor elszakadt a porvédő lepel.'::text),
(352524,39170,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Boot ... sie gerade über den Hafen, als sie das Opernhaus sah.'::text,'fuhr'::text,'fuhr'::text,'hat gefahren'::text,'Das Boot fuhr sie gerade über den Hafen, als sie das Opernhaus sah.'::text),
(352528,39170,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Човен ... її через гавань, коли вона побачила оперний театр.'::text,'перевозив'::text,'перевіз'::text,'перевіз'::text,'Човен перевозив її через гавань, коли вона побачила оперний театр.'::text),
(352527,39170,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El barco la ... a través del puerto cuando vio la ópera.'::text,'estaba llevando'::text,'llevó'::text,'ha llevado'::text,'El barco la estaba llevando a través del puerto cuando vio la ópera.'::text),
(352526,39170,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le bateau la ... à travers le port quand elle a vu l''opéra.'::text,'transportait'::text,'a transportée'::text,'a transportée'::text,'Le bateau la transportait à travers le port quand elle a vu l''opéra.'::text),
(352529,39170,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Operayı gördüğünde tekne onu limanın karşısına ...'::text,'taşıyordu'::text,'taşıdı'::text,'taşımış'::text,'Operayı gördüğünde tekne onu limanın karşısına taşıyordu.'::text),
(352530,39170,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A hajó éppen ... őt a kikötőn keresztül, amikor meglátta az operaházat.'::text,'vitte'::text,'átvitte'::text,'átvitte'::text,'A hajó éppen vitte őt a kikötőn keresztül, amikor meglátta az operaházat.'::text),
(352542,39172,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Boot ... sie gerade über den Hafen, als sie die Brücke sah, also war die Brücke da.'::text,'fuhr'::text,'hat gefahren'::text,'fährt'::text,'Das Boot fuhr sie gerade über den Hafen, als sie die Brücke sah, also war die Brücke da.'::text),
(352546,39172,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Човен ... її через гавань, коли вона побачила міст, отже, міст там був.'::text,'перевозив'::text,'перевіз'::text,'перевозить'::text,'Човен перевозив її через гавань, коли вона побачила міст, отже, міст там був.'::text),
(352545,39172,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El barco la ... a través del puerto cuando vio el puente, así que el puente estaba ahí.'::text,'estaba llevando'::text,'ha llevado'::text,'lleva'::text,'El barco la estaba llevando a través del puerto cuando vio el puente, así que el puente estaba ahí.'::text),
(352544,39172,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le bateau la ... à travers le port quand elle a vu le pont, donc le pont était là.'::text,'transportait'::text,'a transportée'::text,'transporte'::text,'Le bateau la transportait à travers le port quand elle a vu le pont, donc le pont était là.'::text),
(352547,39172,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Köprüyü gördüğünde tekne onu limanın karşısına ..., yani köprü oradaydı.'::text,'taşıyordu'::text,'taşımış'::text,'taşır'::text,'Köprüyü gördüğünde tekne onu limanın karşısına taşıyordu, yani köprü oradaydı.'::text),
(352548,39172,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A hajó éppen ... őt a kikötőn keresztül, amikor meglátta a hidat, szóval a híd ott volt.'::text,'vitte'::text,'átvitte'::text,'viszi'::text,'A hajó éppen vitte őt a kikötőn keresztül, amikor meglátta a hidat, szóval a híd ott volt.'::text),
(352551,39173,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Boot ... seit ungefähr neun Uhr Passagiere über den Hafen.'::text,'befördert'::text,'beförderte'::text,'befördert'::text,'Das Boot befördert seit ungefähr neun Uhr Passagiere über den Hafen.'::text),
(352555,39173,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Човен ... пасажирів через гавань приблизно з дев''ятої години.'::text,'перевозить'::text,'перевіз'::text,'перевозить'::text,'Човен перевозить пасажирів через гавань приблизно з дев''ятої години.'::text),
(352554,39173,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El barco ... pasajeros a través del puerto desde aproximadamente las nueve.'::text,'ha estado transportando'::text,'transportó'::text,'está transportando'::text,'El barco ha estado transportando pasajeros a través del puerto desde aproximadamente las nueve.'::text),
(352553,39173,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le bateau ... des passagers à travers le port depuis environ neuf heures.'::text,'transporte'::text,'a transporté'::text,'est en train de transporter'::text,'Le bateau transporte des passagers à travers le port depuis environ neuf heures.'::text),
(352556,39173,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tekne yaklaşık saat dokuzdan beri limanın karşısına yolcu ...'::text,'taşıyor'::text,'taşıdı'::text,'taşıyor'::text,'Tekne yaklaşık saat dokuzdan beri limanın karşısına yolcu taşıyor.'::text),
(352557,39173,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A hajó körülbelül kilenc óra óta ... az utasokat a kikötőn keresztül.'::text,'szállítja'::text,'szállította'::text,'szállítja'::text,'A hajó körülbelül kilenc óra óta szállítja az utasokat a kikötőn keresztül.'::text),
(352560,39174,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis das Boot dich an der Brücke vorbeibrachte, ... du dir schon den besten Platz geschnappt, ehrlich.'::text,'hattest'::text,'hast'::text,'schnappst'::text,'Bis das Boot dich an der Brücke vorbeibrachte, hattest du dir schon den besten Platz geschnappt, ehrlich.'::text),
(352564,39174,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки човен провіз тебе повз міст, ти вже ... найкраще місце, чесно.'::text,'зайняла'::text,'зайняла'::text,'займаєш'::text,'Поки човен провіз тебе повз міст, ти вже зайняла найкраще місце, чесно.'::text),
(352563,39174,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para cuando el barco te pasó junto al puente, ya ... el mejor sitio, sinceramente.'::text,'habías cogido'::text,'has cogido'::text,'coges'::text,'Para cuando el barco te pasó junto al puente, ya habías cogido el mejor sitio, sinceramente.'::text),
(352562,39174,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le temps que le bateau te fasse passer devant le pont, tu ... la meilleure place, franchement.'::text,'avais déjà pris'::text,'as déjà pris'::text,'prends déjà'::text,'Le temps que le bateau te fasse passer devant le pont, tu avais déjà pris la meilleure place, franchement.'::text),
(352565,39174,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tekne seni köprünün yanından geçirdiğinde en iyi yeri çoktan ..., açıkçası.'::text,'kapmıştın'::text,'kaptın'::text,'kaparsın'::text,'Tekne seni köprünün yanından geçirdiğinde en iyi yeri çoktan kapmıştın, açıkçası.'::text),
(352566,39174,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire a hajó elvitt a híd mellett, már ... a legjobb helyet, őszintén.'::text,'megszerezted'::text,'megszerezted'::text,'megszerzed'::text,'Mire a hajó elvitt a híd mellett, már megszerezted a legjobb helyet, őszintén.'::text),
(352569,39175,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Morgen um diese Zeit ... dich wieder ein Boot am Opernhaus vorbei, und ehrlich, ikonisch.'::text,'fährt'::text,'fährt'::text,'hat gefahren'::text,'Morgen um diese Zeit fährt dich wieder ein Boot am Opernhaus vorbei, und ehrlich, ikonisch.'::text),
(352573,39175,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Завтра в цей час човен знову ... тебе повз оперний театр, і чесно, це культово.'::text,'везтиме'::text,'везе'::text,'провіз'::text,'Завтра в цей час човен знову везтиме тебе повз оперний театр, і чесно, це культово.'::text),
(352572,39175,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mañana a esta hora un barco te ... otra vez junto a la ópera, y sinceramente, icónico.'::text,'estará llevando'::text,'lleva'::text,'ha llevado'::text,'Mañana a esta hora un barco te estará llevando otra vez junto a la ópera, y sinceramente, icónico.'::text),
(352571,39175,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Demain à la même heure, un bateau te ... de nouveau devant l''opéra, et franchement, iconique.'::text,'fera passer'::text,'fait passer'::text,'a fait passer'::text,'Demain à la même heure, un bateau te fera passer de nouveau devant l''opéra, et franchement, iconique.'::text),
(352574,39175,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yarın bu saatte bir tekne seni yine operanın önünden ..., ve açıkçası, efsane.'::text,'geçiriyor olacak'::text,'geçirir'::text,'geçirdi'::text,'Yarın bu saatte bir tekne seni yine operanın önünden geçiriyor olacak, ve açıkçası, efsane.'::text),
(352575,39175,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Holnap ilyenkor újra egy hajó ... téged az operaház mellett, és őszintén, ikonikus.'::text,'fog vinni'::text,'visz'::text,'vitt'::text,'Holnap ilyenkor újra egy hajó fog vinni téged az operaház mellett, és őszintén, ikonikus.'::text),
(352578,39176,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn ein Boot dich am Opernhaus vorbei..., findest du immer den besten Platz. Respekt.'::text,'bringt'::text,'brachte'::text,'bringen wird'::text,'Wenn ein Boot dich am Opernhaus vorbeibringt, findest du immer den besten Platz. Respekt.'::text),
(352582,39176,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коли човен ... тебе повз оперний театр, ти завжди знаходиш найкраще місце. Респект.'::text,'везе'::text,'віз'::text,'повезе'::text,'Коли човен везе тебе повз оперний театр, ти завжди знаходиш найкраще місце. Респект.'::text),
(352581,39176,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cuando un barco te ... junto a la ópera, siempre encuentras el mejor sitio. Respeto.'::text,'lleva'::text,'llevó'::text,'llevará'::text,'Cuando un barco te lleva junto a la ópera, siempre encuentras el mejor sitio. Respeto.'::text),
(352580,39176,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand un bateau te ... devant l''opéra, tu trouves toujours la meilleure place. Respect.'::text,'fait passer'::text,'a fait passer'::text,'fera passer'::text,'Quand un bateau te fait passer devant l''opéra, tu trouves toujours la meilleure place. Respect.'::text),
(352583,39176,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir tekne seni operanın önünden ..., her zaman en iyi yeri bulursun. Helal.'::text,'geçirdiğinde'::text,'geçirdiğinde'::text,'geçireceğinde'::text,'Bir tekne seni operanın önünden geçirdiğinde, her zaman en iyi yeri bulursun. Helal.'::text),
(352584,39176,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amikor egy hajó ... téged az operaház mellett, mindig megtalálod a legjobb helyet. Respekt.'::text,'visz'::text,'vitt'::text,'vinni fog'::text,'Amikor egy hajó visz téged az operaház mellett, mindig megtalálod a legjobb helyet. Respekt.'::text),
(352587,39177,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vor dieser Reise ... Boote sie immer nur über winzige Seen. Dieselbe Aussicht, offensichtlich.'::text,'brachten'::text,'brachten'::text,'waren es gewohnt zu bringen'::text,'Vor dieser Reise brachten Boote sie immer nur über winzige Seen. Dieselbe Aussicht, offensichtlich.'::text),
(352591,39177,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До цієї поїздки човни ... її лише через крихітні озера. Той самий краєвид, очевидно.'::text,'перевозили'::text,'перевозили'::text,'звикли перевозити'::text,'До цієї поїздки човни перевозили її лише через крихітні озера. Той самий краєвид, очевидно.'::text),
(352590,39177,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Antes de este viaje, los barcos solo la ... por lagos diminutos. La misma vista, obviamente.'::text,'llevaban'::text,'solían llevar'::text,'estaban acostumbrados a llevar'::text,'Antes de este viaje, los barcos solo la llevaban por lagos diminutos. La misma vista, obviamente.'::text),
(352589,39177,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Avant ce voyage, les bateaux ne la ... que sur de minuscules lacs. La même vue, évidemment.'::text,'transportaient'::text,'transportaient'::text,'étaient habitués à transporter'::text,'Avant ce voyage, les bateaux ne la transportaient que sur de minuscules lacs. La même vue, évidemment.'::text),
(352592,39177,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu geziden önce tekneler onu sadece minik göllerde ..., aynı manzara, tabii ki.'::text,'taşırdı'::text,'taşırdı'::text,'taşımaya alışkındı'::text,'Bu geziden önce tekneler onu sadece minik göllerde taşırdı, aynı manzara, tabii ki.'::text),
(352593,39177,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ezelőtt az út előtt a hajók csak apró tavakon ... át őt. Ugyanaz a kilátás, nyilván.'::text,'vitték'::text,'vitték'::text,'voltak hozzászokva, hogy vigyék'::text,'Ezelőtt az út előtt a hajók csak apró tavakon vitték át őt. Ugyanaz a kilátás, nyilván.'::text),
(352596,39178,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie erinnert sich, wie sie letztes Jahr über diesen Hafen ... wurde. Ein total langweiliger Tag, eindeutig.'::text,'gebracht'::text,'gebracht zu werden'::text,'gebracht werden'::text,'Sie erinnert sich, wie sie letztes Jahr über diesen Hafen gebracht wurde. Ein total langweiliger Tag, eindeutig.'::text),
(352600,39178,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона пам''ятає, як її ... через цю гавань минулого року. Абсолютно нудний день, ясна річ.'::text,'перевозили'::text,'бути перевезеною'::text,'бути перевезеною'::text,'Вона пам''ятає, як її перевозили через цю гавань минулого року. Абсолютно нудний день, ясна річ.'::text),
(352599,39178,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Recuerda ... por ese puerto el año pasado. Un día totalmente aburrido, claramente.'::text,'que la llevaron'::text,'ser llevada'::text,'ser llevada'::text,'Recuerda que la llevaron por ese puerto el año pasado. Un día totalmente aburrido, claramente.'::text),
(352598,39178,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle se rappelle ... à travers ce port l''an dernier. Une journée totalement ennuyeuse, clairement.'::text,'avoir été transportée'::text,'être transportée'::text,'être transportée'::text,'Elle se rappelle avoir été transportée à travers ce port l''an dernier. Une journée totalement ennuyeuse, clairement.'::text),
(352601,39178,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Geçen yıl o limanın karşısına ... hatırlıyor. Tamamen sıkıcı bir gün, belli ki.'::text,'taşındığını'::text,'taşınmayı'::text,'taşınmak'::text,'Geçen yıl o limanın karşısına taşındığını hatırlıyor. Tamamen sıkıcı bir gün, belli ki.'::text),
(352602,39178,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Emlékszik, hogy tavaly ... azon a kikötőn keresztül. Teljesen unalmas nap, egyértelműen.'::text,'átvitték'::text,'átvinni'::text,'átvinni'::text,'Emlékszik, hogy tavaly átvitték azon a kikötőn keresztül. Teljesen unalmas nap, egyértelműen.'::text),
(352614,39180,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bevor sie surfen ging, ... ein Boot sie über den Hafen gebracht.'::text,'hatte'::text,'hat'::text,'wurde'::text,'Bevor sie surfen ging, hatte ein Boot sie über den Hafen gebracht.'::text),
(352618,39180,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Перш ніж вона пішла серфити, човен ... її через гавань.'::text,'перевіз'::text,'перевіз'::text,'був перевезений'::text,'Перш ніж вона пішла серфити, човен перевіз її через гавань.'::text),
(352617,39180,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Antes de ir a surfear, un barco la ... a través del puerto.'::text,'había llevado'::text,'ha llevado'::text,'fue llevada'::text,'Antes de ir a surfear, un barco la había llevado a través del puerto.'::text),
(352616,39180,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Avant qu''elle aille surfer, un bateau lui ... traverser le port.'::text,'avait fait'::text,'a fait'::text,'a été fait'::text,'Avant qu''elle aille surfer, un bateau lui avait fait traverser le port.'::text),
(352619,39180,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sörfe gitmeden önce bir tekne onu limanın karşısına ...'::text,'taşımıştı'::text,'taşıdı'::text,'taşındı'::text,'Sörfe gitmeden önce bir tekne onu limanın karşısına taşımıştı.'::text),
(352620,39180,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mielőtt szörfözni ment, egy hajó ... őt a kikötőn.'::text,'átvitte'::text,'átvitte'::text,'át lett víve'::text,'Mielőtt szörfözni ment, egy hajó átvitte őt a kikötőn.'::text),
(367698,40856,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, angeblich ... sie sich schon seit einer Stunde an dieses Marmorgeländer.'::text,'lehnt'::text,'lehnt'::text,'lehnt'::text,'Bestie, angeblich lehnt sie sich schon seit einer Stunde an dieses Marmorgeländer.'::text),
(367702,40856,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подружко, кажуть, вона вже годину ... на те мармурове поруччя.'::text,'спирається'::text,'спирається'::text,'спирається'::text,'Подружко, кажуть, вона вже годину спирається на те мармурове поруччя.'::text),
(367701,40856,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, al parecer ella ... en esa barandilla de mármol desde hace una hora.'::text,'ha estado apoyada'::text,'está apoyada'::text,'se apoya'::text,'Amiga, al parecer ella ha estado apoyada en esa barandilla de mármol desde hace una hora.'::text),
(367700,40856,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, apparemment elle ... sur cette rampe en marbre depuis une heure.'::text,'s''appuie'::text,'s''appuie'::text,'s''appuie'::text,'Bestie, apparemment elle s''appuie sur cette rampe en marbre depuis une heure.'::text),
(367703,40856,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, galiba bir saattir o mermer korkuluğa ...'::text,'yaslanıyor'::text,'yaslanıyor'::text,'yaslanır'::text,'Kanka, galiba bir saattir o mermer korkuluğa yaslanıyor.'::text),
(367704,40856,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag már egy órája ... annak a márványkorlátnak.'::text,'támaszkodik'::text,'támaszkodik'::text,'támaszkodik'::text,'Csajszi, állítólag már egy órája támaszkodik annak a márványkorlátnak.'::text),
(367707,40857,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Starker Move: Wenn du dich nicht an das Marmorgeländer gelehnt hättest, ... du dieses Quartett verpasst.'::text,'hättest'::text,'wirst'::text,'hast'::text,'Starker Move: Wenn du dich nicht an das Marmorgeländer gelehnt hättest, hättest du dieses Quartett verpasst.'::text),
(367711,40857,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вдалий хід: якби ти не сперлася на те мармурове поруччя, ти ... того квартету.'::text,'не побачила б'::text,'не побачиш'::text,'не побачила'::text,'Вдалий хід: якби ти не сперлася на те мармурове поруччя, ти не побачила б того квартету.'::text),
(367710,40857,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Buena jugada: si no te hubieras apoyado en esa barandilla de mármol, ... a ese cuarteto.'::text,'no habrías visto'::text,'no verás'::text,'no viste'::text,'Buena jugada: si no te hubieras apoyado en esa barandilla de mármol, no habrías visto a ese cuarteto.'::text),
(367709,40857,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Joli coup : si tu ne t''étais pas appuyée sur cette rampe en marbre, tu ... ce quatuor.'::text,'n''aurais pas vu'::text,'ne verras pas'::text,'n''as pas vu'::text,'Joli coup : si tu ne t''étais pas appuyée sur cette rampe en marbre, tu n''aurais pas vu ce quatuor.'::text),
(367712,40857,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Güzel hamle: o mermer korkuluğa yaslanmasaydın o dörtlüyü ...'::text,'görmezdin'::text,'görmeyeceksin'::text,'görmedin'::text,'Güzel hamle: o mermer korkuluğa yaslanmasaydın o dörtlüyü görmezdin.'::text),
(367713,40857,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ügyes húzás: ha nem támaszkodtál volna arra a márványkorlátra, ... azt a kvartettet.'::text,'nem láttad volna'::text,'nem fogod látni'::text,'nem láttad'::text,'Ügyes húzás: ha nem támaszkodtál volna arra a márványkorlátra, nem láttad volna azt a kvartettet.'::text),
(367716,40858,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mal ehrlich, du wolltest unbedingt die Marmortreppe ..., und es hat sich so gelohnt.'::text,'sehen'::text,'zu sehen'::text,'sahst'::text,'Mal ehrlich, du wolltest unbedingt die Marmortreppe sehen, und es hat sich so gelohnt.'::text),
(367720,40858,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не буду брехати, ти наполягла на тому, щоб ... мармурові сходи, і воно того вартувало.'::text,'побачити'::text,'побачити'::text,'побачила'::text,'Не буду брехати, ти наполягла на тому, щоб побачити мармурові сходи, і воно того вартувало.'::text),
(367719,40858,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No voy a mentir, insististe en ... la escalera de mármol, y valió totalmente la pena.'::text,'ver'::text,'ver'::text,'viste'::text,'No voy a mentir, insististe en ver la escalera de mármol, y valió totalmente la pena.'::text),
(367718,40858,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Je vais pas mentir, tu as tenu à ... l''escalier en marbre, et ça valait trop le coup.'::text,'voir'::text,'voir'::text,'as vu'::text,'Je vais pas mentir, tu as tenu à voir l''escalier en marbre, et ça valait trop le coup.'::text),
(367721,40858,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yalan yok, mermer merdiveni ... ısrar ettin ve kesinlikle değdi.'::text,'görmekte'::text,'görmek için'::text,'gördün'::text,'Yalan yok, mermer merdiveni görmekte ısrar ettin ve kesinlikle değdi.'::text),
(367722,40858,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem hazudok, ragaszkodtál hozzá, hogy ... a márványlépcsőt, és nagyon megérte.'::text,'megnézd'::text,'megnézni'::text,'megnézted'::text,'Nem hazudok, ragaszkodtál hozzá, hogy megnézd a márványlépcsőt, és nagyon megérte.'::text),
(367734,40860,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Palast lässt seine Marmortreppe jeden Morgen ...'::text,'polieren'::text,'polieren'::text,'polierend'::text,'Der Palast lässt seine Marmortreppe jeden Morgen polieren.'::text),
(367738,40860,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'У палаці щоранку ... мармурові сходи.'::text,'полірують'::text,'полірувати'::text,'полірування'::text,'У палаці щоранку полірують мармурові сходи.'::text),
(367737,40860,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El palacio hace ... su escalera de mármol cada mañana.'::text,'pulir'::text,'pulir'::text,'puliendo'::text,'El palacio hace pulir su escalera de mármol cada mañana.'::text),
(367736,40860,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le palais fait ... son escalier en marbre chaque matin.'::text,'polir'::text,'polir'::text,'polissant'::text,'Le palais fait polir son escalier en marbre chaque matin.'::text),
(367739,40860,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Saray mermer merdivenini her sabah ...'::text,'cilalatır'::text,'cilalatır'::text,'cilalayarak'::text,'Saray mermer merdivenini her sabah cilalatır.'::text),
(367740,40860,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A palota minden reggel ... a márványlépcsőjét.'::text,'kifényesítteti'::text,'kifényesítteti'::text,'fényesítve'::text,'A palota minden reggel kifényesítteti a márványlépcsőjét.'::text),
(367743,40861,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie wünscht sich, ihre Wohnung ... Marmorböden wie dieser Palast.'::text,'hätte'::text,'hat'::text,'würde haben'::text,'Sie wünscht sich, ihre Wohnung hätte Marmorböden wie dieser Palast.'::text),
(367747,40861,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона хоче, щоб її квартира ... мармурову підлогу, як у цьому палаці.'::text,'мала'::text,'має'::text,'мала б'::text,'Вона хоче, щоб її квартира мала мармурову підлогу, як у цьому палаці.'::text),
(367746,40861,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Desearía que su piso ... suelos de mármol como este palacio.'::text,'tuviera'::text,'tiene'::text,'tendría'::text,'Desearía que su piso tuviera suelos de mármol como este palacio.'::text),
(367745,40861,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle aimerait que son appartement ... des sols en marbre comme ce palais.'::text,'ait'::text,'a'::text,'aurait'::text,'Elle aimerait que son appartement ait des sols en marbre comme ce palais.'::text),
(367748,40861,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Keşke dairesinde de bu saray gibi mermer zeminler ... diye düşünüyor.'::text,'olsa'::text,'var'::text,'olurdu'::text,'Keşke dairesinde de bu saray gibi mermer zeminler olsa diye düşünüyor.'::text),
(367749,40861,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azt kívánja, bárcsak a lakásában is ... márványpadló, mint ebben a palotában.'::text,'lenne'::text,'van'::text,'lenne'::text,'Azt kívánja, bárcsak a lakásában is lenne márványpadló, mint ebben a palotában.'::text),
(367752,40862,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Palast, ... Marmorsäle von Kronleuchtern beleuchtet werden, ist riesig und gelb.'::text,'dessen'::text,'der'::text,'wo'::text,'Der Palast, dessen Marmorsäle von Kronleuchtern beleuchtet werden, ist riesig und gelb.'::text),
(367756,40862,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Палац, ... мармурові зали освітлюють люстри, величезний і жовтий.'::text,'чиї'::text,'який'::text,'де'::text,'Палац, чиї мармурові зали освітлюють люстри, величезний і жовтий.'::text),
(367755,40862,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El palacio, ... salones de mármol están iluminados por lámparas de araña, es enorme y amarillo.'::text,'cuyos'::text,'que'::text,'donde'::text,'El palacio, cuyos salones de mármol están iluminados por lámparas de araña, es enorme y amarillo.'::text),
(367754,40862,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le palais, ... les salles en marbre sont éclairées par des lustres, est immense et jaune.'::text,'dont'::text,'qui'::text,'où'::text,'Le palais, dont les salles en marbre sont éclairées par des lustres, est immense et jaune.'::text),
(367757,40862,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... Mermer salonları avizelerle aydınlatılan saray devasa ve sarı.'::text,''::text,NULL::text,NULL::text,'Mermer salonları avizelerle aydınlatılan saray devasa ve sarı.'::text),
(367758,40862,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A palota, ... márványtermeit csillárok világítják meg, hatalmas és sárga.'::text,'amelynek'::text,'amely'::text,'ahol'::text,'A palota, amelynek márványtermeit csillárok világítják meg, hatalmas és sárga.'::text),
(367761,40863,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... dieses Palastes ist absolut atemberaubend!'::text,'Der Marmor'::text,'Ein Marmor'::text,'Marmor'::text,'Der Marmor dieses Palastes ist absolut atemberaubend!'::text),
(367765,40863,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... цього палацу абсолютно захопливий!'::text,'Мармур'::text,'Мармур'::text,'Мармур'::text,'Мармур цього палацу абсолютно захопливий!'::text),
(367764,40863,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡... de este palacio es absolutamente impresionante!'::text,'El mármol'::text,'Un mármol'::text,'Mármol'::text,'¡El mármol de este palacio es absolutamente impresionante!'::text),
(367763,40863,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... de ce palais est absolument à couper le souffle !'::text,'Le marbre'::text,'Un marbre'::text,'Marbre'::text,'Le marbre de ce palais est absolument à couper le souffle !'::text),
(367766,40863,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu sarayın ... kesinlikle nefes kesici!'::text,'mermeri'::text,'bir mermeri'::text,'mermeri'::text,'Bu sarayın mermeri kesinlikle nefes kesici!'::text),
(367767,40863,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ennek a palotának ... abszolút lélegzetelállító!'::text,'a márványa'::text,'egy márványa'::text,'márványa'::text,'Ennek a palotának a márványa abszolút lélegzetelállító!'::text),
(367770,40864,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... des kalten Marmors lehnte sie ewig am Geländer. Absolut furchtlos!'::text,'Trotz'::text,'Obwohl'::text,'Wegen'::text,'Trotz des kalten Marmors lehnte sie ewig am Geländer. Absolut furchtlos!'::text),
(367774,40864,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... холодний мармур, вона цілу вічність спиралася на поруччя. Абсолютно безстрашна!'::text,'Попри'::text,'Хоча'::text,'Через'::text,'Попри холодний мармур, вона цілу вічність спиралася на поруччя. Абсолютно безстрашна!'::text),
(367773,40864,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... el mármol frío, se apoyó en la barandilla durante siglos. ¡Absolutamente valiente!'::text,'A pesar de'::text,'Aunque'::text,'Debido a'::text,'A pesar de el mármol frío, se apoyó en la barandilla durante siglos. ¡Absolutamente valiente!'::text),
(367772,40864,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... le marbre froid, elle est restée appuyée sur la rampe pendant des lustres. Absolument intrépide !'::text,'Malgré'::text,'Bien que'::text,'En raison de'::text,'Malgré le marbre froid, elle est restée appuyée sur la rampe pendant des lustres. Absolument intrépide !'::text),
(367775,40864,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Soğuk mermere ... korkuluğa uzun süre yaslandı. Kesinlikle korkusuz!'::text,'rağmen'::text,'halde'::text,'yüzünden'::text,'Soğuk mermere rağmen korkuluğa uzun süre yaslandı. Kesinlikle korkusuz!'::text),
(367776,40864,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A hideg márvány ... egy örökkévalóságig a korlátra támaszkodott. Abszolút rettenthetetlen!'::text,'ellenére'::text,'bár'::text,'miatt'::text,'A hideg márvány ellenére egy örökkévalóságig a korlátra támaszkodott. Abszolút rettenthetetlen!'::text),
(367779,40865,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Unter uns, angeblich ... sie bis heute Abend jeden Marmorsaal im Palast gesehen haben.'::text,'wird'::text,'wird'::text,'sieht'::text,'Unter uns, angeblich wird sie bis heute Abend jeden Marmorsaal im Palast gesehen haben.'::text),
(367783,40865,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Між нами, кажуть, до вечора вона ... кожну мармурову залу в палаці.'::text,'побачить'::text,'побачить'::text,'бачить'::text,'Між нами, кажуть, до вечора вона побачить кожну мармурову залу в палаці.'::text),
(367782,40865,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Entre nosotras, se supone que para esta noche ... todas las salas de mármol del palacio.'::text,'habrá visto'::text,'verá'::text,'ve'::text,'Entre nosotras, se supone que para esta noche habrá visto todas las salas de mármol del palacio.'::text),
(367781,40865,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Entre nous, il paraît que d''ici ce soir elle ... chaque salle en marbre du palais.'::text,'aura vu'::text,'verra'::text,'voit'::text,'Entre nous, il paraît que d''ici ce soir elle aura vu chaque salle en marbre du palais.'::text),
(367784,40865,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Aramızda kalsın, güya bu akşama kadar saraydaki her mermer salonu ...'::text,'görmüş olacak'::text,'görecek'::text,'görüyor'::text,'Aramızda kalsın, güya bu akşama kadar saraydaki her mermer salonu görmüş olacak.'::text),
(367785,40865,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Maradjon köztünk, állítólag estére ... a palota összes márványtermét.'::text,'már látta'::text,'látni fogja'::text,'látja'::text,'Maradjon köztünk, állítólag estére már látta a palota összes márványtermét.'::text),
(389253,43251,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn er sie den ganzen Hügel hinaufträgt, ... sein Rücken morgen total wund sein.'::text,'wird'::text,'würde'::text,'ist'::text,'Wenn er sie den ganzen Hügel hinaufträgt, wird sein Rücken morgen total wund sein.'::text),
(389257,43251,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо він донесе її аж на вершину пагорба, завтра в нього ... спина.'::text,'болітиме'::text,'боліла б'::text,'болить'::text,'Якщо він донесе її аж на вершину пагорба, завтра в нього болітиме спина.'::text),
(389256,43251,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la sube por toda la colina, mañana ... la espalda dolorida.'::text,'tendrá'::text,'tendría'::text,'tiene'::text,'Si la sube por toda la colina, mañana tendrá la espalda dolorida.'::text),
(389255,43251,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'S''il la porte jusqu''en haut de la colline, il ... mal au dos demain.'::text,'aura'::text,'aurait'::text,'a'::text,'S''il la porte jusqu''en haut de la colline, il aura mal au dos demain.'::text),
(389258,43251,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Onu bütün tepe boyunca taşırsa yarın sırtı ...'::text,'ağrıyacak'::text,'ağrırdı'::text,'ağrıyor'::text,'Onu bütün tepe boyunca taşırsa yarın sırtı ağrıyacak.'::text),
(389259,43251,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha felviszi a lányt az egész dombon, holnap ... a háta.'::text,'fájni fog'::text,'fájna'::text,'fáj'::text,'Ha felviszi a lányt az egész dombon, holnap fájni fog a háta.'::text),
(389262,43252,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn sein Rücken nicht so wehtun würde, ... er den schweren Rucksack den ganzen Tag tragen.'::text,'würde'::text,'wird'::text,'trug'::text,'Wenn sein Rücken nicht so wehtun würde, würde er den schweren Rucksack den ganzen Tag tragen.'::text),
(389266,43252,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби в нього так не боліла спина, він ... важкий рюкзак цілий день.'::text,'носив би'::text,'носитиме'::text,'носив'::text,'Якби в нього так не боліла спина, він носив би важкий рюкзак цілий день.'::text),
(389265,43252,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si no le doliera tanto la espalda, ... la mochila pesada todo el día.'::text,'llevaría'::text,'llevará'::text,'llevó'::text,'Si no le doliera tanto la espalda, llevaría la mochila pesada todo el día.'::text),
(389264,43252,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'S''il n''avait pas si mal au dos, il ... le sac à dos lourd toute la journée.'::text,'porterait'::text,'portera'::text,'portait'::text,'S''il n''avait pas si mal au dos, il porterait le sac à dos lourd toute la journée.'::text),
(389267,43252,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sırtı o kadar ağrımasaydı ağır sırt çantasını bütün gün ...'::text,'taşırdı'::text,'taşıyacak'::text,'taşıdı'::text,'Sırtı o kadar ağrımasaydı ağır sırt çantasını bütün gün taşırdı.'::text),
(389268,43252,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha nem fájna ennyire a háta, egész nap ... a nehéz hátizsákot.'::text,'cipelné'::text,'cipelni fogja'::text,'cipelte'::text,'Ha nem fájna ennyire a háta, egész nap cipelné a nehéz hátizsákot.'::text),
(389280,43254,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der schwere Rucksack ... seinen Rücken nach der langen Wanderung ganz wund.'::text,'machte'::text,'wurde gemacht'::text,'machend'::text,'Der schwere Rucksack machte seinen Rücken nach der langen Wanderung ganz wund.'::text),
(389284,43254,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Важкий рюкзак ... біль у його спині після довгої прогулянки.'::text,'спричинив'::text,'був спричинений'::text,'спричиняючи'::text,'Важкий рюкзак спричинив біль у його спині після довгої прогулянки.'::text),
(389283,43254,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La mochila pesada le ... la espalda dolorida después de la larga caminata.'::text,'dejó'::text,'fue dejada'::text,'dejando'::text,'La mochila pesada le dejó la espalda dolorida después de la larga caminata.'::text),
(389282,43254,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le sac à dos lourd lui ... mal au dos après la longue marche.'::text,'a fait'::text,'a été fait'::text,'faisant'::text,'Le sac à dos lourd lui a fait mal au dos après la longue marche.'::text),
(389285,43254,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ağır sırt çantası uzun yürüyüşten sonra sırtını ...'::text,'ağrıttı'::text,'ağrıtıldı'::text,'ağrıtarak'::text,'Ağır sırt çantası uzun yürüyüşten sonra sırtını ağrıttı.'::text),
(389286,43254,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A nehéz hátizsák a hosszú túra után ... a hátát.'::text,'megfájdította'::text,'meg lett fájdítva'::text,'fájdítva'::text,'A nehéz hátizsák a hosszú túra után megfájdította a hátát.'::text),
(389289,43255,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du hast sie den ganzen Hügel hochgetragen, also ... dir inzwischen alles wehtun, aber ehrlich, Respekt.'::text,'muss'::text,'könnte'::text,'kann nicht'::text,'Du hast sie den ganzen Hügel hochgetragen, also muss dir inzwischen alles wehtun, aber ehrlich, Respekt.'::text),
(389293,43255,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти ніс її аж на вершину пагорба, тож у тебе вже ... все боліти, але чесно, респект.'::text,'мусить'::text,'може'::text,'не може'::text,'Ти ніс її аж на вершину пагорба, тож у тебе вже мусить все боліти, але чесно, респект.'::text),
(389292,43255,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La subiste por toda la colina, así que ... estar dolorido ya, pero sinceramente, respeto.'::text,'debes de'::text,'podrías'::text,'no puedes'::text,'La subiste por toda la colina, así que debes de estar dolorido ya, pero sinceramente, respeto.'::text),
(389291,43255,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu l''as portée jusqu''en haut de la colline, donc tu ... avoir mal partout maintenant, mais franchement, respect.'::text,'dois'::text,'pourrais'::text,'ne peux pas'::text,'Tu l''as portée jusqu''en haut de la colline, donc tu dois avoir mal partout maintenant, mais franchement, respect.'::text),
(389294,43255,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Onu bütün tepe boyunca taşıdın, yani artık her yerin ağrıyor ..., ama açıkçası helal.'::text,'olmalı'::text,'olabilir'::text,'olamaz'::text,'Onu bütün tepe boyunca taşıdın, yani artık her yerin ağrıyor olmalı, ama açıkçası helal.'::text),
(389295,43255,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Felvitted őt az egész dombon, szóval mostanra ... mindened, de őszintén, respekt.'::text,'biztosan fáj'::text,'fájhat'::text,'nem fájhat'::text,'Felvitted őt az egész dombon, szóval mostanra biztosan fáj mindened, de őszintén, respekt.'::text),
(389298,43256,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Mann, ... Rücken wehtut, trug einen Rucksack und eine Freundin. Toller Plan, offensichtlich.'::text,'dessen'::text,'der'::text,'welcher'::text,'Der Mann, dessen Rücken wehtut, trug einen Rucksack und eine Freundin. Toller Plan, offensichtlich.'::text),
(389302,43256,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чоловік, ... спина болить, ніс рюкзак і подругу. Чудовий план, очевидно.'::text,'чия'::text,'який'::text,'що'::text,'Чоловік, чия спина болить, ніс рюкзак і подругу. Чудовий план, очевидно.'::text),
(389301,43256,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El hombre ... espalda está dolorida cargó una mochila y a una amiga. Gran plan, obviamente.'::text,'cuya'::text,'que'::text,'el cual'::text,'El hombre cuya espalda está dolorida cargó una mochila y a una amiga. Gran plan, obviamente.'::text),
(389300,43256,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''homme ... le dos est douloureux a porté un sac à dos et une amie. Super plan, évidemment.'::text,'dont'::text,'qui'::text,'lequel'::text,'L''homme dont le dos est douloureux a porté un sac à dos et une amie. Super plan, évidemment.'::text),
(389303,43256,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... Sırtı ağrıyan adam hem sırt çantasını hem de bir arkadaşını taşıdı. Harika plan, tabii ki.'::text,''::text,NULL::text,NULL::text,'Sırtı ağrıyan adam hem sırt çantasını hem de bir arkadaşını taşıdı. Harika plan, tabii ki.'::text),
(389304,43256,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A férfi, ... fáj a háta, egy hátizsákot és egy barátnőt cipelt. Remek terv, nyilván.'::text,'akinek'::text,'aki'::text,'amely'::text,'A férfi, akinek fáj a háta, egy hátizsákot és egy barátnőt cipelt. Remek terv, nyilván.'::text),
(389307,43257,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... seines wunden Rückens trug er sie den Hügel hinauf. Makellose Planung, offensichtlich.'::text,'Trotz'::text,'Obwohl'::text,'Wegen'::text,'Trotz seines wunden Rückens trug er sie den Hügel hinauf. Makellose Planung, offensichtlich.'::text),
(389311,43257,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... хвору спину, він заніс її на пагорб. Бездоганне планування, очевидно.'::text,'Попри'::text,'Хоча'::text,'Через'::text,'Попри хвору спину, він заніс її на пагорб. Бездоганне планування, очевидно.'::text),
(389310,43257,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... su espalda dolorida, la subió a la colina. Planificación impecable, obviamente.'::text,'A pesar de'::text,'Aunque'::text,'Debido a'::text,'A pesar de su espalda dolorida, la subió a la colina. Planificación impecable, obviamente.'::text),
(389309,43257,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... son mal de dos, il l''a portée en haut de la colline. Planification impeccable, évidemment.'::text,'Malgré'::text,'Bien que'::text,'À cause de'::text,'Malgré son mal de dos, il l''a portée en haut de la colline. Planification impeccable, évidemment.'::text),
(389312,43257,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ağrıyan sırtına ... onu tepeye taşıdı. Kusursuz planlama, tabii ki.'::text,'rağmen'::text,'halde'::text,'yüzünden'::text,'Ağrıyan sırtına rağmen onu tepeye taşıdı. Kusursuz planlama, tabii ki.'::text),
(389313,43257,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Fájós háta ... felvitte őt a dombra. Hibátlan tervezés, nyilván.'::text,'ellenére'::text,'bár'::text,'miatt'::text,'Fájós háta ellenére felvitte őt a dombra. Hibátlan tervezés, nyilván.'::text),
(389316,43258,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Digga, er wusste, dass ihm nach dem Tragen der Rücken ..., aber er hat''s trotzdem gemacht, ohne Witz.'::text,'wehtun würde'::text,'wehtun wird'::text,'gerade wehtut'::text,'Digga, er wusste, dass ihm nach dem Tragen der Rücken wehtun würde, aber er hat''s trotzdem gemacht, ohne Witz.'::text),
(389320,43258,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, він знав, що після того, як понесе її, спина ..., але все одно це зробив, чесно.'::text,'болітиме'::text,'болітиме'::text,'болить'::text,'Бро, він знав, що після того, як понесе її, спина болітиме, але все одно це зробив, чесно.'::text),
(389319,43258,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, sabía que la espalda le ... después de cargarla, pero lo hizo igual, en serio.'::text,'dolería'::text,'dolerá'::text,'está doliendo'::text,'Tío, sabía que la espalda le dolería después de cargarla, pero lo hizo igual, en serio.'::text),
(389318,43258,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, il savait qu''il ... mal au dos après l''avoir portée, mais il l''a fait quand même, sans mentir.'::text,'aurait'::text,'aura'::text,'est en train d''avoir'::text,'Frère, il savait qu''il aurait mal au dos après l''avoir portée, mais il l''a fait quand même, sans mentir.'::text),
(389321,43258,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, onu taşıdıktan sonra sırtının ... biliyordu ama yine de yaptı, ciddiyim.'::text,'ağrıyacağını'::text,'ağrıyacağını'::text,'ağrıdığını'::text,'Kanka, onu taşıdıktan sonra sırtının ağrıyacağını biliyordu ama yine de yaptı, ciddiyim.'::text),
(389322,43258,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, tudta, hogy a cipelés után ... a háta, de azért megcsinálta, komolyan.'::text,'fájni fog'::text,'fájni fog'::text,'éppen fáj'::text,'Tesó, tudta, hogy a cipelés után fájni fog a háta, de azért megcsinálta, komolyan.'::text),
(389334,43260,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis zum Status-Update um 15 Uhr ... sein Rücken den Großteil der Wanderung wund gewesen.'::text,'war'::text,'ist'::text,'wurde'::text,'Bis zum Status-Update um 15 Uhr war sein Rücken den Großteil der Wanderung wund gewesen.'::text),
(389338,43260,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До оновлення статусу о 15:00 спина в нього ... більшу частину походу.'::text,'боліла'::text,'болить'::text,'боліла'::text,'До оновлення статусу о 15:00 спина в нього боліла більшу частину походу.'::text),
(389337,43260,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para la actualización de estado de las 15:00, la espalda le ... durante la mayor parte de la excursión.'::text,'había dolido'::text,'ha dolido'::text,'estaba doliendo'::text,'Para la actualización de estado de las 15:00, la espalda le había dolido durante la mayor parte de la excursión.'::text),
(389336,43260,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Au point d''avancement de 15 h, il ... mal au dos pendant la majeure partie de la randonnée.'::text,'avait eu'::text,'a eu'::text,'était en train d''avoir'::text,'Au point d''avancement de 15 h, il avait eu mal au dos pendant la majeure partie de la randonnée.'::text),
(389339,43260,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Saat 15.00''teki durum güncellemesine kadar yürüyüşün büyük bölümünde sırtı ...'::text,'ağrımıştı'::text,'ağrıdı'::text,'ağrıyordu'::text,'Saat 15.00''teki durum güncellemesine kadar yürüyüşün büyük bölümünde sırtı ağrımıştı.'::text),
(389340,43260,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A 15 órás státuszfrissítésig a túra nagy részében ... a háta.'::text,'fájt'::text,'fáj'::text,'éppen fájt'::text,'A 15 órás státuszfrissítésig a túra nagy részében fájt a háta.'::text),
(389343,43261,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis zum Gipfel des Hügels ... ihm der Rücken schon über eine Stunde wehgetan haben.'::text,'wird'::text,'wird'::text,'tut'::text,'Bis zum Gipfel des Hügels wird ihm der Rücken schon über eine Stunde wehgetan haben.'::text),
(389347,43261,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До вершини пагорба спина в нього ... вже понад годину.'::text,'болітиме'::text,'болітиме'::text,'болить'::text,'До вершини пагорба спина в нього болітиме вже понад годину.'::text),
(389346,43261,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para cuando llegue a la cima, la espalda le ... durante más de una hora.'::text,'habrá dolido'::text,'dolerá'::text,'duele'::text,'Para cuando llegue a la cima, la espalda le habrá dolido durante más de una hora.'::text),
(389345,43261,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici le sommet de la colline, il ... mal au dos depuis plus d''une heure.'::text,'aura eu'::text,'aura'::text,'a'::text,'D''ici le sommet de la colline, il aura eu mal au dos depuis plus d''une heure.'::text),
(389348,43261,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tepenin zirvesine vardığında sırtı bir saatten uzun süredir ...'::text,'ağrıyor olacak'::text,'ağrıyacak'::text,'ağrıyor'::text,'Tepenin zirvesine vardığında sırtı bir saatten uzun süredir ağrıyor olacak.'::text),
(389349,43261,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire felér a domb tetejére, a háta már több mint egy órája ...'::text,'fáj majd'::text,'fájni fog'::text,'fáj'::text,'Mire felér a domb tetejére, a háta már több mint egy órája fáj majd.'::text),
(377652,41962,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Digga, wenn sie noch eine Handtasche kauft, ... sie keine Hand mehr frei, echt.'::text,'hat'::text,'hätte'::text,'hatte'::text,'Digga, wenn sie noch eine Handtasche kauft, hat sie keine Hand mehr frei, echt.'::text),
(377656,41962,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, якщо вона купить ще одну сумочку, в неї ... жодної вільної руки, реально.'::text,'не залишиться'::text,'не залишилося б'::text,'не залишилося'::text,'Бро, якщо вона купить ще одну сумочку, в неї не залишиться жодної вільної руки, реально.'::text),
(377655,41962,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, si se compra un bolso más, no le ... ninguna mano libre, en serio.'::text,'quedará'::text,'quedaría'::text,'quedó'::text,'Tío, si se compra un bolso más, no le quedará ninguna mano libre, en serio.'::text),
(377654,41962,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, si elle achète encore un sac à main, elle ... plus de main libre, sérieux.'::text,'n''aura'::text,'n''aurait'::text,'n''avait'::text,'Frère, si elle achète encore un sac à main, elle n''aura plus de main libre, sérieux.'::text),
(377657,41962,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, bir çanta daha alırsa hiç boş eli ..., cidden.'::text,'kalmayacak'::text,'kalmazdı'::text,'kalmadı'::text,'Kanka, bir çanta daha alırsa hiç boş eli kalmayacak, cidden.'::text),
(377658,41962,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ha vesz még egy táskát, nem ... szabad keze, komolyan.'::text,'marad'::text,'maradna'::text,'maradt'::text,'Tesó, ha vesz még egy táskát, nem marad szabad keze, komolyan.'::text),
(377661,41963,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn die Handtasche 500 Euro kosten würde, ... sie ihr gesamtes Shoppingbudget verschlingen.'::text,'würde'::text,'wird'::text,'verschlingt'::text,'Wenn die Handtasche 500 Euro kosten würde, würde sie ihr gesamtes Shoppingbudget verschlingen.'::text),
(377665,41963,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби сумочка коштувала 500 євро, вона ... весь її бюджет на покупки.'::text,'з''їла б'::text,'з''їсть'::text,'з''їдає'::text,'Якби сумочка коштувала 500 євро, вона з''їла б весь її бюджет на покупки.'::text),
(377664,41963,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si el bolso costara 500 euros, ... todo su presupuesto de compras.'::text,'se comería'::text,'se comerá'::text,'se come'::text,'Si el bolso costara 500 euros, se comería todo su presupuesto de compras.'::text),
(377663,41963,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si le sac coûtait 500 euros, il ... tout son budget shopping.'::text,'engloutirait'::text,'engloutira'::text,'engloutit'::text,'Si le sac coûtait 500 euros, il engloutirait tout son budget shopping.'::text),
(377666,41963,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çanta 500 euro olsaydı, tüm alışveriş bütçesini ...'::text,'yerdi'::text,'yiyecek'::text,'yiyor'::text,'Çanta 500 euro olsaydı, tüm alışveriş bütçesini yerdi.'::text),
(377667,41963,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a táska 500 euróba kerülne, ... a teljes vásárlási keretét.'::text,'elvinné'::text,'el fogja vinni'::text,'elviszi'::text,'Ha a táska 500 euróba kerülne, elvinné a teljes vásárlási keretét.'::text),
(377670,41964,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die braune Handtasche ... aus Leder gemacht, also ist sie eine Ledertasche.'::text,'ist'::text,'macht'::text,'macht'::text,'Die braune Handtasche ist aus Leder gemacht, also ist sie eine Ledertasche.'::text),
(377674,41964,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коричнева сумочка ... зі шкіри, тож це шкіряна сумочка.'::text,'зроблена'::text,'робить'::text,'робить'::text,'Коричнева сумочка зроблена зі шкіри, тож це шкіряна сумочка.'::text),
(377673,41964,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El bolso marrón ... de cuero, así que es un bolso de cuero.'::text,'está hecho'::text,'hace'::text,'está haciendo'::text,'El bolso marrón está hecho de cuero, así que es un bolso de cuero.'::text),
(377672,41964,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le sac marron ... en cuir, donc c''est un sac en cuir.'::text,'est fait'::text,'fait'::text,'est en train de faire'::text,'Le sac marron est fait en cuir, donc c''est un sac en cuir.'::text),
(377675,41964,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kahverengi çanta deriden ..., yani deri bir çanta.'::text,'yapılmış'::text,'yapıyor'::text,'yapıyor'::text,'Kahverengi çanta deriden yapılmış, yani deri bir çanta.'::text),
(377676,41964,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A barna táska bőrből ..., szóval ez egy bőrtáska.'::text,'készült'::text,'készít'::text,'készít'::text,'A barna táska bőrből készült, szóval ez egy bőrtáska.'::text),
(377679,41965,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Person ... auf der Rolltreppe eine gemusterte Lederhandtasche in die Kamera.'::text,'hält'::text,'wird gehalten'::text,'haltend'::text,'Die Person hält auf der Rolltreppe eine gemusterte Lederhandtasche in die Kamera.'::text),
(377683,41965,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Суб''єктка ... візерункову шкіряну сумочку перед камерою на ескалаторі.'::text,'тримає'::text,'тримається'::text,'тримаючи'::text,'Суб''єктка тримає візерункову шкіряну сумочку перед камерою на ескалаторі.'::text),
(377682,41965,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El sujeto ... un bolso de cuero estampado hacia la cámara en la escalera mecánica.'::text,'sostiene'::text,'es sostenido'::text,'sosteniendo'::text,'El sujeto sostiene un bolso de cuero estampado hacia la cámara en la escalera mecánica.'::text),
(377681,41965,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le sujet ... un sac en cuir à motifs face à la caméra dans l''escalator.'::text,'tient'::text,'est tenu'::text,'tenant'::text,'Le sujet tient un sac en cuir à motifs face à la caméra dans l''escalator.'::text),
(377684,41965,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Denek yürüyen merdivende desenli deri bir çantayı kameraya ...'::text,'tutuyor'::text,'tutuluyor'::text,'tutarak'::text,'Denek yürüyen merdivende desenli deri bir çantayı kameraya tutuyor.'::text),
(377685,41965,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az alany a mozgólépcsőn ... egy mintás bőrtáskát a kamera felé.'::text,'tart'::text,'tartva van'::text,'tartva'::text,'Az alany a mozgólépcsőn tart egy mintás bőrtáskát a kamera felé.'::text),
(377688,41966,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, die Handtasche ... brandneu sein, weil du sie gerade ausgepackt hast.'::text,'muss'::text,'kann nicht'::text,'sollte'::text,'Ehrlich, die Handtasche muss brandneu sein, weil du sie gerade ausgepackt hast.'::text),
(377692,41966,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, ця сумочка ... бути зовсім новою, бо ти щойно її розпакувала.'::text,'мусить'::text,'не може'::text,'має'::text,'Чесно, ця сумочка мусить бути зовсім новою, бо ти щойно її розпакувала.'::text),
(377691,41966,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sinceramente, ese bolso ... ser nuevecito, porque lo acabas de desempaquetar.'::text,'debe de'::text,'no puede'::text,'debería'::text,'Sinceramente, ese bolso debe de ser nuevecito, porque lo acabas de desempaquetar.'::text),
(377690,41966,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, ce sac ... être tout neuf, puisque tu viens de le déballer.'::text,'doit'::text,'ne peut pas'::text,'devrait'::text,'Franchement, ce sac doit être tout neuf, puisque tu viens de le déballer.'::text),
(377693,41966,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası o çanta yepyeni ..., çünkü daha yeni paketinden çıkardın.'::text,'olmalı'::text,'olamaz'::text,'olması lazım'::text,'Açıkçası o çanta yepyeni olmalı, çünkü daha yeni paketinden çıkardın.'::text),
(377694,41966,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, az a táska ... vadonatúj, hiszen most csomagoltad ki.'::text,'biztosan'::text,'nem lehet'::text,'elvileg'::text,'Őszintén, az a táska biztosan vadonatúj, hiszen most csomagoltad ki.'::text),
(377697,41967,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respekt, die Handtasche, ... du ausgesucht hast, hat so ein ikonisches Muster.'::text,'die'::text,'wer'::text,'was'::text,'Respekt, die Handtasche, die du ausgesucht hast, hat so ein ikonisches Muster.'::text),
(377701,41967,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Респект, сумочка, ... ти вибрала, має такий культовий візерунок.'::text,'яку'::text,'хто'::text,'що'::text,'Респект, сумочка, яку ти вибрала, має такий культовий візерунок.'::text),
(377700,41967,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respeto, el bolso ... elegiste tiene un estampado muy icónico.'::text,'que'::text,'quien'::text,'lo que'::text,'Respeto, el bolso que elegiste tiene un estampado muy icónico.'::text),
(377699,41967,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respect, le sac ... tu as choisi a un motif trop iconique.'::text,'que'::text,'qui'::text,'ce que'::text,'Respect, le sac que tu as choisi a un motif trop iconique.'::text),
(377702,41967,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Helal, ... seçtiğin çantanın deseni çok ikonik.'::text,''::text,NULL::text,NULL::text,'Helal, seçtiğin çantanın deseni çok ikonik.'::text),
(377703,41967,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respekt, a táska, ... kiválasztottál, olyan ikonikus mintájú.'::text,'amit'::text,'aki'::text,'ami'::text,'Respekt, a táska, amit kiválasztottál, olyan ikonikus mintájú.'::text),
(377706,41968,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du hast mir gesagt, du ... dir seit Jahren so eine Handtasche gewünscht, und ehrlich, endlich hast du sie.'::text,'hättest'::text,'hast'::text,'wünschst'::text,'Du hast mir gesagt, du hättest dir seit Jahren so eine Handtasche gewünscht, und ehrlich, endlich hast du sie.'::text),
(377710,41968,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти казала мені, що роками ... таку сумочку, і чесно, нарешті вона в тебе.'::text,'хотіла'::text,'хочеш'::text,'хочеш'::text,'Ти казала мені, що роками хотіла таку сумочку, і чесно, нарешті вона в тебе.'::text),
(377709,41968,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Me dijiste que ... un bolso así desde hacía años, y sinceramente, por fin lo tienes.'::text,'habías querido'::text,'has querido'::text,'quieres'::text,'Me dijiste que habías querido un bolso así desde hacía años, y sinceramente, por fin lo tienes.'::text),
(377708,41968,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu m''as dit que tu ... un sac comme ça depuis des années, et franchement, tu l''as enfin eu.'::text,'voulais'::text,'as voulu'::text,'veux'::text,'Tu m''as dit que tu voulais un sac comme ça depuis des années, et franchement, tu l''as enfin eu.'::text),
(377711,41968,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yıllardır böyle bir çanta ... söyledin, ve açıkçası sonunda aldın.'::text,'istediğini'::text,'istediğini'::text,'istediğini'::text,'Yıllardır böyle bir çanta istediğini söyledin, ve açıkçası sonunda aldın.'::text),
(377712,41968,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azt mondtad, évek óta ... egy ilyen táskát, és őszintén, végre megkaptad.'::text,'akartál'::text,'akarsz'::text,'akarsz'::text,'Azt mondtad, évek óta akartál egy ilyen táskát, és őszintén, végre megkaptad.'::text),
(377724,41970,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie scheint mit ihrer neuen Handtasche sehr glücklich ...'::text,'zu sein'::text,'seiend'::text,'sein'::text,'Sie scheint mit ihrer neuen Handtasche sehr glücklich zu sein.'::text),
(377728,41970,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Здається, вона ... дуже задоволена своєю новою сумочкою.'::text,'є'::text,'буття'::text,'бути'::text,'Здається, вона є дуже задоволена своєю новою сумочкою.'::text),
(377727,41970,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Parece ... muy contenta con su bolso nuevo.'::text,'estar'::text,'estando'::text,'estar'::text,'Parece estar muy contenta con su bolso nuevo.'::text),
(377726,41970,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle semble ... très contente de son nouveau sac.'::text,'être'::text,'étant'::text,'être'::text,'Elle semble être très contente de son nouveau sac.'::text),
(377729,41970,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yeni çantasından çok memnun ... benziyor.'::text,'olmaya'::text,'olarak'::text,'ol'::text,'Yeni çantasından çok memnun olmaya benziyor.'::text),
(377730,41970,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Úgy tűnik, ... nagyon boldog az új táskájával.'::text,''::text,NULL::text,NULL::text,'Úgy tűnik, nagyon boldog az új táskájával.'::text),
(377742,41972,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Digga, sie ... stundenlang shoppen, bevor sie die Handtasche gefunden hat, ohne Witz.'::text,'war'::text,'ist'::text,'geht'::text,'Digga, sie war stundenlang shoppen, bevor sie die Handtasche gefunden hat, ohne Witz.'::text),
(377746,41972,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, вона ... годинами, поки не знайшла ту сумочку, чесно.'::text,'шопилася'::text,'шопиться'::text,'шопиться'::text,'Бро, вона шопилася годинами, поки не знайшла ту сумочку, чесно.'::text),
(377745,41972,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, ella ... durante horas antes de encontrar ese bolso, en serio.'::text,'había estado de compras'::text,'ha estado de compras'::text,'va de compras'::text,'Tío, ella había estado de compras durante horas antes de encontrar ese bolso, en serio.'::text),
(377744,41972,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, elle ... du shopping pendant des heures avant de trouver ce sac, sans mentir.'::text,'avait fait'::text,'a fait'::text,'fait'::text,'Frère, elle avait fait du shopping pendant des heures avant de trouver ce sac, sans mentir.'::text),
(377747,41972,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, o çantayı bulana kadar saatlerce ..., cidden.'::text,'alışveriş yapmıştı'::text,'alışveriş yapıyor'::text,'alışveriş yapar'::text,'Kanka, o çantayı bulana kadar saatlerce alışveriş yapmıştı, cidden.'::text),
(377748,41972,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, órákig ..., mielőtt megtalálta azt a táskát, komolyan.'::text,'vásárolt'::text,'vásárol'::text,'vásárol'::text,'Tesó, órákig vásárolt, mielőtt megtalálta azt a táskát, komolyan.'::text),
(386364,42930,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Morgen um 12 Uhr ... sie im Einkaufszentrum shoppen, also wird sie im Einkaufszentrum sein.'::text,'wird'::text,'wird'::text,'geht'::text,'Morgen um 12 Uhr wird sie im Einkaufszentrum shoppen, also wird sie im Einkaufszentrum sein.'::text),
(386368,42930,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Завтра опівдні вона ... в торговому центрі, тож вона буде в торговому центрі.'::text,'робитиме покупки'::text,'зробить покупки'::text,'робить покупки'::text,'Завтра опівдні вона робитиме покупки в торговому центрі, тож вона буде в торговому центрі.'::text),
(386367,42930,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mañana a mediodía ... de compras en el centro comercial, así que estará en el centro comercial.'::text,'estará'::text,'irá'::text,'va'::text,'Mañana a mediodía estará de compras en el centro comercial, así que estará en el centro comercial.'::text),
(386366,42930,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Demain à midi, elle ... au centre commercial, donc elle sera au centre commercial.'::text,'sera en train de faire du shopping'::text,'fera du shopping'::text,'fait du shopping'::text,'Demain à midi, elle sera en train de faire du shopping au centre commercial, donc elle sera au centre commercial.'::text),
(386369,42930,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yarın öğlen AVM''de ..., yani AVM''de olacak.'::text,'alışveriş yapıyor olacak'::text,'alışveriş yapacak'::text,'alışveriş yapar'::text,'Yarın öğlen AVM''de alışveriş yapıyor olacak, yani AVM''de olacak.'::text),
(386370,42930,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Holnap délben a plázában ..., szóval a plázában lesz.'::text,'fog vásárolni'::text,'vásárol majd'::text,'vásárol'::text,'Holnap délben a plázában fog vásárolni, szóval a plázában lesz.'::text),
(386373,42931,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nächsten Samstag um diese Uhrzeit ... die Person vermutlich im selben Einkaufszentrum einkaufen.'::text,'wird'::text,'wird'::text,'kauft'::text,'Nächsten Samstag um diese Uhrzeit wird die Person vermutlich im selben Einkaufszentrum einkaufen.'::text),
(386377,42931,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Наступної суботи в цю годину суб''єктка, імовірно, ... в тому самому торговому центрі.'::text,'робитиме покупки'::text,'зробить покупки'::text,'робить покупки'::text,'Наступної суботи в цю годину суб''єктка, імовірно, робитиме покупки в тому самому торговому центрі.'::text),
(386376,42931,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A esta hora el próximo sábado, el sujeto ... en el mismo centro comercial, presumiblemente.'::text,'estará comprando'::text,'comprará'::text,'está comprando'::text,'A esta hora el próximo sábado, el sujeto estará comprando en el mismo centro comercial, presumiblemente.'::text),
(386375,42931,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'À cette heure-ci samedi prochain, le sujet ... dans le même centre commercial, vraisemblablement.'::text,'sera en train de faire ses achats'::text,'fera ses achats'::text,'fait ses achats'::text,'À cette heure-ci samedi prochain, le sujet sera en train de faire ses achats dans le même centre commercial, vraisemblablement.'::text),
(386378,42931,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gelecek cumartesi bu saatte denek muhtemelen aynı alışveriş merkezinde ...'::text,'alışveriş yapıyor olacak'::text,'alışveriş yapacak'::text,'alışveriş yapıyor'::text,'Gelecek cumartesi bu saatte denek muhtemelen aynı alışveriş merkezinde alışveriş yapıyor olacak.'::text),
(386379,42931,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jövő szombaton ebben az órában az alany feltehetően ugyanabban a bevásárlóközpontban ...'::text,'fog vásárolni'::text,'vásárol majd'::text,'vásárol'::text,'Jövő szombaton ebben az órában az alany feltehetően ugyanabban a bevásárlóközpontban fog vásárolni.'::text),
(386382,42932,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn du so ..., merkt es das ganze Einkaufszentrum, ehrlich.'::text,'shoppst'::text,'geshoppt hast'::text,'shoppen wirst'::text,'Wenn du so shoppst, merkt es das ganze Einkaufszentrum, ehrlich.'::text),
(386386,42932,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коли ти ... отак, увесь торговий центр це помічає, чесно.'::text,'шопишся'::text,'шопилася'::text,'шопитимешся'::text,'Коли ти шопишся отак, увесь торговий центр це помічає, чесно.'::text),
(386385,42932,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si ... así, todo el centro comercial se da cuenta, sinceramente.'::text,'compras'::text,'compraste'::text,'comprarás'::text,'Si compras así, todo el centro comercial se da cuenta, sinceramente.'::text),
