(330548,36728,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Son sac n''est pas encore arrivé, mais il ... encore apparaître. Pas idéal.'::text,'pourrait'::text,'doit'::text,'ne peut pas'::text,'Son sac n''est pas encore arrivé, mais il pourrait encore apparaître. Pas idéal.'::text),
(330551,36728,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çantası henüz gelmedi ama hâlâ ..., pek ideal değil.'::text,'görünebilir'::text,'görünmeli'::text,'görünemez'::text,'Çantası henüz gelmedi ama hâlâ görünebilir, pek ideal değil.'::text),
(330552,36728,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A táskája még nem jött meg, de még ... a szalagon. Nem ideális.'::text,'megjelenhet'::text,'meg kell jelennie'::text,'nem jelenhet meg'::text,'A táskája még nem jött meg, de még megjelenhet a szalagon. Nem ideális.'::text),
(330555,36729,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Rucksack, ... endlich auf dem Band aufgetaucht ist, ist rot.'::text,'der'::text,'wer'::text,'dessen'::text,'Der Rucksack, der endlich auf dem Band aufgetaucht ist, ist rot.'::text),
(330559,36729,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Рюкзак, ... нарешті з''явився на стрічці, червоний.'::text,'який'::text,'хто'::text,'чий'::text,'Рюкзак, який нарешті з''явився на стрічці, червоний.'::text),
(330558,36729,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La mochila ... por fin apareció en la cinta es roja.'::text,'que'::text,'quien'::text,'cuya'::text,'La mochila que por fin apareció en la cinta es roja.'::text),
(330557,36729,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le sac à dos ... est enfin apparu sur le tapis est rouge.'::text,'qui'::text,'qui'::text,'dont'::text,'Le sac à dos qui est enfin apparu sur le tapis est rouge.'::text),
(330560,36729,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sonunda bantta ... görünen sırt çantası kırmızı.'::text,''::text,NULL::text,NULL::text,'Sonunda bantta görünen sırt çantası kırmızı.'::text),
(330561,36729,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A hátizsák, ... végre megjelent a szalagon, piros.'::text,'amely'::text,'aki'::text,'akinek'::text,'A hátizsák, amely végre megjelent a szalagon, piros.'::text),
(330564,36730,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er sagte, sein Rucksack ... endlich auf dem Band aufgetaucht.'::text,'war'::text,'ist'::text,'taucht'::text,'Er sagte, sein Rucksack war endlich auf dem Band aufgetaucht.'::text),
(330568,36730,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він сказав, що його рюкзак нарешті ... на стрічці.'::text,'з''явився'::text,'з''явився'::text,'з''являється'::text,'Він сказав, що його рюкзак нарешті з''явився на стрічці.'::text),
(330567,36730,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dijo que su mochila por fin ... en la cinta.'::text,'había aparecido'::text,'ha aparecido'::text,'aparece'::text,'Dijo que su mochila por fin había aparecido en la cinta.'::text),
(330566,36730,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il a dit que son sac à dos ... sur le tapis, enfin.'::text,'était apparu'::text,'est apparu'::text,'apparaît'::text,'Il a dit que son sac à dos était apparu sur le tapis, enfin.'::text),
(330569,36730,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sırt çantasının sonunda bantta ... söyledi.'::text,'göründüğünü'::text,'göründüğünü'::text,'göründüğünü'::text,'Sırt çantasının sonunda bantta göründüğünü söyledi.'::text),
(330570,36730,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azt mondta, hogy a hátizsákja végre ... a szalagon.'::text,'megjelent'::text,'megjelent'::text,'megjelenik'::text,'Azt mondta, hogy a hátizsákja végre megjelent a szalagon.'::text),
(330573,36731,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ..., darauf zu warten, dass Taschen auftauchen, aber jetzt ist er geduldiger.'::text,'hasste es früher'::text,'hasste es'::text,'war es gewohnt, es zu hassen'::text,'Er hasste es früher, darauf zu warten, dass Taschen auftauchen, aber jetzt ist er geduldiger.'::text),
(330577,36731,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... чекати, поки з''являться сумки, але тепер він терплячіший.'::text,'раніше ненавидів'::text,'ненавидів би'::text,'звик ненавидіти'::text,'Він раніше ненавидів чекати, поки з''являться сумки, але тепер він терплячіший.'::text),
(330576,36731,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él ... esperar a que aparecieran las maletas, pero ahora es más paciente.'::text,'solía odiar'::text,'odiaría'::text,'estaba acostumbrado a odiar'::text,'Él solía odiar esperar a que aparecieran las maletas, pero ahora es más paciente.'::text),
(330575,36731,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... attendre que les bagages apparaissent, mais maintenant il est plus patient.'::text,'détestait'::text,'détesterait'::text,'avait l''habitude de détester'::text,'Il détestait attendre que les bagages apparaissent, mais maintenant il est plus patient.'::text),
(330578,36731,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çantaların çıkmasını beklemekten ..., ama artık daha sabırlı.'::text,'nefret ederdi'::text,'nefret ederdi'::text,'nefret etmeye alışkındı'::text,'Çantaların çıkmasını beklemekten nefret ederdi, ama artık daha sabırlı.'::text),
(330579,36731,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... várni, hogy megjelenjenek a táskák, de most már türelmesebb.'::text,'Régen utált'::text,'Utált volna'::text,'Hozzá volt szokva utálni'::text,'Régen utált várni, hogy megjelenjenek a táskák, de most már türelmesebb.'::text),
(330582,36732,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er will, dass seine Tasche ..., weil er darauf wartet.'::text,'auftaucht'::text,'auftauchend'::text,'auftauchen'::text,'Er will, dass seine Tasche auftaucht, weil er darauf wartet.'::text),
(330586,36732,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він хоче, щоб його сумка ..., бо він на неї чекає.'::text,'з''явилася'::text,'з''являючись'::text,'з''явитися'::text,'Він хоче, щоб його сумка з''явилася, бо він на неї чекає.'::text),
(330585,36732,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quiere que su bolsa ... porque la está esperando.'::text,'aparezca'::text,'apareciendo'::text,'aparecer'::text,'Quiere que su bolsa aparezca porque la está esperando.'::text),
(330584,36732,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il veut que son sac ... parce qu''il l''attend.'::text,'apparaisse'::text,'apparaissant'::text,'apparaître'::text,'Il veut que son sac apparaisse parce qu''il l''attend.'::text),
(330587,36732,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çantasının ... istiyor, çünkü onu bekliyor.'::text,'görünmesini'::text,'görünerek'::text,'görün'::text,'Çantasının görünmesini istiyor, çünkü onu bekliyor.'::text),
(330588,36732,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azt akarja, hogy a táskája ..., mert várja.'::text,'megjelenjen'::text,'megjelenve'::text,'megjelenni'::text,'Azt akarja, hogy a táskája megjelenjen, mert várja.'::text),
(330600,36734,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, dein Rucksack ist auf dem Band aufgetaucht, und ...'::text,'dein Lächeln auch.'::text,'dein Lächeln war es auch.'::text,'dein Lächeln auch nicht.'::text,'Ehrlich, dein Rucksack ist auf dem Band aufgetaucht, und dein Lächeln auch.'::text),
(330604,36734,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, твій рюкзак з''явився на стрічці, і ...'::text,'твоя усмішка теж.'::text,'твоя усмішка теж була.'::text,'твоя усмішка теж ні.'::text,'Чесно, твій рюкзак з''явився на стрічці, і твоя усмішка теж.'::text),
(330603,36734,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sinceramente, tu mochila apareció en la cinta, y ...'::text,'tu sonrisa también.'::text,'tu sonrisa también estaba.'::text,'tu sonrisa tampoco.'::text,'Sinceramente, tu mochila apareció en la cinta, y tu sonrisa también.'::text),
(330602,36734,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, ton sac à dos est apparu sur le tapis, et ...'::text,'ton sourire aussi.'::text,'ton sourire l''était aussi.'::text,'ton sourire non plus.'::text,'Franchement, ton sac à dos est apparu sur le tapis, et ton sourire aussi.'::text),
(330605,36734,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası sırt çantan bantta göründü, ...'::text,'gülüşün de öyle.'::text,'gülüşün de öyleydi.'::text,'gülüşün de görünmedi.'::text,'Açıkçası sırt çantan bantta göründü, gülüşün de öyle.'::text),
(330606,36734,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, a hátizsákod megjelent a szalagon, és ...'::text,'a mosolyod is.'::text,'a mosolyod is az volt.'::text,'a mosolyod sem.'::text,'Őszintén, a hátizsákod megjelent a szalagon, és a mosolyod is.'::text),
(330609,36735,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du ... ewig auf dieses Band gestarrt, bevor dein Rucksack auftauchte. Respekt.'::text,'hattest'::text,'hast'::text,'starrst'::text,'Du hattest ewig auf dieses Band gestarrt, bevor dein Rucksack auftauchte. Respekt.'::text),
(330613,36735,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти ... на ту стрічку цілу вічність, поки не з''явився твій рюкзак. Респект.'::text,'витріщався'::text,'витріщаєшся'::text,'витріщаєшся'::text,'Ти витріщався на ту стрічку цілу вічність, поки не з''явився твій рюкзак. Респект.'::text),
(330612,36735,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... esa cinta durante siglos antes de que apareciera tu mochila. Respeto.'::text,'Habías estado mirando'::text,'Has estado mirando'::text,'Estás mirando'::text,'Habías estado mirando esa cinta durante siglos antes de que apareciera tu mochila. Respeto.'::text),
(330611,36735,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu ... ce tapis pendant des lustres avant que ton sac à dos apparaisse. Respect.'::text,'avais fixé'::text,'as fixé'::text,'fixes'::text,'Tu avais fixé ce tapis pendant des lustres avant que ton sac à dos apparaisse. Respect.'::text),
(330614,36735,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sırt çantan görünene kadar o banda uzun uzun ..., helal.'::text,'bakıyordun'::text,'bakıyorsun'::text,'bakıyorsun'::text,'Sırt çantan görünene kadar o banda uzun uzun bakıyordun, helal.'::text),
(330615,36735,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egy örökkévalóságig ... azt a szalagot, mielőtt megjelent a hátizsákod. Respekt.'::text,'bámultad'::text,'bámulod'::text,'bámulod'::text,'Egy örökkévalóságig bámultad azt a szalagot, mielőtt megjelent a hátizsákod. Respekt.'::text),
(348825,38759,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rate mal, sie meinte, bis Mittag haben sie den ganzen Teig zu kleinen Kugeln ...'::text,'geformt'::text,'formen'::text,'am Formen'::text,'Rate mal, sie meinte, bis Mittag haben sie den ganzen Teig zu kleinen Kugeln geformt.'::text),
(348829,38759,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Уяви, вона сказала, що до обіду вони ... все тісто в маленькі кульки.'::text,'вже зліплять'::text,'зліплять'::text,'ліпитимуть'::text,'Уяви, вона сказала, що до обіду вони вже зліплять все тісто в маленькі кульки.'::text),
(348828,38759,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Adivina qué, dijo que para el mediodía ... toda la masa en bolitas.'::text,'habrán formado'::text,'formarán'::text,'estarán formando'::text,'Adivina qué, dijo que para el mediodía habrán formado toda la masa en bolitas.'::text),
(348827,38759,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Devine quoi, elle a dit que d''ici midi elles ... toute la pâte en petites boules.'::text,'auront façonné'::text,'façonneront'::text,'seront en train de façonner'::text,'Devine quoi, elle a dit que d''ici midi elles auront façonné toute la pâte en petites boules.'::text),
(348830,38759,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bil bakalım ne oldu, öğlene kadar tüm hamuru küçük toplar haline ... söyledi.'::text,'getirmiş olacaklarını'::text,'getireceklerini'::text,'getiriyor olacaklarını'::text,'Bil bakalım ne oldu, öğlene kadar tüm hamuru küçük toplar haline getirmiş olacaklarını söyledi.'::text),
(348831,38759,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Képzeld, azt mondta, délre az összes tésztát kis golyókká ...'::text,'formázták'::text,'formázni fogják'::text,'éppen formázni fogják'::text,'Képzeld, azt mondta, délre az összes tésztát kis golyókká formázták.'::text),
(348834,38760,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Okay, ich hab gehört, um sechs ... sie schon drei Stunden am Stück Teig.'::text,'formen'::text,'formen'::text,'formen'::text,'Okay, ich hab gehört, um sechs formen sie schon drei Stunden am Stück Teig.'::text),
(348838,38760,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коротше, я чула, що о шостій вони ... тісто вже три години поспіль.'::text,'ліпитимуть'::text,'ліпитимуть'::text,'ліпитимуть'::text,'Коротше, я чула, що о шостій вони ліпитимуть тісто вже три години поспіль.'::text),
(348837,38760,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vale, he oído que a las seis ... masa durante tres horas seguidas.'::text,'habrán estado formando'::text,'estarán formando'::text,'formarán'::text,'Vale, he oído que a las seis habrán estado formando masa durante tres horas seguidas.'::text),
(348836,38760,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bon, j''ai entendu dire qu''à six heures, elles ... de la pâte depuis trois heures d''affilée.'::text,'auront façonné'::text,'seront en train de façonner'::text,'façonneront'::text,'Bon, j''ai entendu dire qu''à six heures, elles auront façonné de la pâte depuis trois heures d''affilée.'::text),
(348839,38760,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tamam, duydum ki saat altıda üç saattir aralıksız hamur ...'::text,'şekillendiriyor olacaklar'::text,'şekillendiriyor olacaklar'::text,'şekillendirecekler'::text,'Tamam, duydum ki saat altıda üç saattir aralıksız hamur şekillendiriyor olacaklar.'::text),
(348840,38760,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oké, azt hallottam, hogy hatra már három órája ... megállás nélkül a tésztát.'::text,'formázzák'::text,'formázzák'::text,'formázni fogják'::text,'Oké, azt hallottam, hogy hatra már három órája formázzák megállás nélkül a tésztát.'::text),
(348852,38762,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn sie den Teig nicht in den Ofen geschoben hätten, ... er jetzt immer noch roh.'::text,'wäre'::text,'wäre gewesen'::text,'wird'::text,'Wenn sie den Teig nicht in den Ofen geschoben hätten, wäre er jetzt immer noch roh.'::text),
(348856,38762,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби вони не поставили тісто в духовку, воно зараз ... сирим.'::text,'досі було б'::text,'досі було б'::text,'досі буде'::text,'Якби вони не поставили тісто в духовку, воно зараз досі було б сирим.'::text),
(348855,38762,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si no hubieran metido la masa en el horno, ahora ... cruda.'::text,'seguiría'::text,'habría seguido'::text,'seguirá'::text,'Si no hubieran metido la masa en el horno, ahora seguiría cruda.'::text),
(348854,38762,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si elles n''avaient pas mis la pâte au four, elle ... encore crue maintenant.'::text,'serait'::text,'aurait été'::text,'sera'::text,'Si elles n''avaient pas mis la pâte au four, elle serait encore crue maintenant.'::text),
(348857,38762,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hamuru fırına koymasalardı şimdi hâlâ çiğ ...'::text,'olurdu'::text,'olmuş olurdu'::text,'olacak'::text,'Hamuru fırına koymasalardı şimdi hâlâ çiğ olurdu.'::text),
(348858,38762,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha nem tették volna be a tésztát a sütőbe, most is nyers ...'::text,'lenne'::text,'lett volna'::text,'lesz'::text,'Ha nem tették volna be a tésztát a sütőbe, most is nyers lenne.'::text),
(348861,38763,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Teig soll heute früh am Morgen von Hand ...'::text,'geformt worden sein'::text,'formen'::text,'formend'::text,'Der Teig soll heute früh am Morgen von Hand geformt worden sein.'::text),
(348865,38763,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вважається, що тісто ... вручну сьогодні рано-вранці.'::text,'виліпили'::text,'ліпити'::text,'ліплення'::text,'Вважається, що тісто виліпили вручну сьогодні рано-вранці.'::text),
(348864,38763,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Se cree que la masa ... a mano esta mañana temprano.'::text,'fue formada'::text,'formar'::text,'formando'::text,'Se cree que la masa fue formada a mano esta mañana temprano.'::text),
(348863,38763,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'On pense que la pâte ... à la main tôt ce matin.'::text,'a été façonnée'::text,'façonner'::text,'façonnant'::text,'On pense que la pâte a été façonnée à la main tôt ce matin.'::text),
(348866,38763,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hamurun bu sabah erken saatlerde elle ... düşünülüyor.'::text,'şekillendirildiği'::text,'şekillendirmek'::text,'şekillendirerek'::text,'Hamurun bu sabah erken saatlerde elle şekillendirildiği düşünülüyor.'::text),
(348867,38763,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Úgy gondolják, hogy a tésztát ma kora reggel kézzel ...'::text,'formázták'::text,'formázni'::text,'formázva'::text,'Úgy gondolják, hogy a tésztát ma kora reggel kézzel formázták.'::text),
(348870,38764,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die ältere Frau schlug vor, den Teig in Reihen aufs Blech ...'::text,'zu legen'::text,'zu legen'::text,'gelegt zu haben'::text,'Die ältere Frau schlug vor, den Teig in Reihen aufs Blech zu legen.'::text),
(348874,38764,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Старша жінка запропонувала ... тісто рядами на деко.'::text,'викласти'::text,'викласти'::text,'виклавши'::text,'Старша жінка запропонувала викласти тісто рядами на деко.'::text),
(348873,38764,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La mujer mayor sugirió ... la masa en filas en la bandeja.'::text,'poner'::text,'poner'::text,'haber puesto'::text,'La mujer mayor sugirió poner la masa en filas en la bandeja.'::text),
(348872,38764,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La femme plus âgée a proposé de ... la pâte en rangées sur la plaque.'::text,'mettre'::text,'mettre'::text,'avoir mis'::text,'La femme plus âgée a proposé de mettre la pâte en rangées sur la plaque.'::text),
(348875,38764,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yaşlı kadın hamuru tepsiye sıra sıra ... önerdi.'::text,'dizmeyi'::text,'dizmeyi'::text,'dizmiş olmayı'::text,'Yaşlı kadın hamuru tepsiye sıra sıra dizmeyi önerdi.'::text),
(348876,38764,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az idősebb nő azt javasolta, hogy ... a tésztát sorokban a tepsire.'::text,'tegyék'::text,'tenni'::text,'tették'::text,'Az idősebb nő azt javasolta, hogy tegyék a tésztát sorokban a tepsire.'::text),
(348879,38765,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Teig ... gut aufgegangen sein, da die Croissants golden und bemerkenswert leicht herauskamen.'::text,'muss'::text,'kann nicht'::text,'sollte'::text,'Der Teig muss gut aufgegangen sein, da die Croissants golden und bemerkenswert leicht herauskamen.'::text),
(348883,38765,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Тісто ... добре піднятися, оскільки круасани вийшли золотистими й напрочуд легкими.'::text,'мусило'::text,'не могло'::text,'мало'::text,'Тісто мусило добре піднятися, оскільки круасани вийшли золотистими й напрочуд легкими.'::text),
(348882,38765,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La masa ... subido bien, ya que los cruasanes salieron dorados y notablemente ligeros.'::text,'debió de haber'::text,'no puede haber'::text,'debería haber'::text,'La masa debió de haber subido bien, ya que los cruasanes salieron dorados y notablemente ligeros.'::text),
(348881,38765,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La pâte ... bien lever, puisque les croissants sont sortis dorés et remarquablement légers.'::text,'a dû'::text,'n''a pas pu'::text,'aurait dû'::text,'La pâte a dû bien lever, puisque les croissants sont sortis dorés et remarquablement légers.'::text),
(348884,38765,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kruvasanlar altın rengi ve dikkat çekici derecede hafif çıktığına göre hamur iyi ...'::text,'kabarmış olmalı'::text,'kabarmış olamaz'::text,'kabarmalıydı'::text,'Kruvasanlar altın rengi ve dikkat çekici derecede hafif çıktığına göre hamur iyi kabarmış olmalı.'::text),
(348885,38765,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A tészta ..., hiszen a croissant-ok aranybarnán és feltűnően könnyen jöttek ki.'::text,'biztosan jól megkelt'::text,'nem kelhetett meg jól'::text,'jól meg kellett volna kelnie'::text,'A tészta biztosan jól megkelt, hiszen a croissant-ok aranybarnán és feltűnően könnyen jöttek ki.'::text),
(348888,38766,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nie ... ich so perfekten Teig sich in Croissants verwandeln sehen! Absolut unglaublich!'::text,'habe'::text,'habe'::text,'habe'::text,'Nie habe ich so perfekten Teig sich in Croissants verwandeln sehen! Absolut unglaublich!'::text),
(348892,38766,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ніколи ..., щоб таке ідеальне тісто перетворювалося на круасани! Абсолютно неймовірно!'::text,'я не бачив'::text,'я не бачив'::text,'я не бачив'::text,'Ніколи я не бачив, щоб таке ідеальне тісто перетворювалося на круасани! Абсолютно неймовірно!'::text),
(348891,38766,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Nunca ... una masa tan perfecta convertirse en cruasanes! ¡Absolutamente increíble!'::text,'he visto'::text,'he visto'::text,'he visto'::text,'¡Nunca he visto una masa tan perfecta convertirse en cruasanes! ¡Absolutamente increíble!'::text),
(348890,38766,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jamais je ... une pâte aussi parfaite se transformer en croissants ! Absolument incroyable !'::text,'n''ai vu'::text,'n''ai vu'::text,'n''ai vu'::text,'Jamais je n''ai vu une pâte aussi parfaite se transformer en croissants ! Absolument incroyable !'::text),
(348893,38766,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Böyle mükemmel bir hamurun kruvasana dönüştüğünü hiç ...! Kesinlikle inanılmaz!'::text,'görmedim'::text,'görmedim'::text,'görmedim'::text,'Böyle mükemmel bir hamurun kruvasana dönüştüğünü hiç görmedim! Kesinlikle inanılmaz!'::text),
(348894,38766,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Még soha ... ilyen tökéletes tésztát croissant-ná változni! Abszolút hihetetlen!'::text,'nem láttam'::text,'nem láttam'::text,'nem láttam'::text,'Még soha nem láttam ilyen tökéletes tésztát croissant-ná változni! Abszolút hihetetlen!'::text),
(348897,38767,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ließen den Ofen den Teig goldbraun ..., sonst wäre der ganze Morgen ruiniert gewesen!'::text,'backen'::text,'zu backen'::text,'backend'::text,'Sie ließen den Ofen den Teig goldbraun backen, sonst wäre der ganze Morgen ruiniert gewesen!'::text),
(348901,38767,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вони дали духовці ... тісто до золотистого кольору, інакше весь ранок був би зіпсований!'::text,'випекти'::text,'випекти'::text,'випікаючи'::text,'Вони дали духовці випекти тісто до золотистого кольору, інакше весь ранок був би зіпсований!'::text),
(348900,38767,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Hicieron que el horno ... la masa hasta dorarla, o toda la mañana se habría arruinado!'::text,'horneara'::text,'hornear'::text,'horneando'::text,'¡Hicieron que el horno horneara la masa hasta dorarla, o toda la mañana se habría arruinado!'::text),
(348899,38767,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elles ont laissé le four ... la pâte jusqu''à ce qu''elle dore, sinon toute la matinée aurait été gâchée !'::text,'cuire'::text,'cuire'::text,'cuisant'::text,'Elles ont laissé le four cuire la pâte jusqu''à ce qu''elle dore, sinon toute la matinée aurait été gâchée !'::text),
(348902,38767,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hamuru fırında altın rengi olana kadar ..., yoksa bütün sabah mahvolurdu!'::text,'pişirttiler'::text,'pişirmek'::text,'pişirerek'::text,'Hamuru fırında altın rengi olana kadar pişirttiler, yoksa bütün sabah mahvolurdu!'::text),
(348903,38767,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A sütővel aranybarnára ... a tésztát, különben az egész reggel tönkremegy!'::text,'süttették'::text,'sütni'::text,'sütve'::text,'A sütővel aranybarnára süttették a tésztát, különben az egész reggel tönkremegy!'::text),
(348906,38768,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie wünscht sich, sie ... doppelt so viel Teig gemacht! Diese Croissants werden für immer verschwinden!'::text,'hätte'::text,'machte'::text,'würde'::text,'Sie wünscht sich, sie hätte doppelt so viel Teig gemacht! Diese Croissants werden für immer verschwinden!'::text),
(348910,38768,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби ж вона ... вдвічі більше тіста! Ці круасани зникнуть назавжди!'::text,'зробила'::text,'робила'::text,'зробила б'::text,'Якби ж вона зробила вдвічі більше тіста! Ці круасани зникнуть назавжди!'::text),
(348909,38768,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Ojalá ... el doble de masa! ¡Estos cruasanes van a desaparecer para siempre!'::text,'hubiera hecho'::text,'hiciera'::text,'haría'::text,'¡Ojalá hubiera hecho el doble de masa! ¡Estos cruasanes van a desaparecer para siempre!'::text),
(348908,38768,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle aurait aimé ... deux fois plus de pâte ! Ces croissants vont disparaître pour toujours !'::text,'avoir fait'::text,'faire'::text,'faire'::text,'Elle aurait aimé avoir fait deux fois plus de pâte ! Ces croissants vont disparaître pour toujours !'::text),
(348911,38768,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Keşke iki kat daha fazla hamur ...! Bu kruvasanlar sonsuza dek yok olacak!'::text,'yapsaydı'::text,'yapsa'::text,'yapacak olsa'::text,'Keşke iki kat daha fazla hamur yapsaydı! Bu kruvasanlar sonsuza dek yok olacak!'::text),
(348912,38768,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bárcsak kétszer annyi tésztát ...! Ezek a croissant-ok örökre eltűnnek!'::text,'csinált volna'::text,'csinálna'::text,'fog csinálni'::text,'Bárcsak kétszer annyi tésztát csinált volna! Ezek a croissant-ok örökre eltűnnek!'::text),
(348915,38769,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör mal, angeblich teilt die ältere Frau, ... Teigrezept ein Familiengeheimnis ist, es nie.'::text,'deren'::text,'die'::text,'das'::text,'Hör mal, angeblich teilt die ältere Frau, deren Teigrezept ein Familiengeheimnis ist, es nie.'::text),
(348919,38769,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, кажуть, старша жінка, ... рецепт тіста — родинна таємниця, ніколи ним не ділиться.'::text,'чий'::text,'яка'::text,'який'::text,'Слухай, кажуть, старша жінка, чий рецепт тіста — родинна таємниця, ніколи ним не ділиться.'::text),
(348918,38769,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, al parecer la mujer mayor, ... receta de masa es un secreto familiar, nunca la comparte.'::text,'cuya'::text,'que'::text,'la cual'::text,'Oye, al parecer la mujer mayor, cuya receta de masa es un secreto familiar, nunca la comparte.'::text),
(348917,38769,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, apparemment la femme plus âgée, ... la recette de pâte est un secret de famille, ne la partage jamais.'::text,'dont'::text,'qui'::text,'laquelle'::text,'Écoute, apparemment la femme plus âgée, dont la recette de pâte est un secret de famille, ne la partage jamais.'::text),
(348920,38769,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, güya ... hamur tarifi aile sırrı olan yaşlı kadın onu asla paylaşmıyor.'::text,''::text,NULL::text,NULL::text,'Dinle, güya hamur tarifi aile sırrı olan yaşlı kadın onu asla paylaşmıyor.'::text),
(348921,38769,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, állítólag az idősebb nő, ... tésztareceptje családi titok, soha nem osztja meg.'::text,'akinek a'::text,'aki'::text,'amely'::text,'Figyelj, állítólag az idősebb nő, akinek a tésztareceptje családi titok, soha nem osztja meg.'::text),
(365628,40626,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Sonne ... gerade über der Stadt unter, als sie die Lichterkette anmachte.'::text,'ging'::text,'ging'::text,'ist'::text,'Die Sonne ging gerade über der Stadt unter, als sie die Lichterkette anmachte.'::text),
(365632,40626,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Сонце ... над містом, коли вона ввімкнула гірлянду.'::text,'сідало'::text,'сіло'::text,'сіло'::text,'Сонце сідало над містом, коли вона ввімкнула гірлянду.'::text),
(365631,40626,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El sol ... sobre la ciudad cuando ella encendió la guirnalda de luces.'::text,'se estaba poniendo'::text,'se puso'::text,'se ha puesto'::text,'El sol se estaba poniendo sobre la ciudad cuando ella encendió la guirnalda de luces.'::text),
(365630,40626,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le soleil ... sur la ville quand elle a allumé la guirlande lumineuse.'::text,'se couchait'::text,'s''est couché'::text,'s''est couché'::text,'Le soleil se couchait sur la ville quand elle a allumé la guirlande lumineuse.'::text),
(365633,40626,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Işık zincirini yaktığında güneş şehrin üzerinde ...'::text,'batıyordu'::text,'battı'::text,'batmış'::text,'Işık zincirini yaktığında güneş şehrin üzerinde batıyordu.'::text),
(365634,40626,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A nap éppen ... a város fölött, amikor felkapcsolta a fényfüzért.'::text,'nyugodott'::text,'lenyugodott'::text,'lenyugodott'::text,'A nap éppen nyugodott a város fölött, amikor felkapcsolta a fényfüzért.'::text),
(365637,40627,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Lichterkette ... die Terrasse seit Sonnenuntergang.'::text,'beleuchtet'::text,'beleuchtet'::text,'beleuchtet'::text,'Die Lichterkette beleuchtet die Terrasse seit Sonnenuntergang.'::text),
(365641,40627,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Гірлянда ... терасу від заходу сонця.'::text,'освітлює'::text,'освітлює'::text,'освітлює'::text,'Гірлянда освітлює терасу від заходу сонця.'::text),
(365640,40627,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La guirnalda de luces ... la terraza desde el atardecer.'::text,'ha estado iluminando'::text,'está iluminando'::text,'ilumina'::text,'La guirnalda de luces ha estado iluminando la terraza desde el atardecer.'::text),
(365639,40627,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La guirlande lumineuse ... la terrasse depuis le coucher du soleil.'::text,'éclaire'::text,'éclaire'::text,'éclaire'::text,'La guirlande lumineuse éclaire la terrasse depuis le coucher du soleil.'::text),
(365642,40627,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Işık zinciri gün batımından beri terası ...'::text,'aydınlatıyor'::text,'aydınlatıyor'::text,'aydınlatır'::text,'Işık zinciri gün batımından beri terası aydınlatıyor.'::text),
(365643,40627,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A fényfüzér naplemente óta ... a teraszt.'::text,'világítja meg'::text,'világítja meg'::text,'világítja meg'::text,'A fényfüzér naplemente óta világítja meg a teraszt.'::text),
(365646,40628,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Es ... gerade leicht dunkel, als sie die Lichterkette anmachte. Nicht ideal.'::text,'wurde'::text,'wurde'::text,'ist'::text,'Es wurde gerade leicht dunkel, als sie die Lichterkette anmachte. Nicht ideal.'::text),
(365650,40628,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Трохи ..., коли вона ввімкнула гірлянду. Не ідеально.'::text,'смеркало'::text,'стемніло'::text,'стемніло'::text,'Трохи смеркало, коли вона ввімкнула гірлянду. Не ідеально.'::text),
(365649,40628,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... un poco oscuro cuando encendió la guirnalda. No es lo ideal.'::text,'Se estaba poniendo'::text,'Se puso'::text,'Se ha puesto'::text,'Se estaba poniendo un poco oscuro cuando encendió la guirnalda. No es lo ideal.'::text),
(365648,40628,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... un peu sombre quand elle a allumé la guirlande. Pas idéal.'::text,'commençait à faire'::text,'a fait'::text,'a fait'::text,'Il commençait à faire un peu sombre quand elle a allumé la guirlande. Pas idéal.'::text),
(365651,40628,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Işık zincirini yaktığında hava biraz ..., pek ideal değil.'::text,'kararıyordu'::text,'karardı'::text,'kararmış'::text,'Işık zincirini yaktığında hava biraz kararıyordu, pek ideal değil.'::text),
(365652,40628,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kicsit ..., amikor felkapcsolta a fényfüzért. Nem ideális.'::text,'sötétedett'::text,'besötétedett'::text,'besötétedett'::text,'Kicsit sötétedett, amikor felkapcsolta a fényfüzért. Nem ideális.'::text),
(365655,40629,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... die Lichter diese Woche schon dreimal angemacht. Wirklich bahnbrechend.'::text,'hat'::text,'hat'::text,'machte'::text,'Sie hat die Lichter diese Woche schon dreimal angemacht. Wirklich bahnbrechend.'::text),
(365659,40629,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Цього тижня вона вже ... світло тричі. Справді революційно.'::text,'увімкнула'::text,'вмикала'::text,'увімкнула'::text,'Цього тижня вона вже увімкнула світло тричі. Справді революційно.'::text),
(365658,40629,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Esta semana ya ... las luces tres veces. Verdaderamente revolucionario.'::text,'ha encendido'::text,'ha estado encendiendo'::text,'encendió'::text,'Esta semana ya ha encendido las luces tres veces. Verdaderamente revolucionario.'::text),
(365657,40629,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... les lumières trois fois cette semaine déjà. Vraiment révolutionnaire.'::text,'a allumé'::text,'allume'::text,'a allumé'::text,'Elle a allumé les lumières trois fois cette semaine déjà. Vraiment révolutionnaire.'::text),
(365660,40629,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu hafta ışıkları şimdiden üç kez ..., gerçekten çığır açıcı.'::text,'yaktı'::text,'yakıyor'::text,'yaktı'::text,'Bu hafta ışıkları şimdiden üç kez yaktı, gerçekten çığır açıcı.'::text),
(365661,40629,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ezen a héten már háromszor ... a lámpákat. Igazán úttörő.'::text,'kapcsolta fel'::text,'kapcsolgatta fel'::text,'felkapcsolta'::text,'Ezen a héten már háromszor kapcsolta fel a lámpákat. Igazán úttörő.'::text),
(365664,40630,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als sie die Glühbirnen anmachte, ... sie die Pflanzen schon gegossen. Makellose Routine, eindeutig.'::text,'hatte'::text,'hat'::text,'gießt'::text,'Als sie die Glühbirnen anmachte, hatte sie die Pflanzen schon gegossen. Makellose Routine, eindeutig.'::text),
(365668,40630,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки вона ввімкнула лампочки, вона вже ... рослини. Бездоганна рутина, ясна річ.'::text,'полила'::text,'полила'::text,'поливає'::text,'Поки вона ввімкнула лампочки, вона вже полила рослини. Бездоганна рутина, ясна річ.'::text),
(365667,40630,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para cuando encendió las bombillas, ya ... las plantas. Rutina impecable, claramente.'::text,'había regado'::text,'ha regado'::text,'riega'::text,'Para cuando encendió las bombillas, ya había regado las plantas. Rutina impecable, claramente.'::text),
(365666,40630,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Au moment où elle a allumé les ampoules, elle ... les plantes. Routine impeccable, clairement.'::text,'avait déjà arrosé'::text,'a déjà arrosé'::text,'arrose déjà'::text,'Au moment où elle a allumé les ampoules, elle avait déjà arrosé les plantes. Routine impeccable, clairement.'::text),
(365669,40630,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ampulleri yaktığında bitkileri çoktan ..., kusursuz rutin, belli ki.'::text,'sulamıştı'::text,'suladı'::text,'sular'::text,'Ampulleri yaktığında bitkileri çoktan sulamıştı, kusursuz rutin, belli ki.'::text),
(365670,40630,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire felkapcsolta az izzókat, már ... a növényeket. Hibátlan rutin, egyértelműen.'::text,'meglocsolta'::text,'meglocsolta'::text,'locsolja'::text,'Mire felkapcsolta az izzókat, már meglocsolta a növényeket. Hibátlan rutin, egyértelműen.'::text),
(365673,40631,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Morgen um diese Zeit ... sie wieder die Lichter anknipsen, total besessen!'::text,'wird'::text,'wird'::text,'knipst'::text,'Morgen um diese Zeit wird sie wieder die Lichter anknipsen, total besessen!'::text),
(365677,40631,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Завтра в цей час вона знову ... світло, повністю одержима!'::text,'вмикатиме'::text,'увімкне'::text,'вмикає'::text,'Завтра в цей час вона знову вмикатиме світло, повністю одержима!'::text),
(365676,40631,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Mañana a esta hora ... las luces otra vez, totalmente obsesionada!'::text,'estará encendiendo'::text,'encenderá'::text,'enciende'::text,'¡Mañana a esta hora estará encendiendo las luces otra vez, totalmente obsesionada!'::text),
(365675,40631,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Demain à la même heure, elle ... de nouveau les lumières, complètement obsédée !'::text,'sera en train d''allumer'::text,'allumera'::text,'allume'::text,'Demain à la même heure, elle sera en train d''allumer de nouveau les lumières, complètement obsédée !'::text),
(365678,40631,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yarın bu saatte ışıkları yine ..., tamamen takıntılı!'::text,'yakıyor olacak'::text,'yakacak'::text,'yakıyor'::text,'Yarın bu saatte ışıkları yine yakıyor olacak, tamamen takıntılı!'::text),
(365679,40631,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Holnap ilyenkor újra ... a lámpákat, teljesen megszállottan!'::text,'kapcsolgatni fogja'::text,'fel fogja kapcsolni'::text,'kapcsolja fel'::text,'Holnap ilyenkor újra kapcsolgatni fogja a lámpákat, teljesen megszállottan!'::text),
(365682,40632,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Auf der Terrasse wird es dunkel, eine totale Katastrophe! Warte, ich ... die Lichter an!'::text,'mache'::text,'werde'::text,'mache gerade'::text,'Auf der Terrasse wird es dunkel, eine totale Katastrophe! Warte, ich mache die Lichter an!'::text),
(365686,40632,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'На терасі темніє, повна катастрофа! Стривай, я ... світло!'::text,'увімкну'::text,'вмикатиму'::text,'вмикаю'::text,'На терасі темніє, повна катастрофа! Стривай, я увімкну світло!'::text),
(365685,40632,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡La terraza se está quedando a oscuras, un desastre total! ¡Espera, ... las luces!'::text,'encenderé'::text,'estaré encendiendo'::text,'estoy encendiendo'::text,'¡La terraza se está quedando a oscuras, un desastre total! ¡Espera, encenderé las luces!'::text),
(365684,40632,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La terrasse s''assombrit, une catastrophe totale ! Attends, je ... les lumières !'::text,'vais allumer'::text,'serai en train d''allumer'::text,'suis en train d''allumer'::text,'La terrasse s''assombrit, une catastrophe totale ! Attends, je vais allumer les lumières !'::text),
(365687,40632,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Teras kararıyor, tam bir felaket! Dur, ışıkları ben ...!'::text,'yakarım'::text,'yakıyor olacağım'::text,'yakıyorum'::text,'Teras kararıyor, tam bir felaket! Dur, ışıkları ben yakarım!'::text),
(365688,40632,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sötétedik a teraszon, totális katasztrófa! Várj, ... a lámpákat!'::text,'felkapcsolom'::text,'fel fogom kapcsolni'::text,'kapcsolom fel'::text,'Sötétedik a teraszon, totális katasztrófa! Várj, felkapcsolom a lámpákat!'::text),
(365700,40634,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn sie die Lichterkette jetzt anmacht, ... die Terrasse auch nach Sonnenuntergang hell.'::text,'bleibt'::text,'würde bleiben'::text,'blieb'::text,'Wenn sie die Lichterkette jetzt anmacht, bleibt die Terrasse auch nach Sonnenuntergang hell.'::text),
(365704,40634,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо вона зараз увімкне гірлянду, тераса ... світлою й після заходу сонця.'::text,'залишиться'::text,'залишилася б'::text,'залишилася'::text,'Якщо вона зараз увімкне гірлянду, тераса залишиться світлою й після заходу сонця.'::text),
(365703,40634,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si enciende la guirnalda ahora, la terraza ... iluminada después del atardecer.'::text,'seguirá'::text,'seguiría'::text,'siguió'::text,'Si enciende la guirnalda ahora, la terraza seguirá iluminada después del atardecer.'::text),
(365702,40634,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si elle allume la guirlande maintenant, la terrasse ... éclairée après le coucher du soleil.'::text,'restera'::text,'resterait'::text,'est restée'::text,'Si elle allume la guirlande maintenant, la terrasse restera éclairée après le coucher du soleil.'::text),
(365705,40634,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Işık zincirini şimdi yakarsa teras gün batımından sonra da aydınlık ...'::text,'kalacak'::text,'kalırdı'::text,'kaldı'::text,'Işık zincirini şimdi yakarsa teras gün batımından sonra da aydınlık kalacak.'::text),
(365706,40634,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha most felkapcsolja a fényfüzért, a terasz naplemente után is világos ...'::text,'marad'::text,'maradna'::text,'maradt'::text,'Ha most felkapcsolja a fényfüzért, a terasz naplemente után is világos marad.'::text),
(365709,40635,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Digga, wenn ich so eine Terrasse hätte, ... ich sie jeden Abend beleuchten, echt.'::text,'würde'::text,'werde'::text,'beleuchtete'::text,'Digga, wenn ich so eine Terrasse hätte, würde ich sie jeden Abend beleuchten, echt.'::text),
(365713,40635,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, якби в мене була така тераса, я ... її щовечора, реально.'::text,'освітлював би'::text,'освітлюватиму'::text,'освітлював'::text,'Бро, якби в мене була така тераса, я освітлював би її щовечора, реально.'::text),
(365712,40635,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, si yo tuviera una terraza así, la ... todas las noches, en serio.'::text,'iluminaría'::text,'iluminaré'::text,'iluminé'::text,'Tío, si yo tuviera una terraza así, la iluminaría todas las noches, en serio.'::text),
(365711,40635,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, si j''avais une terrasse comme ça, je ... tous les soirs, sérieux.'::text,'l''illuminerais'::text,'l''illuminerai'::text,'l''ai illuminée'::text,'Frère, si j''avais une terrasse comme ça, je l''illuminerais tous les soirs, sérieux.'::text),
(365714,40635,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, öyle bir terasım olsaydı her akşam ışıl ışıl ..., cidden.'::text,'yapardım'::text,'yapacağım'::text,'yaptım'::text,'Kanka, öyle bir terasım olsaydı her akşam ışıl ışıl yapardım, cidden.'::text),
(365715,40635,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ha nekem lenne egy ilyen teraszom, minden este ..., komolyan.'::text,'kivilágítanám'::text,'ki fogom világítani'::text,'kivilágítottam'::text,'Tesó, ha nekem lenne egy ilyen teraszom, minden este kivilágítanám, komolyan.'::text),
(365718,40636,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Terrasse ... nach Sonnenuntergang von kleinen Glühbirnen beleuchtet.'::text,'wurde'::text,'beleuchtete'::text,'beleuchtet gerade'::text,'Die Terrasse wurde nach Sonnenuntergang von kleinen Glühbirnen beleuchtet.'::text),
(365722,40636,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Тераса ... маленькими лампочками, коли сонце сіло.'::text,'була освітлена'::text,'освітила'::text,'освітлює'::text,'Тераса була освітлена маленькими лампочками, коли сонце сіло.'::text),
(365721,40636,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La terraza ... por pequeñas bombillas después de que se pusiera el sol.'::text,'fue iluminada'::text,'iluminó'::text,'está iluminando'::text,'La terraza fue iluminada por pequeñas bombillas después de que se pusiera el sol.'::text),
(365720,40636,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La terrasse ... par de petites ampoules après le coucher du soleil.'::text,'a été éclairée'::text,'a éclairé'::text,'est en train d''éclairer'::text,'La terrasse a été éclairée par de petites ampoules après le coucher du soleil.'::text),
(365723,40636,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Güneş battıktan sonra teras küçük ampullerle ...'::text,'aydınlatıldı'::text,'aydınlattı'::text,'aydınlatıyor'::text,'Güneş battıktan sonra teras küçük ampullerle aydınlatıldı.'::text),
(365724,40636,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Naplemente után a teraszt apró izzók ...'::text,'világították meg'::text,'világította meg'::text,'világítják meg'::text,'Naplemente után a teraszt apró izzók világították meg.'::text),
(366033,40671,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Geldscheine ... am Schalter von einer Maschine gezählt, bevor sie in die Eingangshalle ging.'::text,'wurden'::text,'zählten'::text,'zählend'::text,'Die Geldscheine wurden am Schalter von einer Maschine gezählt, bevor sie in die Eingangshalle ging.'::text),
(366037,40671,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Банкноти ... машиною біля каси, перш ніж вона зайшла у вестибюль.'::text,'були пораховані'::text,'порахували'::text,'рахуючи'::text,'Банкноти були пораховані машиною біля каси, перш ніж вона зайшла у вестибюль.'::text),
(366036,40671,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los billetes ... por una máquina en el mostrador antes de que ella entrara en el vestíbulo.'::text,'fueron contados'::text,'contaron'::text,'contando'::text,'Los billetes fueron contados por una máquina en el mostrador antes de que ella entrara en el vestíbulo.'::text),
(366035,40671,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les billets ... par une machine au guichet avant qu''elle entre dans le hall.'::text,'ont été comptés'::text,'ont compté'::text,'comptant'::text,'Les billets ont été comptés par une machine au guichet avant qu''elle entre dans le hall.'::text),
(366038,40671,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Lobiye girmeden önce banknotlar gişede bir makine tarafından ...'::text,'sayıldı'::text,'saydı'::text,'sayarak'::text,'Lobiye girmeden önce banknotlar gişede bir makine tarafından sayıldı.'::text),
(366039,40671,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A bankjegyeket egy gép ... meg a pultnál, mielőtt belépett az előcsarnokba.'::text,'számolta'::text,'számolták'::text,'számolva'::text,'A bankjegyeket egy gép számolta meg a pultnál, mielőtt belépett az előcsarnokba.'::text),
(366042,40672,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eine Marmorhalle wie diese ... billig zu putzen sein. Eindeutig eine Billigbank.'::text,'kann nicht'::text,'muss'::text,'sollte'::text,'Eine Marmorhalle wie diese kann nicht billig zu putzen sein. Eindeutig eine Billigbank.'::text),
(366046,40672,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Прибирання такого мармурового вестибюля ... бути дешевим. Явно бюджетний банк.'::text,'не може'::text,'мусить'::text,'має'::text,'Прибирання такого мармурового вестибюля не може бути дешевим. Явно бюджетний банк.'::text),
(366045,40672,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Limpiar un vestíbulo de mármol como este ... ser barato. Claramente un banco low cost.'::text,'no puede'::text,'debe de'::text,'debería'::text,'Limpiar un vestíbulo de mármol como este no puede ser barato. Claramente un banco low cost.'::text),
(366044,40672,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un hall en marbre comme celui-ci ... être bon marché à nettoyer. Clairement une banque low cost.'::text,'ne peut pas'::text,'doit'::text,'devrait'::text,'Un hall en marbre comme celui-ci ne peut pas être bon marché à nettoyer. Clairement une banque low cost.'::text),
(366047,40672,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Böyle mermer bir lobiyi temizlemek ucuz ..., belli ki düşük bütçeli bir banka.'::text,'olamaz'::text,'olmalı'::text,'olması lazım'::text,'Böyle mermer bir lobiyi temizlemek ucuz olamaz, belli ki düşük bütçeli bir banka.'::text),
(366048,40672,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egy ilyen márvány előcsarnok takarítása ... olcsó. Egyértelműen fapados bank.'::text,'nem lehet'::text,'biztosan'::text,'elvileg'::text,'Egy ilyen márvány előcsarnok takarítása nem lehet olcsó. Egyértelműen fapados bank.'::text),
(366051,40673,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Eingangshalle, ... Boden aus Marmor ist, ist eindeutig nur ein bescheidener kleiner Flur.'::text,'deren'::text,'die'::text,'wo'::text,'Die Eingangshalle, deren Boden aus Marmor ist, ist eindeutig nur ein bescheidener kleiner Flur.'::text),
(366055,40673,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вестибюль, ... підлога мармурова, явно лише скромний маленький коридор.'::text,'чия'::text,'який'::text,'де'::text,'Вестибюль, чия підлога мармурова, явно лише скромний маленький коридор.'::text),
(366054,40673,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El vestíbulo, ... suelo es de mármol, es claramente solo un modesto pasillito.'::text,'cuyo'::text,'que'::text,'donde'::text,'El vestíbulo, cuyo suelo es de mármol, es claramente solo un modesto pasillito.'::text),
(366053,40673,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le hall, ... le sol est en marbre, n''est clairement qu''un modeste petit couloir.'::text,'dont'::text,'qui'::text,'où'::text,'Le hall, dont le sol est en marbre, n''est clairement qu''un modeste petit couloir.'::text),
(366056,40673,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... Zemini mermer olan lobi, belli ki mütevazı küçük bir koridor.'::text,''::text,NULL::text,NULL::text,'Zemini mermer olan lobi, belli ki mütevazı küçük bir koridor.'::text),
(366057,40673,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az előcsarnok, ... padlója márvány, egyértelműen csak egy szerény kis folyosó.'::text,'amelynek'::text,'amely'::text,'ahol'::text,'Az előcsarnok, amelynek padlója márvány, egyértelműen csak egy szerény kis folyosó.'::text),
(366060,40674,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Digga, sie hat gesagt, sie ... noch nie so eine riesige Bankhalle gesehen, echt.'::text,'hätte'::text,'hat'::text,'war'::text,'Digga, sie hat gesagt, sie hätte noch nie so eine riesige Bankhalle gesehen, echt.'::text),
(366064,40674,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, вона сказала, що ще ніколи ... такого великого вестибюля банку, реально.'::text,'не бачила'::text,'не бачила'::text,'не була'::text,'Бро, вона сказала, що ще ніколи не бачила такого великого вестибюля банку, реально.'::text),
(366063,40674,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, dijo que nunca ... un vestíbulo de banco tan grande, en serio.'::text,'había visto'::text,'ha visto'::text,'estaba'::text,'Tío, dijo que nunca había visto un vestíbulo de banco tan grande, en serio.'::text),
(366062,40674,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, elle a dit qu''elle ... jamais vu un hall de banque aussi grand, sérieux.'::text,'n''avait'::text,'n''a'::text,'n''était'::text,'Frère, elle a dit qu''elle n''avait jamais vu un hall de banque aussi grand, sérieux.'::text),
(366065,40674,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, hiç bu kadar büyük bir banka lobisi ... söyledi, cidden.'::text,'görmediğini'::text,'görmediğini'::text,'olmadığını'::text,'Kanka, hiç bu kadar büyük bir banka lobisi görmediğini söyledi, cidden.'::text),
(366066,40674,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, azt mondta, még soha ... ekkora banki előcsarnokot, komolyan.'::text,'nem látott'::text,'nem látott'::text,'nem volt'::text,'Tesó, azt mondta, még soha nem látott ekkora banki előcsarnokot, komolyan.'::text),
(366078,40676,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie hat zugesagt, die Eingangshalle um 9 Uhr für den Kunden ...'::text,'zu besuchen'::text,'besuchend'::text,'besuchen'::text,'Sie hat zugesagt, die Eingangshalle um 9 Uhr für den Kunden zu besuchen.'::text),
(366082,40676,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона погодилася ... вестибюль о 9:00 заради клієнта.'::text,'відвідати'::text,'відвідування'::text,'відвідати'::text,'Вона погодилася відвідати вестибюль о 9:00 заради клієнта.'::text),
(366081,40676,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Aceptó ... el vestíbulo a las 9:00 para el cliente.'::text,'visitar'::text,'visitando'::text,'visitar'::text,'Aceptó visitar el vestíbulo a las 9:00 para el cliente.'::text),
(366080,40676,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle a accepté de ... le hall à 9 h pour le client.'::text,'visiter'::text,'visitant'::text,'visiter'::text,'Elle a accepté de visiter le hall à 9 h pour le client.'::text),
(366083,40676,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Müşteri için lobiyi saat 9''da ... kabul etti.'::text,'ziyaret etmeyi'::text,'ziyaret ederek'::text,'ziyaret et'::text,'Müşteri için lobiyi saat 9''da ziyaret etmeyi kabul etti.'::text),
(366084,40676,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Beleegyezett, hogy reggel 9-kor ... az előcsarnokot az ügyfél miatt.'::text,'meglátogatja'::text,'meglátogatás'::text,'meglátogat'::text,'Beleegyezett, hogy reggel 9-kor meglátogatja az előcsarnokot az ügyfél miatt.'::text),
(366087,40677,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Eingangshalle ist groß, weil sie nicht klein ist, ...'::text,'oder?'::text,'oder?'::text,'oder?'::text,'Die Eingangshalle ist groß, weil sie nicht klein ist, oder?'::text),
(366091,40677,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вестибюль великий, бо він не малий, ...'::text,'правда?'::text,'правда?'::text,'правда?'::text,'Вестибюль великий, бо він не малий, правда?'::text),
(366090,40677,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El vestíbulo es grande porque no es pequeño, ...'::text,'¿verdad?'::text,'¿verdad?'::text,'¿verdad?'::text,'El vestíbulo es grande porque no es pequeño, ¿verdad?'::text),
(366089,40677,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le hall est grand parce qu''il n''est pas petit, ...'::text,'n''est-ce pas ?'::text,'n''est-ce pas ?'::text,'n''est-ce pas ?'::text,'Le hall est grand parce qu''il n''est pas petit, n''est-ce pas ?'::text),
(366092,40677,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Lobi büyük çünkü küçük değil, ...'::text,'değil mi?'::text,'değil mi?'::text,'değil mi?'::text,'Lobi büyük çünkü küçük değil, değil mi?'::text),
(366093,40677,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az előcsarnok nagy, mert nem kicsi, ...'::text,'ugye?'::text,'ugye?'::text,'ugye?'::text,'Az előcsarnok nagy, mert nem kicsi, ugye?'::text),
(366096,40678,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Eingangshalle ist nicht klein, und ...'::text,'die Stahltür auch nicht.'::text,'die Stahltür auch.'::text,'die Stahltür auch nicht.'::text,'Die Eingangshalle ist nicht klein, und die Stahltür auch nicht.'::text),
(366100,40678,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вестибюль не малий, і ...'::text,'сталеві двері теж ні.'::text,'сталеві двері теж.'::text,'сталеві двері теж ні.'::text,'Вестибюль не малий, і сталеві двері теж ні.'::text),
(366099,40678,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El vestíbulo no es pequeño, y ...'::text,'la puerta de acero tampoco.'::text,'la puerta de acero también.'::text,'la puerta de acero tampoco.'::text,'El vestíbulo no es pequeño, y la puerta de acero tampoco.'::text),
(366098,40678,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le hall n''est pas petit, et ...'::text,'la porte en acier non plus.'::text,'la porte en acier aussi.'::text,'la porte en acier non plus.'::text,'Le hall n''est pas petit, et la porte en acier non plus.'::text),
(366101,40678,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Lobi küçük değil, ...'::text,'çelik kapı da değil.'::text,'çelik kapı da öyle.'::text,'çelik kapı da değil.'::text,'Lobi küçük değil, çelik kapı da değil.'::text),
(366102,40678,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az előcsarnok nem kicsi, és ...'::text,'az acélajtó sem.'::text,'az acélajtó is.'::text,'az acélajtó sem.'::text,'Az előcsarnok nem kicsi, és az acélajtó sem.'::text),
(366114,40680,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis Mittag ... Hunderte Kunden durch diese Eingangshalle gegangen sein.'::text,'werden'::text,'werden'::text,'gehen'::text,'Bis Mittag werden Hunderte Kunden durch diese Eingangshalle gegangen sein.'::text),
(366118,40680,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До полудня цим вестибюлем ... сотні клієнтів.'::text,'пройдуть'::text,'пройдуть'::text,'ходять'::text,'До полудня цим вестибюлем пройдуть сотні клієнтів.'::text),
(366117,40680,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para el mediodía, cientos de clientes ... por este vestíbulo.'::text,'habrán pasado'::text,'pasarán'::text,'pasan'::text,'Para el mediodía, cientos de clientes habrán pasado por este vestíbulo.'::text),
(366116,40680,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici midi, des centaines de clients ... par ce hall.'::text,'seront passés'::text,'passeront'::text,'passent'::text,'D''ici midi, des centaines de clients seront passés par ce hall.'::text),
(366119,40680,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Öğlene kadar bu lobiden yüzlerce müşteri ...'::text,'geçmiş olacak'::text,'geçecek'::text,'geçer'::text,'Öğlene kadar bu lobiden yüzlerce müşteri geçmiş olacak.'::text),
(366120,40680,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Délre több száz ügyfél ... ezen az előcsarnokon.'::text,'haladt már át'::text,'fog áthaladni'::text,'halad át'::text,'Délre több száz ügyfél haladt már át ezen az előcsarnokon.'::text),
(366123,40681,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respekt, bis zum Mittag ... du schon zwei Stunden durch diese Halle, und du siehst immer noch begeistert aus.'::text,'läufst'::text,'läufst'::text,'läufst'::text,'Respekt, bis zum Mittag läufst du schon zwei Stunden durch diese Halle, und du siehst immer noch begeistert aus.'::text),
(366127,40681,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Респект, до обіду ти ... цим вестибюлем уже дві години, а досі виглядаєш враженою.'::text,'ходитимеш'::text,'ходитимеш'::text,'пройдешся'::text,'Респект, до обіду ти ходитимеш цим вестибюлем уже дві години, а досі виглядаєш враженою.'::text),
(366126,40681,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respeto, para la hora de comer ... dos horas por este vestíbulo, y todavía pareces asombrada.'::text,'habrás estado caminando'::text,'estarás caminando'::text,'caminarás'::text,'Respeto, para la hora de comer habrás estado caminando dos horas por este vestíbulo, y todavía pareces asombrada.'::text),
(366125,40681,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respect, d''ici le déjeuner, tu ... dans ce hall depuis deux heures, et tu as encore l''air émerveillée.'::text,'auras déambulé'::text,'déambuleras'::text,'déambuleras'::text,'Respect, d''ici le déjeuner, tu auras déambulé dans ce hall depuis deux heures, et tu as encore l''air émerveillée.'::text),
(366128,40681,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Helal, öğle yemeğine kadar bu lobide iki saattir ... ve hâlâ büyülenmiş görünüyorsun.'::text,'dolaşıyor olacaksın'::text,'dolaşıyor olacaksın'::text,'dolaşacaksın'::text,'Helal, öğle yemeğine kadar bu lobide iki saattir dolaşıyor olacaksın ve hâlâ büyülenmiş görünüyorsun.'::text),
(366129,40681,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respekt, ebédre már két órája ... ebben az előcsarnokban, és még mindig ámulsz.'::text,'sétálsz'::text,'sétálni fogsz'::text,'sétálni fogsz'::text,'Respekt, ebédre már két órája sétálsz ebben az előcsarnokban, és még mindig ámulsz.'::text),
(334137,37127,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mädel, angeblich ... sein Kumpel im Keller, als sie das Kino fanden.'::text,'zitterte'::text,'zitterte'::text,'hat gezittert'::text,'Mädel, angeblich zitterte sein Kumpel im Keller, als sie das Kino fanden.'::text),
(334141,37127,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, його друг ... у підвалі, коли вони знайшли кінотеатр.'::text,'тремтів'::text,'затремтів'::text,'затремтів'::text,'Подруго, кажуть, його друг тремтів у підвалі, коли вони знайшли кінотеатр.'::text),
(334140,37127,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, al parecer su amigo ... en el sótano cuando encontraron el cine.'::text,'estaba temblando'::text,'tembló'::text,'ha temblado'::text,'Tía, al parecer su amigo estaba temblando en el sótano cuando encontraron el cine.'::text),
(334139,37127,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, apparemment son pote ... au sous-sol quand ils ont trouvé le cinéma.'::text,'grelottait'::text,'a grelotté'::text,'a grelotté'::text,'Meuf, apparemment son pote grelottait au sous-sol quand ils ont trouvé le cinéma.'::text),
(334142,37127,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, güya sinemayı bulduklarında arkadaşı bodrumda ...'::text,'titriyordu'::text,'titredi'::text,'titremiş'::text,'Kızım, güya sinemayı bulduklarında arkadaşı bodrumda titriyordu.'::text),
(334143,37127,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag a haverja ... a pincében, amikor megtalálták a mozit.'::text,'reszketett'::text,'megremegett'::text,'megremegett'::text,'Csajszi, állítólag a haverja reszketett a pincében, amikor megtalálták a mozit.'::text),
(334146,37128,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Farbdosen ... seit Jahren in den Kellerregalen.'::text,'stehen'::text,'stehen'::text,'stehen'::text,'Die Farbdosen stehen seit Jahren in den Kellerregalen.'::text),
(334150,37128,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Банки з фарбою ... на полицях у підвалі вже роками.'::text,'стоять'::text,'стоять'::text,'стоять'::text,'Банки з фарбою стоять на полицях у підвалі вже роками.'::text),
(334149,37128,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Las latas de pintura ... en las estanterías del sótano desde hace años.'::text,'han estado'::text,'están'::text,'están'::text,'Las latas de pintura han estado en las estanterías del sótano desde hace años.'::text),
(334148,37128,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les pots de peinture ... sur les étagères du sous-sol depuis des années.'::text,'traînent'::text,'traînent'::text,'traînent'::text,'Les pots de peinture traînent sur les étagères du sous-sol depuis des années.'::text),
(334151,37128,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Boya kutuları yıllardır bodrum raflarında ...'::text,'duruyor'::text,'duruyor'::text,'durur'::text,'Boya kutuları yıllardır bodrum raflarında duruyor.'::text),
(334152,37128,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A festékes dobozok évek óta ... a pince polcain.'::text,'állnak'::text,'állnak'::text,'állnak'::text,'A festékes dobozok évek óta állnak a pince polcain.'::text),
(334155,37129,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... gerade durch den dunklen Keller, als er die Tür aufstieß.'::text,'gingen'::text,'gingen'::text,'sind gegangen'::text,'Sie gingen gerade durch den dunklen Keller, als er die Tür aufstieß.'::text),
(334159,37129,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вони ... темним підвалом, коли він штовхнув двері.'::text,'йшли'::text,'пройшли'::text,'пройшли'::text,'Вони йшли темним підвалом, коли він штовхнув двері.'::text),
(334158,37129,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... por el sótano oscuro cuando él empujó la puerta.'::text,'Estaban caminando'::text,'Caminaron'::text,'Han caminado'::text,'Estaban caminando por el sótano oscuro cuando él empujó la puerta.'::text),
(334157,37129,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ils ... dans le sous-sol sombre quand il a poussé la porte.'::text,'marchaient'::text,'ont marché'::text,'ont marché'::text,'Ils marchaient dans le sous-sol sombre quand il a poussé la porte.'::text),
(334160,37129,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O kapıyı ittiğinde karanlık bodrumda ...'::text,'yürüyorlardı'::text,'yürüdüler'::text,'yürümüşler'::text,'O kapıyı ittiğinde karanlık bodrumda yürüyorlardı.'::text),
(334161,37129,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Épp ... a sötét pincén keresztül, amikor ő kinyitotta az ajtót.'::text,'mentek'::text,'átmentek'::text,'átmentek'::text,'Épp mentek a sötét pincén keresztül, amikor ő kinyitotta az ajtót.'::text),
(334173,37131,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als das Kellerkino eröffnete, ... er das gesamte Budget von 5.000 Euro ausgegeben.'::text,'hatte'::text,'hat'::text,'gibt'::text,'Als das Kellerkino eröffnete, hatte er das gesamte Budget von 5.000 Euro ausgegeben.'::text),
(334177,37131,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До відкриття кінотеатру в підвалі він ... весь бюджет у 5 000 євро.'::text,'витратив'::text,'витратив'::text,'витрачає'::text,'До відкриття кінотеатру в підвалі він витратив весь бюджет у 5 000 євро.'::text),
(334176,37131,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para cuando abrió el cine del sótano, ... todo el presupuesto de 5.000 euros.'::text,'había gastado'::text,'ha gastado'::text,'gasta'::text,'Para cuando abrió el cine del sótano, había gastado todo el presupuesto de 5.000 euros.'::text),
(334175,37131,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Au moment où le cinéma du sous-sol a ouvert, il ... tout le budget de 5 000 euros.'::text,'avait dépensé'::text,'a dépensé'::text,'dépense'::text,'Au moment où le cinéma du sous-sol a ouvert, il avait dépensé tout le budget de 5 000 euros.'::text),
(334178,37131,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bodrum sineması açıldığında 5.000 euroluk bütçenin tamamını ...'::text,'harcamıştı'::text,'harcadı'::text,'harcar'::text,'Bodrum sineması açıldığında 5.000 euroluk bütçenin tamamını harcamıştı.'::text),
(334179,37131,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire a pincemozi megnyílt, ... az egész 5000 eurós keretet.'::text,'elköltötte'::text,'elköltötte'::text,'költi'::text,'Mire a pincemozi megnyílt, elköltötte az egész 5000 eurós keretet.'::text),
(334182,37132,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... seines Hauses versteckt hinter einer Tür ein Heimkino.'::text,'Der Keller'::text,'Ein Keller'::text,'Keller'::text,'Der Keller seines Hauses versteckt hinter einer Tür ein Heimkino.'::text),
(334186,37132,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... його будинку ховає за дверима домашній кінотеатр.'::text,'Підвал'::text,'Підвал'::text,'Підвал'::text,'Підвал його будинку ховає за дверима домашній кінотеатр.'::text),
(334185,37132,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... de su casa esconde un cine en casa detrás de una puerta.'::text,'El sótano'::text,'Un sótano'::text,'Sótano'::text,'El sótano de su casa esconde un cine en casa detrás de una puerta.'::text),
(334184,37132,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... de sa maison cache un home cinéma derrière une porte.'::text,'Le sous-sol'::text,'Un sous-sol'::text,'Sous-sol'::text,'Le sous-sol de sa maison cache un home cinéma derrière une porte.'::text),
(334187,37132,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Evinin ... bir kapının arkasında ev sineması saklıyor.'::text,'bodrumu'::text,'bir bodrumu'::text,'bodrumu'::text,'Evinin bodrumu bir kapının arkasında ev sineması saklıyor.'::text),
(334188,37132,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A háza ... egy ajtó mögött házimozit rejt.'::text,'pincéje'::text,'egy pincéje'::text,'pincéje'::text,'A háza pincéje egy ajtó mögött házimozit rejt.'::text),
(334191,37133,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... des kalten Lagerraums enthält der Keller tatsächlich ein komplettes Heimkino.'::text,'Trotz'::text,'Obwohl'::text,'Im Falle'::text,'Trotz des kalten Lagerraums enthält der Keller tatsächlich ein komplettes Heimkino.'::text),
(334195,37133,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... холодну комору, підвал насправді містить повноцінний домашній кінотеатр.'::text,'Попри'::text,'Хоча'::text,'У разі'::text,'Попри холодну комору, підвал насправді містить повноцінний домашній кінотеатр.'::text),
(334194,37133,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... el frío trastero, el sótano en realidad contiene un cine en casa completo.'::text,'A pesar de'::text,'Aunque'::text,'En caso de'::text,'A pesar de el frío trastero, el sótano en realidad contiene un cine en casa completo.'::text),
(334193,37133,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... la réserve froide, le sous-sol contient en fait un home cinéma complet.'::text,'Malgré'::text,'Bien que'::text,'En cas de'::text,'Malgré la réserve froide, le sous-sol contient en fait un home cinéma complet.'::text),
(334196,37133,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Soğuk depoya ... bodrum aslında eksiksiz bir ev sineması barındırıyor.'::text,'rağmen'::text,'halde'::text,'durumunda'::text,'Soğuk depoya rağmen bodrum aslında eksiksiz bir ev sineması barındırıyor.'::text),
(334197,37133,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A hideg raktár ... a pince valójában egy teljes házimozit rejt.'::text,'ellenére'::text,'bár'::text,'esetén'::text,'A hideg raktár ellenére a pince valójában egy teljes házimozit rejt.'::text),
(334200,37134,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als er die Tür öffnete, wusste sein Kumpel, dass dieser Keller sein Leben für immer ...!'::text,'verändern würde'::text,'verändern wird'::text,'verändert'::text,'Als er die Tür öffnete, wusste sein Kumpel, dass dieser Keller sein Leben für immer verändern würde!'::text),
(334204,37134,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коли він відчинив двері, його друг знав, що цей підвал ... його життя назавжди!'::text,'змінить'::text,'змінить'::text,'змінює'::text,'Коли він відчинив двері, його друг знав, що цей підвал змінить його життя назавжди!'::text),
(334203,37134,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Cuando abrió la puerta, su amigo supo que este sótano ... su vida para siempre!'::text,'cambiaría'::text,'cambiará'::text,'cambia'::text,'¡Cuando abrió la puerta, su amigo supo que este sótano cambiaría su vida para siempre!'::text),
(334202,37134,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand il a ouvert la porte, son pote a su que ce sous-sol ... sa vie pour toujours !'::text,'changerait'::text,'changera'::text,'change'::text,'Quand il a ouvert la porte, son pote a su que ce sous-sol changerait sa vie pour toujours !'::text),
(334205,37134,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kapıyı açtığında arkadaşı bu bodrumun hayatını sonsuza dek ... biliyordu!'::text,'değiştireceğini'::text,'değiştireceğini'::text,'değiştirdiğini'::text,'Kapıyı açtığında arkadaşı bu bodrumun hayatını sonsuza dek değiştireceğini biliyordu!'::text),
(334206,37134,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amikor kinyitotta az ajtót, a haverja tudta, hogy ez a pince örökre ... az életét!'::text,'meg fogja változtatni'::text,'megváltoztatja'::text,'változtatja'::text,'Amikor kinyitotta az ajtót, a haverja tudta, hogy ez a pince örökre meg fogja változtatni az életét!'::text),
(334209,37135,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sein Kumpel ... schon ganze zehn Minuten in diesem eiskalten Keller! Völlig erfroren!'::text,'zittert'::text,'zittert'::text,'zittert'::text,'Sein Kumpel zittert schon ganze zehn Minuten in diesem eiskalten Keller! Völlig erfroren!'::text),
(334213,37135,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Його друг ... у цьому крижаному підвалі цілих десять хвилин! Геть замерз!'::text,'тремтить'::text,'тремтить'::text,'тремтить'::text,'Його друг тремтить у цьому крижаному підвалі цілих десять хвилин! Геть замерз!'::text),
(334212,37135,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Su amigo ... en este sótano helado desde hace diez minutos enteros! ¡Completamente congelado!'::text,'ha estado temblando'::text,'está temblando'::text,'tiembla'::text,'¡Su amigo ha estado temblando en este sótano helado desde hace diez minutos enteros! ¡Completamente congelado!'::text),
(334211,37135,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Son pote ... dans ce sous-sol glacial depuis dix bonnes minutes ! Complètement gelé !'::text,'grelotte'::text,'grelotte'::text,'grelotte'::text,'Son pote grelotte dans ce sous-sol glacial depuis dix bonnes minutes ! Complètement gelé !'::text),
(334214,37135,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Arkadaşı on dakikadır bu buz gibi bodrumda ...! Tamamen donmuş!'::text,'titriyor'::text,'titriyor'::text,'titrer'::text,'Arkadaşı on dakikadır bu buz gibi bodrumda titriyor! Tamamen donmuş!'::text),
(334215,37135,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A haverja már tíz teljes perce ... ebben a jéghideg pincében! Teljesen megfagyott!'::text,'reszket'::text,'reszket'::text,'reszket'::text,'A haverja már tíz teljes perce reszket ebben a jéghideg pincében! Teljesen megfagyott!'::text),
(334227,37137,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Okay, er hat mir erzählt, nächste Woche um diese Zeit ... sie jeden Abend Filme im Keller.'::text,'schauen'::text,'schauen'::text,'haben geschaut'::text,'Okay, er hat mir erzählt, nächste Woche um diese Zeit schauen sie jeden Abend Filme im Keller.'::text),
(334231,37137,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коротше, він сказав мені, що наступного тижня в цей час вони ... фільми в підвалі щовечора.'::text,'дивитимуться'::text,'дивляться'::text,'дивилися'::text,'Коротше, він сказав мені, що наступного тижня в цей час вони дивитимуться фільми в підвалі щовечора.'::text),
(334230,37137,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vale, me dijo que la semana que viene a esta hora ... películas en el sótano todas las noches.'::text,'estarán viendo'::text,'ven'::text,'han visto'::text,'Vale, me dijo que la semana que viene a esta hora estarán viendo películas en el sótano todas las noches.'::text),
(334229,37137,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bon, il m''a dit que la semaine prochaine à cette heure-ci, ils ... des films au sous-sol tous les soirs.'::text,'seront en train de regarder'::text,'regardent'::text,'ont regardé'::text,'Bon, il m''a dit que la semaine prochaine à cette heure-ci, ils seront en train de regarder des films au sous-sol tous les soirs.'::text),
(334232,37137,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tamam, bana dedi ki gelecek hafta bu saatlerde her akşam bodrumda film ...'::text,'izliyor olacaklarmış'::text,'izliyorlar'::text,'izlediler'::text,'Tamam, bana dedi ki gelecek hafta bu saatlerde her akşam bodrumda film izliyor olacaklarmış.'::text),
(334233,37137,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oké, azt mondta, jövő héten ilyenkor minden este filmeket ... a pincében.'::text,'fognak nézni'::text,'néznek'::text,'néztek'::text,'Oké, azt mondta, jövő héten ilyenkor minden este filmeket fognak nézni a pincében.'::text),
(383187,42577,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn der Lachs noch höher springt, ... der Bär ihn in der Luft.'::text,'fängt'::text,'würde fangen'::text,'fing'::text,'Wenn der Lachs noch höher springt, fängt der Bär ihn in der Luft.'::text),
(383191,42577,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо лосось стрибне ще вище, ведмідь ... його в повітрі.'::text,'зловить'::text,'зловив би'::text,'зловив'::text,'Якщо лосось стрибне ще вище, ведмідь зловить його в повітрі.'::text),
(383190,42577,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si el salmón salta más alto, el oso lo ... en el aire.'::text,'atrapará'::text,'atraparía'::text,'atrapó'::text,'Si el salmón salta más alto, el oso lo atrapará en el aire.'::text),
(383189,42577,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si le saumon saute plus haut, l''ours ... en plein vol.'::text,'l''attrapera'::text,'l''attraperait'::text,'l''a attrapé'::text,'Si le saumon saute plus haut, l''ours l''attrapera en plein vol.'::text),
(383192,42577,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Somon biraz daha yükseğe zıplarsa ayı onu havada ...'::text,'yakalayacak'::text,'yakalardı'::text,'yakaladı'::text,'Somon biraz daha yükseğe zıplarsa ayı onu havada yakalayacak.'::text),
(383193,42577,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a lazac még magasabbra ugrik, a medve a levegőben ...'::text,'el fogja kapni'::text,'elkapná'::text,'elkapta'::text,'Ha a lazac még magasabbra ugrik, a medve a levegőben el fogja kapni.'::text),
(351039,39005,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Morgen um acht ... die zwei Freundinnen auf dem Konzert vor Begeisterung hüpfen.'::text,'werden'::text,'werden'::text,'hüpfen'::text,'Morgen um acht werden die zwei Freundinnen auf dem Konzert vor Begeisterung hüpfen.'::text),
(351043,39005,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Завтра о восьмій ці дві подруги ... від захвату на концерті.'::text,'стрибатимуть'::text,'стрибнуть'::text,'стрибають'::text,'Завтра о восьмій ці дві подруги стрибатимуть від захвату на концерті.'::text),
(351042,39005,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mañana a las ocho, las dos amigas ... de emoción en el concierto.'::text,'estarán saltando'::text,'saltarán'::text,'saltan'::text,'Mañana a las ocho, las dos amigas estarán saltando de emoción en el concierto.'::text),
(351041,39005,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Demain à vingt heures, les deux amies ... d''excitation au concert.'::text,'seront en train de sauter'::text,'sauteront'::text,'sautent'::text,'Demain à vingt heures, les deux amies seront en train de sauter d''excitation au concert.'::text),
(351044,39005,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yarın saat sekizde iki arkadaş konserde heyecandan ...'::text,'zıplıyor olacak'::text,'zıplayacak'::text,'zıplar'::text,'Yarın saat sekizde iki arkadaş konserde heyecandan zıplıyor olacak.'::text),
(351045,39005,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Holnap nyolckor a két barátnő ... az izgalomtól a koncerten.'::text,'ugrálni fog'::text,'ugrani fog'::text,'ugrál'::text,'Holnap nyolckor a két barátnő ugrálni fog az izgalomtól a koncerten.'::text),
(351048,39006,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn die Band ihr Lieblingslied spielt, ... ihre Begeisterung noch größer.'::text,'wird'::text,'würde'::text,'wurde'::text,'Wenn die Band ihr Lieblingslied spielt, wird ihre Begeisterung noch größer.'::text),
(351052,39006,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо гурт зіграє її улюблену пісню, її захват ... ще більшим.'::text,'стане'::text,'став би'::text,'став'::text,'Якщо гурт зіграє її улюблену пісню, її захват стане ще більшим.'::text),
(351051,39006,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la banda toca su canción favorita, su emoción ... aún mayor.'::text,'será'::text,'sería'::text,'fue'::text,'Si la banda toca su canción favorita, su emoción será aún mayor.'::text),
(351050,39006,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si le groupe joue sa chanson préférée, son excitation ... encore plus grande.'::text,'deviendra'::text,'deviendrait'::text,'est devenue'::text,'Si le groupe joue sa chanson préférée, son excitation deviendra encore plus grande.'::text),
(351053,39006,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Grup en sevdiği şarkıyı çalarsa heyecanı daha da ...'::text,'artacak'::text,'artardı'::text,'arttı'::text,'Grup en sevdiği şarkıyı çalarsa heyecanı daha da artacak.'::text),
(351054,39006,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a zenekar a kedvenc dalát játssza, az izgalma még nagyobb ...'::text,'lesz'::text,'lenne'::text,'lett'::text,'Ha a zenekar a kedvenc dalát játssza, az izgalma még nagyobb lesz.'::text),
(351057,39007,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ihre Begeisterung ... dazu, dass sie den ganzen Weg zur Arena rannte.'::text,'führte'::text,'wurde geführt'::text,'führend'::text,'Ihre Begeisterung führte dazu, dass sie den ganzen Weg zur Arena rannte.'::text),
(351061,39007,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Її захват ... те, що вона бігла аж до арени.'::text,'спричинив'::text,'був спричинений'::text,'спричиняючи'::text,'Її захват спричинив те, що вона бігла аж до арени.'::text),
(351060,39007,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Su emoción ... que corriera todo el camino hasta el recinto.'::text,'provocó'::text,'fue provocada'::text,'provocando'::text,'Su emoción provocó que corriera todo el camino hasta el recinto.'::text),
(351059,39007,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Son excitation ... à courir jusqu''à la salle.'::text,'l''a poussée'::text,'a été poussée'::text,'la poussant'::text,'Son excitation l''a poussée à courir jusqu''à la salle.'::text),
(351062,39007,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Heyecanı arenaya kadar bütün yolu koşmasına ...'::text,'neden oldu'::text,'neden olundu'::text,'neden olarak'::text,'Heyecanı arenaya kadar bütün yolu koşmasına neden oldu.'::text),
(351063,39007,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az izgalma ..., hogy egészen az arénáig fusson.'::text,'késztette arra'::text,'arra lett késztetve'::text,'késztetve'::text,'Az izgalma késztette arra, hogy egészen az arénáig fusson.'::text),
(351066,39008,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, sie hüpft total rum, also ... ihre Begeisterung echt sein, ohne Witz.'::text,'muss'::text,'kann nicht'::text,'sollte'::text,'Yo, sie hüpft total rum, also muss ihre Begeisterung echt sein, ohne Witz.'::text),
(351070,39008,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йо, вона скаче як скажена, тож її захват ... бути справжнім, чесно.'::text,'мусить'::text,'не може'::text,'має'::text,'Йо, вона скаче як скажена, тож її захват мусить бути справжнім, чесно.'::text),
(351069,39008,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ey, está dando botes, así que su emoción ... ser real, en serio.'::text,'debe de'::text,'no puede'::text,'debería'::text,'Ey, está dando botes, así que su emoción debe de ser real, en serio.'::text),
(351068,39008,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, elle saute partout, donc son excitation ... être réelle, sans mentir.'::text,'doit'::text,'ne peut pas'::text,'devrait'::text,'Yo, elle saute partout, donc son excitation doit être réelle, sans mentir.'::text),
(351071,39008,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, zıplayıp duruyor, yani heyecanı gerçek ..., cidden.'::text,'olmalı'::text,'olamaz'::text,'olması lazım'::text,'Kanka, zıplayıp duruyor, yani heyecanı gerçek olmalı, cidden.'::text),
(351072,39008,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyu, ugrál, mint egy őrült, szóval az izgalma ... valódi, komolyan.'::text,'biztosan'::text,'nem lehet'::text,'elvileg'::text,'Figyu, ugrál, mint egy őrült, szóval az izgalma biztosan valódi, komolyan.'::text),
(351075,39009,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Arena, ... Kapazität bei 20.000 liegt, war voller Begeisterung.'::text,'deren'::text,'die'::text,'wo'::text,'Die Arena, deren Kapazität bei 20.000 liegt, war voller Begeisterung.'::text),
(351079,39009,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Арена, ... місткість становить 20 000, була сповнена захвату.'::text,'чия'::text,'яка'::text,'де'::text,'Арена, чия місткість становить 20 000, була сповнена захвату.'::text),
(351078,39009,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El recinto, ... capacidad es de 20.000, estaba lleno de emoción.'::text,'cuya'::text,'que'::text,'donde'::text,'El recinto, cuya capacidad es de 20.000, estaba lleno de emoción.'::text),
(351077,39009,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La salle, ... la capacité est de 20 000 places, était pleine d''excitation.'::text,'dont'::text,'qui'::text,'où'::text,'La salle, dont la capacité est de 20 000 places, était pleine d''excitation.'::text),
(351080,39009,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... Kapasitesi 20.000 olan arena heyecanla doluydu.'::text,''::text,NULL::text,NULL::text,'Kapasitesi 20.000 olan arena heyecanla doluydu.'::text),
(351081,39009,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az aréna, ... befogadóképessége 20 000 fő, tele volt izgalommal.'::text,'amelynek'::text,'amely'::text,'ahol'::text,'Az aréna, amelynek befogadóképessége 20 000 fő, tele volt izgalommal.'::text),
(351093,39011,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ihre Begeisterung ... vor Konzerten typischerweise geringer; jetzt ist sie bemerkenswert hoch.'::text,'war früher'::text,'wäre'::text,'war es gewohnt zu sein'::text,'Ihre Begeisterung war früher vor Konzerten typischerweise geringer; jetzt ist sie bemerkenswert hoch.'::text),
(351097,39011,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Її захват перед концертами ... зазвичай нижчим; тепер він надзвичайно високий.'::text,'раніше бував'::text,'бував'::text,'звик бути'::text,'Її захват перед концертами раніше бував зазвичай нижчим; тепер він надзвичайно високий.'::text),
(351096,39011,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Su emoción ... ser normalmente más baja antes de los conciertos; ahora es notablemente alta.'::text,'solía'::text,'solía'::text,'estaba acostumbrada a'::text,'Su emoción solía ser normalmente más baja antes de los conciertos; ahora es notablemente alta.'::text),
(351095,39011,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Son excitation ... d''habitude plus faible avant les concerts ; maintenant, elle est remarquablement élevée.'::text,'était'::text,'serait'::text,'avait l''habitude d''être'::text,'Son excitation était d''habitude plus faible avant les concerts ; maintenant, elle est remarquablement élevée.'::text),
(351098,39011,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Konserlerden önce heyecanı tipik olarak daha düşük ...; şimdi dikkat çekici derecede yüksek.'::text,'olurdu'::text,'olurdu'::text,'olmaya alışkındı'::text,'Konserlerden önce heyecanı tipik olarak daha düşük olurdu; şimdi dikkat çekici derecede yüksek.'::text),
(351099,39011,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az izgalma koncertek előtt jellemzően alacsonyabb ...; most feltűnően magas.'::text,'szokott lenni'::text,'lett volna'::text,'volt hozzászokva, hogy legyen'::text,'Az izgalma koncertek előtt jellemzően alacsonyabb szokott lenni; most feltűnően magas.'::text),
(351102,39012,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie kann absolut nicht aufhören zu ...! Die Begeisterung ist buchstäblich zu viel!'::text,'hüpfen'::text,'hüpfen'::text,'hüpfen'::text,'Sie kann absolut nicht aufhören zu hüpfen! Die Begeisterung ist buchstäblich zu viel!'::text),
(351106,39012,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона абсолютно не може перестати ...! Цей захват — буквально занадто!'::text,'стрибати'::text,'стрибати'::text,'стрибати'::text,'Вона абсолютно не може перестати стрибати! Цей захват — буквально занадто!'::text),
(351105,39012,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Es que no puede dejar de ...! ¡La emoción es literalmente demasiado!'::text,'saltar'::text,'saltar'::text,'saltar'::text,'¡Es que no puede dejar de saltar! ¡La emoción es literalmente demasiado!'::text),
(351104,39012,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle n''arrive absolument pas à arrêter de ... ! L''excitation, c''est littéralement trop !'::text,'sauter'::text,'sauter'::text,'sauter'::text,'Elle n''arrive absolument pas à arrêter de sauter ! L''excitation, c''est littéralement trop !'::text),
(351107,39012,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kesinlikle ... bırakamıyor! Heyecan resmen fazla!'::text,'zıplamayı'::text,'zıplamayı'::text,'zıplamayı'::text,'Kesinlikle zıplamayı bırakamıyor! Heyecan resmen fazla!'::text),
(351108,39012,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egyszerűen képtelen abbahagyni az ...! Az izgalom szó szerint túl sok!'::text,'ugrálást'::text,'ugrálást'::text,'ugrálást'::text,'Egyszerűen képtelen abbahagyni az ugrálást! Az izgalom szó szerint túl sok!'::text),
(351111,39013,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das ist es! Die Begeisterung ist das beste Gefühl überhaupt, ...'::text,'oder?'::text,'oder?'::text,'oder?'::text,'Das ist es! Die Begeisterung ist das beste Gefühl überhaupt, oder?'::text),
(351115,39013,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Оце воно! Захват — найкраще відчуття у світі, ...'::text,'правда?'::text,'правда?'::text,'правда?'::text,'Оце воно! Захват — найкраще відчуття у світі, правда?'::text),
(351114,39013,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Llegó el momento! La emoción es la mejor sensación del mundo, ...'::text,'¿verdad?'::text,'¿verdad?'::text,'¿verdad?'::text,'¡Llegó el momento! La emoción es la mejor sensación del mundo, ¿verdad?'::text),
(351113,39013,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'C''est le moment ! L''excitation est la meilleure sensation au monde, ...'::text,'n''est-ce pas ?'::text,'n''est-ce pas ?'::text,'n''est-ce pas ?'::text,'C''est le moment ! L''excitation est la meilleure sensation au monde, n''est-ce pas ?'::text),
(351116,39013,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İşte bu! Heyecan dünyanın en güzel duygusu, ...'::text,'değil mi?'::text,'değil mi?'::text,'değil mi?'::text,'İşte bu! Heyecan dünyanın en güzel duygusu, değil mi?'::text),
(351117,39013,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ez az! Az izgalom a világ legjobb érzése, ...'::text,'ugye?'::text,'ugye?'::text,'ugye?'::text,'Ez az! Az izgalom a világ legjobb érzése, ugye?'::text),
(351120,39014,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... seit heute Morgen vor Begeisterung, völlig außer Kontrolle!'::text,'zittert'::text,'zittert'::text,'zittert'::text,'Sie zittert seit heute Morgen vor Begeisterung, völlig außer Kontrolle!'::text),
(351124,39014,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... від захвату з самого ранку, повністю без контролю!'::text,'тремтить'::text,'тремтить'::text,'тремтить'::text,'Вона тремтить від захвату з самого ранку, повністю без контролю!'::text),
(351123,39014,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Ella ... de emoción desde esta mañana, totalmente fuera de control!'::text,'ha estado temblando'::text,'está temblando'::text,'tiembla'::text,'¡Ella ha estado temblando de emoción desde esta mañana, totalmente fuera de control!'::text),
(351122,39014,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... d''excitation depuis ce matin, complètement hors de contrôle !'::text,'tremble'::text,'tremble'::text,'tremble'::text,'Elle tremble d''excitation depuis ce matin, complètement hors de contrôle !'::text),
(351125,39014,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sabahtan beri heyecandan ..., tamamen kontrolden çıkmış!'::text,'titriyor'::text,'titriyor'::text,'titrer'::text,'Sabahtan beri heyecandan titriyor, tamamen kontrolden çıkmış!'::text),
(351126,39014,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Reggel óta ... az izgalomtól, teljesen kontrollálhatatlanul!'::text,'remeg'::text,'remeg'::text,'remeg'::text,'Reggel óta remeg az izgalomtól, teljesen kontrollálhatatlanul!'::text),
(371586,41288,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn er seine Gegnerin genauer beobachtet hätte, ... er sein Gebiet nicht verloren.'::text,'hätte'::text,'wird'::text,'hat'::text,'Wenn er seine Gegnerin genauer beobachtet hätte, hätte er sein Gebiet nicht verloren.'::text),
(371590,41288,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби він уважніше стежив за суперницею, він ... своєї території.'::text,'не втратив би'::text,'не втратить'::text,'не втратив'::text,'Якби він уважніше стежив за суперницею, він не втратив би своєї території.'::text),
(371589,41288,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si hubiera vigilado a su rival más de cerca, ... su territorio.'::text,'no habría perdido'::text,'no perderá'::text,'no perdió'::text,'Si hubiera vigilado a su rival más de cerca, no habría perdido su territorio.'::text),
(371588,41288,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'S''il avait surveillé son adversaire de plus près, il ... son territoire.'::text,'n''aurait pas perdu'::text,'ne perdra pas'::text,'n''a pas perdu'::text,'S''il avait surveillé son adversaire de plus près, il n''aurait pas perdu son territoire.'::text),
(371591,41288,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rakibini daha dikkatli izleseydi bölgesini ...'::text,'kaybetmezdi'::text,'kaybetmeyecek'::text,'kaybetmedi'::text,'Rakibini daha dikkatli izleseydi bölgesini kaybetmezdi.'::text),
(371592,41288,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha jobban figyelte volna az ellenfelét, ... a területét.'::text,'nem vesztette volna el'::text,'nem fogja elveszíteni'::text,'nem vesztette el'::text,'Ha jobban figyelte volna az ellenfelét, nem vesztette volna el a területét.'::text),
(371595,41289,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn seine Gegnerin diese Figur nicht gezogen hätte, ... er jetzt nicht so geschockt.'::text,'wäre'::text,'wäre gewesen'::text,'wird'::text,'Wenn seine Gegnerin diese Figur nicht gezogen hätte, wäre er jetzt nicht so geschockt.'::text),
(371599,41289,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби його суперниця не зробила хід тією фігуркою, він зараз ... таким шокованим.'::text,'не був би'::text,'не був би'::text,'не буде'::text,'Якби його суперниця не зробила хід тією фігуркою, він зараз не був би таким шокованим.'::text),
(371598,41289,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si su rival no hubiera movido esa ficha, ahora ... tan en shock.'::text,'no estaría'::text,'no habría estado'::text,'no estará'::text,'Si su rival no hubiera movido esa ficha, ahora no estaría tan en shock.'::text),
(371597,41289,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si son adversaire n''avait pas déplacé ce pion, il ... aussi choqué maintenant.'::text,'ne serait pas'::text,'n''aurait pas été'::text,'ne sera pas'::text,'Si son adversaire n''avait pas déplacé ce pion, il ne serait pas aussi choqué maintenant.'::text),
(371600,41289,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rakibi o taşı oynatmasaydı şimdi bu kadar şokta ...'::text,'olmazdı'::text,'olmamış olurdu'::text,'olmayacak'::text,'Rakibi o taşı oynatmasaydı şimdi bu kadar şokta olmazdı.'::text),
(371601,41289,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha az ellenfele nem lépett volna azzal a bábuval, most ... ennyire sokkolt.'::text,'nem lenne'::text,'nem lett volna'::text,'nem lesz'::text,'Ha az ellenfele nem lépett volna azzal a bábuval, most nem lenne ennyire sokkolt.'::text),
(371613,41291,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, du hast bestritten, deinen Gegner ..., aber dieses Lächeln sagt alles.'::text,'reingelegt zu haben'::text,'reinzulegen'::text,'legtest rein'::text,'Ehrlich, du hast bestritten, deinen Gegner reingelegt zu haben, aber dieses Lächeln sagt alles.'::text),
(371617,41291,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, ти заперечила, що ... свого суперника, але ця усмішка все каже.'::text,'обдурила'::text,'обдурити'::text,'обдурила'::text,'Чесно, ти заперечила, що обдурила свого суперника, але ця усмішка все каже.'::text),
(371616,41291,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sinceramente, negaste ... a tu rival, pero esa sonrisa lo dice todo.'::text,'haber engañado'::text,'engañar'::text,'engañaste'::text,'Sinceramente, negaste haber engañado a tu rival, pero esa sonrisa lo dice todo.'::text),
(371615,41291,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, tu as nié ... ton adversaire, mais ce sourire en dit long.'::text,'avoir piégé'::text,'piéger'::text,'as piégé'::text,'Franchement, tu as nié avoir piégé ton adversaire, mais ce sourire en dit long.'::text),
(371618,41291,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası rakibini ... inkâr ettin ama o gülümseme her şeyi anlatıyor.'::text,'kandırdığını'::text,'kandırmayı'::text,'kandırdın'::text,'Açıkçası rakibini kandırdığını inkâr ettin ama o gülümseme her şeyi anlatıyor.'::text),
(371619,41291,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, tagadtad, hogy ... az ellenfeledet, de az a mosoly mindent elárul.'::text,'átverted'::text,'átverni'::text,'átverted'::text,'Őszintén, tagadtad, hogy átverted az ellenfeledet, de az a mosoly mindent elárul.'::text),
(371622,41292,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respekt, du ... diesen Zug ewig geplant haben; dein Gegner hatte keine Chance.'::text,'musst'::text,'solltest'::text,'kannst nicht'::text,'Respekt, du musst diesen Zug ewig geplant haben; dein Gegner hatte keine Chance.'::text),
(371626,41292,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Респект, ти ... цей хід цілу вічність; твій суперник не мав шансів.'::text,'мабуть планувала'::text,'мала б спланувати'::text,'не могла планувати'::text,'Респект, ти мабуть планувала цей хід цілу вічність; твій суперник не мав шансів.'::text),
(371625,41292,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respeto, ... planeado esa jugada durante siglos; tu rival no tenía ninguna oportunidad.'::text,'debes de haber'::text,'deberías haber'::text,'no puedes haber'::text,'Respeto, debes de haber planeado esa jugada durante siglos; tu rival no tenía ninguna oportunidad.'::text),
(371624,41292,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respect, tu ... préparer ce coup depuis des lustres ; ton adversaire n''avait aucune chance.'::text,'as dû'::text,'aurais dû'::text,'n''as pas pu'::text,'Respect, tu as dû préparer ce coup depuis des lustres ; ton adversaire n''avait aucune chance.'::text),
(371627,41292,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Helal, o hamleyi uzun zamandır ...; rakibinin hiç şansı yoktu.'::text,'planlamış olmalısın'::text,'planlamalıydın'::text,'planlamış olamazsın'::text,'Helal, o hamleyi uzun zamandır planlamış olmalısın; rakibinin hiç şansı yoktu.'::text),
(371628,41292,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respekt, ... ezt a lépést egy örökkévalóságig; az ellenfelednek esélye sem volt.'::text,'biztosan tervezted'::text,'tervezned kellett volna'::text,'nem tervezhetted'::text,'Respekt, biztosan tervezted ezt a lépést egy örökkévalóságig; az ellenfelednek esélye sem volt.'::text),
(371631,41293,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nie zuvor ... er seine Gegnerin eine Figur so leise ziehen sehen.'::text,'hatte'::text,'hatte'::text,'hatte'::text,'Nie zuvor hatte er seine Gegnerin eine Figur so leise ziehen sehen.'::text),
(371635,41293,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ніколи раніше він ..., щоб суперниця так тихо пересувала фігурку.'::text,'не бачив'::text,'не бачив'::text,'не бачив'::text,'Ніколи раніше він не бачив, щоб суперниця так тихо пересувала фігурку.'::text),
(371634,41293,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nunca antes ... a su rival mover una ficha tan sigilosamente.'::text,'había visto'::text,'había visto'::text,'había visto'::text,'Nunca antes había visto a su rival mover una ficha tan sigilosamente.'::text),
(371633,41293,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jamais auparavant il ... son adversaire déplacer un pion aussi discrètement.'::text,'n''avait vu'::text,'n''avait vu'::text,'n''avait vu'::text,'Jamais auparavant il n''avait vu son adversaire déplacer un pion aussi discrètement.'::text),
(371636,41293,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rakibinin bir taşı bu kadar sessizce oynattığını daha önce hiç ...'::text,'görmemişti'::text,'görmemişti'::text,'görmemişti'::text,'Rakibinin bir taşı bu kadar sessizce oynattığını daha önce hiç görmemişti.'::text),
(371637,41293,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Soha korábban ... az ellenfelét ilyen csendben lépni egy bábuval.'::text,'nem látta'::text,'nem látta'::text,'nem látta'::text,'Soha korábban nem látta az ellenfelét ilyen csendben lépni egy bábuval.'::text),
(371640,41294,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie brachte ihren Gegner dazu, seine Figur ..., bevor sie angriff.'::text,'zu ziehen'::text,'ziehen'::text,'ziehend'::text,'Sie brachte ihren Gegner dazu, seine Figur zu ziehen, bevor sie angriff.'::text),
(371644,41294,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона змусила суперника ... фігурку, перш ніж атакувати.'::text,'пересунути'::text,'пересунути'::text,'пересуваючи'::text,'Вона змусила суперника пересунути фігурку, перш ніж атакувати.'::text),
(371643,41294,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Consiguió que su rival ... su ficha antes de atacar.'::text,'moviera'::text,'mover'::text,'moviendo'::text,'Consiguió que su rival moviera su ficha antes de atacar.'::text),
(371642,41294,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle a poussé son adversaire à ... son pion avant d''attaquer.'::text,'déplacer'::text,'déplacer'::text,'déplaçant'::text,'Elle a poussé son adversaire à déplacer son pion avant d''attaquer.'::text),
(371645,41294,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Saldırmadan önce rakibinin taşını ... sağladı.'::text,'oynatmasını'::text,'oynatmasını'::text,'oynatarak'::text,'Saldırmadan önce rakibinin taşını oynatmasını sağladı.'::text),
(371646,41294,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rávette az ellenfelét, hogy ... a bábujával, mielőtt támadott.'::text,'lépjen'::text,'lépni'::text,'lépve'::text,'Rávette az ellenfelét, hogy lépjen a bábujával, mielőtt támadott.'::text),
(371649,41295,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er wünscht sich, seine Gegnerin ... diese Figur nicht in sein Gebiet gezogen.'::text,'hätte'::text,'zog'::text,'würde'::text,'Er wünscht sich, seine Gegnerin hätte diese Figur nicht in sein Gebiet gezogen.'::text),
(371653,41295,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він хотів би, щоб його суперниця ... ту фігурку на його територію.'::text,'не пересунула'::text,'не пересувала'::text,'не пересувала б'::text,'Він хотів би, щоб його суперниця не пересунула ту фігурку на його територію.'::text),
(371652,41295,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él desearía que su rival no ... esa ficha a su territorio.'::text,'hubiera movido'::text,'moviera'::text,'movería'::text,'Él desearía que su rival no hubiera movido esa ficha a su territorio.'::text),
(371651,41295,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il aimerait que son adversaire ... ce pion sur son territoire.'::text,'n''ait pas déplacé'::text,'ne déplace pas'::text,'ne déplacerait pas'::text,'Il aimerait que son adversaire n''ait pas déplacé ce pion sur son territoire.'::text),
(371654,41295,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Keşke rakibi o taşı bölgesine ... diye düşünüyor.'::text,'oynatmasaydı'::text,'oynatmasa'::text,'oynatmayacak olsa'::text,'Keşke rakibi o taşı bölgesine oynatmasaydı diye düşünüyor.'::text),
(371655,41295,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azt kívánja, bárcsak az ellenfele ... át azt a bábut a területére.'::text,'ne tolta volna'::text,'ne tolná'::text,'nem tolná'::text,'Azt kívánja, bárcsak az ellenfele ne tolta volna át azt a bábut a területére.'::text),
(371658,41296,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Seine Gegnerin, ... Zug sein Gebiet zerstört hat, lächelte nur. Der schlimmste Verrat!'::text,'deren'::text,'die'::text,'welche'::text,'Seine Gegnerin, deren Zug sein Gebiet zerstört hat, lächelte nur. Der schlimmste Verrat!'::text),
(371662,41296,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Його суперниця, ... хід знищив його територію, лише всміхнулася. Найгірша зрада!'::text,'чий'::text,'яка'::text,'котра'::text,'Його суперниця, чий хід знищив його територію, лише всміхнулася. Найгірша зрада!'::text),
(371661,41296,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Su rival, ... jugada destruyó su territorio, solo sonrió. ¡La peor traición!'::text,'cuya'::text,'que'::text,'la cual'::text,'Su rival, cuya jugada destruyó su territorio, solo sonrió. ¡La peor traición!'::text),
(371660,41296,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Son adversaire, ... le coup a détruit son territoire, s''est contentée de sourire. La pire des trahisons !'::text,'dont'::text,'qui'::text,'laquelle'::text,'Son adversaire, dont le coup a détruit son territoire, s''est contentée de sourire. La pire des trahisons !'::text),
(371663,41296,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... Hamlesi bölgesini yok eden rakibi sadece gülümsedi. En büyük ihanet!'::text,''::text,NULL::text,NULL::text,'Hamlesi bölgesini yok eden rakibi sadece gülümsedi. En büyük ihanet!'::text),
(371664,41296,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az ellenfele, ... lépése lerombolta a területét, csak mosolygott. A legnagyobb árulás!'::text,'akinek a'::text,'aki'::text,'amely'::text,'Az ellenfele, akinek a lépése lerombolta a területét, csak mosolygott. A legnagyobb árulás!'::text),
(371667,41297,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie spielen jeden Freitag nach ... Brettspiele, und heute Abend hat ihn seine Gegnerin zerstört!'::text,'dem Abendessen'::text,'dem Abendessen'::text,'einem Abendessen'::text,'Sie spielen jeden Freitag nach dem Abendessen Brettspiele, und heute Abend hat ihn seine Gegnerin zerstört!'::text),
(371671,41297,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вони щоп''ятниці грають у настільні ігри після ..., а сьогодні суперниця його розгромила!'::text,'вечері'::text,'вечері'::text,'вечері'::text,'Вони щоп''ятниці грають у настільні ігри після вечері, а сьогодні суперниця його розгромила!'::text),
(371670,41297,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Juegan a juegos de mesa después de ... todos los viernes, y esta noche su rival lo ha destrozado!'::text,'cenar'::text,'la cena'::text,'una cena'::text,'¡Juegan a juegos de mesa después de cenar todos los viernes, y esta noche su rival lo ha destrozado!'::text),
(371669,41297,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ils jouent à des jeux de société après ... tous les vendredis, et ce soir son adversaire l''a écrasé !'::text,'le dîner'::text,'le dîner'::text,'un dîner'::text,'Ils jouent à des jeux de société après le dîner tous les vendredis, et ce soir son adversaire l''a écrasé !'::text),
(371672,41297,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Her cuma ... sonra kutu oyunları oynuyorlar ve bu akşam rakibi onu ezip geçti!'::text,'yemekten'::text,'yemekten'::text,'bir yemekten'::text,'Her cuma yemekten sonra kutu oyunları oynuyorlar ve bu akşam rakibi onu ezip geçti!'::text),
(371673,41297,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Minden pénteken ... után társasoznak, és ma este az ellenfele szétszedte!'::text,'vacsora'::text,'a vacsora'::text,'egy vacsora'::text,'Minden pénteken vacsora után társasoznak, és ma este az ellenfele szétszedte!'::text),
(371676,41298,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... seines sorgfältigen Plans zerstörte seine Gegnerin sein Gebiet mit einem Zug!'::text,'Trotz'::text,'Obwohl'::text,'Dank'::text,'Trotz seines sorgfältigen Plans zerstörte seine Gegnerin sein Gebiet mit einem Zug!'::text),
(371680,41298,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... його ретельний план, суперниця знищила його територію одним ходом!'::text,'Попри'::text,'Хоча'::text,'Завдяки'::text,'Попри його ретельний план, суперниця знищила його територію одним ходом!'::text),
(371679,41298,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡... su cuidadoso plan, su rival destruyó su territorio en una sola jugada!'::text,'A pesar de'::text,'Aunque'::text,'Gracias a'::text,'¡A pesar de su cuidadoso plan, su rival destruyó su territorio en una sola jugada!'::text),
(371678,41298,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... son plan minutieux, son adversaire a détruit son territoire en un seul coup !'::text,'Malgré'::text,'Bien que'::text,'Grâce à'::text,'Malgré son plan minutieux, son adversaire a détruit son territoire en un seul coup !'::text),
(371681,41298,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Özenli planına ... rakibi bölgesini tek hamlede yok etti!'::text,'rağmen'::text,'halde'::text,'sayesinde'::text,'Özenli planına rağmen rakibi bölgesini tek hamlede yok etti!'::text),
(371682,41298,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gondos terve ... az ellenfele egyetlen lépéssel lerombolta a területét!'::text,'ellenére'::text,'bár'::text,'révén'::text,'Gondos terve ellenére az ellenfele egyetlen lépéssel lerombolta a területét!'::text)
) v(id, eid, lang, n_intro_text, n_correct_answer, n_distractor_1, n_distractor_2, n_full_sentence, o_intro_text, o_correct_answer, o_distractor_1, o_distractor_2, o_full_sentence)
where l.id = v.id and l.exercise_id = v.eid and l.language_code = v.lang and l.intro_text is not distinct from v.o_intro_text and l.correct_answer is not distinct from v.o_correct_answer and l.distractor_1 is not distinct from v.o_distractor_1 and l.distractor_2 is not distinct from v.o_distractor_2 and l.full_sentence is not distinct from v.o_full_sentence
returning l.id;
